INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C1','math',6,2,'u6',2,'원기둥의 뜻 — 각기둥·각뿔을 되짚고, 서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라 하며 직사각형을 한 변을 기준으로 한 바퀴 돌려 만들 수 있음을 알기',ARRAY['6수03-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C2','math',6,2,'u6',3,'원기둥의 구성 요소 — 서로 평행하고 합동인 두 원(밑면 2개), 두 밑면과 만나는 굽은 면(옆면), 두 밑면 사이의 거리(높이)를 알고 높이는 밑면에 수직으로 재기',ARRAY['6수03-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C3','math',6,2,'u6',4,'원기둥의 전개도 — 합동인 원 2개와 직사각형 1개로 이루어지고, 옆면의 가로는 밑면의 둘레((지름) × (원주율)), 세로는 원기둥의 높이와 같음을 알고 길이 구하기',ARRAY['6수03-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C4','math',6,2,'u6',5,'원기둥의 전개도 가려내기 — 옆면이 직사각형이고, 두 밑면이 서로 합동인 원이며, 옆면을 사이에 두고 마주 보는 위치에 있어야 전개도가 됨을 알기',ARRAY['6수03-06']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C5','math',6,2,'u6',6,'원뿔의 뜻 — 한 원을 면으로 하는 입체도형을 원뿔이라 하고, 직각삼각형을 직각을 낀 한 변을 기준으로 한 바퀴 돌려 만들 수 있으며 원기둥·각뿔과 구별하기',ARRAY['6수03-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C6','math',6,2,'u6',7,'원뿔의 구성 요소 — 밑면(1개)·옆면·원뿔의 꼭짓점·모선(꼭짓점과 밑면 둘레의 한 점을 이은 선분, 무수히 많고 길이가 같음)·높이(꼭짓점에서 밑면에 수직으로 내린 선분의 길이)를 알고 모선이 높이보다 긺을 알기',ARRAY['6수03-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C7','math',6,2,'u6',8,'구 — 반원을 지름을 기준으로 한 바퀴 돌려 만든 입체도형을 구라 하고, 구의 중심(1개)·구의 반지름(무수히 많고 길이가 같음)을 알며 원기둥·원뿔·구를 위·앞·옆에서 본 모양을 견주기',ARRAY['6수03-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u6-C8','math',6,2,'u6',9,'앞에서 본 모양 — 원뿔은 삼각형(밑변 = 밑면의 지름, 높이 = 원뿔의 높이), 원기둥은 직사각형(가로 = 밑면의 지름, 세로 = 높이)임을 알고 넓이·둘레를 구하거나 넓이로 모르는 길이를 되짚기',ARRAY['6수03-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X01','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5']::text[],'각기둥·각뿔과 원기둥·원뿔을 혼동한다(밑면이 다각형인지 원인지 보지 않는다)','밑면이 원인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X02','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C2','M6-2-u6-C4']::text[],'원기둥의 두 원이 서로 평행하고 합동이어야 한다는 조건 가운데 하나를 빠뜨린다','평행하고 합동인 두 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X03','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5','M6-2-u6-C7']::text[],'한 바퀴 돌려 만드는 평면도형을 혼동한다(직사각형→원기둥, 직각삼각형→원뿔, 반원→구)','무엇을 돌렸나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X04','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C5']::text[],'돌릴 때 막대에 붙인 변과 뻗어 나간 변의 역할(높이·밑면의 반지름)을 바꾸거나 반지름을 지름으로 본다','뻗은 변 = 반지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X05','math',6,'u6',ARRAY['M6-2-u6-C2','M6-2-u6-C6']::text[],'밑면을 「밑에 있는 면」으로만 보거나 원기둥(2개)·원뿔(1개)의 밑면 수를 혼동한다','원기둥 2개, 원뿔 1개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X06','math',6,'u6',ARRAY['M6-2-u6-C2']::text[],'원기둥의 높이를 비스듬히 재거나 밑면의 지름·옆면의 둘레와 혼동한다','밑면에 수직으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X07','math',6,'u6',ARRAY['M6-2-u6-C2','M6-2-u6-C6','M6-2-u6-C7']::text[],'원기둥·구에 꼭짓점·모서리가 있다고 보거나 원뿔의 꼭짓점 수를 잘못 센다','굽은 면엔 모서리가 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X08','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'전개도에서 옆면의 가로를 밑면의 지름이나 (반지름) × (원주율)로 본다','가로 = 밑면의 둘레') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X09','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'전개도에서 옆면의 가로와 세로가 원기둥의 어디와 같은지 바꾸어 본다','세로 = 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X10','math',6,'u6',ARRAY['M6-2-u6-C3']::text[],'옆면의 가로로 밑면의 지름·반지름을 구할 때 곱셈·나눗셈을 거꾸로 하거나 반지름과 지름을 혼동한다','가로 ÷ 3.14 = 지름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X11','math',6,'u6',ARRAY['M6-2-u6-C4']::text[],'옆면이 직사각형이 아닌(기울어진) 그림도 원기둥의 전개도라고 본다','옆면은 직사각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X12','math',6,'u6',ARRAY['M6-2-u6-C4']::text[],'두 밑면이 옆면의 같은 쪽에 있어 접으면 겹치는 것을 알아차리지 못한다','마주 보는 위치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X13','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C4']::text[],'전개도의 밑면을 원 1개로, 또는 옆면을 원·삼각형으로 생각한다','원 2개 + 직사각형 1개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X14','math',6,'u6',ARRAY['M6-2-u6-C5','M6-2-u6-C6']::text[],'원기둥과 원뿔을 혼동한다(원이 두 개인지 한 개인지, 뾰족한 점이 있는지 보지 않는다)','원 하나·뾰족한 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X15','math',6,'u6',ARRAY['M6-2-u6-C6','M6-2-u6-C8']::text[],'원뿔의 모선과 높이를 혼동한다(모선을 높이로 쓰거나 높이가 모선보다 길다고 본다)','모선은 비스듬히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X16','math',6,'u6',ARRAY['M6-2-u6-C6']::text[],'원뿔의 모선이 하나뿐이라고 보거나 모선마다 길이가 다르다고 본다','모선은 무수히, 길이는 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X17','math',6,'u6',ARRAY['M6-2-u6-C7']::text[],'구의 반지름이 방향마다 다르다고 보거나 구의 중심이 여러 개라고 본다','중심 1개, 반지름은 모두 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X18','math',6,'u6',ARRAY['M6-2-u6-C7','M6-2-u6-C8']::text[],'원기둥·원뿔·구를 위·앞·옆에서 본 모양을 혼동한다','위에서는 모두 원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X19','math',6,'u6',ARRAY['M6-2-u6-C1','M6-2-u6-C2','M6-2-u6-C3','M6-2-u6-C4','M6-2-u6-C5','M6-2-u6-C6','M6-2-u6-C7','M6-2-u6-C8']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔알맞은, 반지름↔지름, 아닌↔맞는','물음의 「잘못·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u6-X20','math',6,'u6',ARRAY['M6-2-u6-C3','M6-2-u6-C8']::text[],'앞모양 넓이에서 삼각형의 ÷ 2를 빠뜨리거나 밑변을 반지름으로 두는 등 넓이·길이 계산을 잘못한다','삼각형은 ÷ 2') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#1','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','원기둥은 어떤 입체도형인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"원기둥은 어떤 입체도형인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","correct":true},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X01"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X03"},{"t":"한 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["원기둥의 뜻을 떠올려요.","원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."],"variant_rule":{"alt":[{"stem":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원기둥","correct":true},{"t":"각기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X14"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]},{"stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"원기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 각기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#2','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'mc','auto','직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."],"variant_rule":{"alt":[{"stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."]},{"stem":"지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 구가 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#3','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'sa','auto','사각기둥의 면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C1","difficulty":1,"kind":"sa","stem":"사각기둥의 면은 모두 몇 개인가요?","answer":["6"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 사각형이에요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"variant_rule":{"alt":[{"stem":"삼각기둥의 모서리는 모두 몇 개인가요?","answer":["9"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 삼각형이에요.","한 밑면의 변 3개가 위아래로 두 번, 옆 모서리가 3개 — 3 × 3 = 9개예요."]},{"stem":"오각기둥의 꼭짓점은 모두 몇 개인가요?","answer":["10"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 오각형이에요.","한 밑면의 꼭짓점 5개가 위아래로 두 번 — 5 × 2 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#4','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',1,'sa','auto','사각뿔의 꼭짓점은 모두 몇 개인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":1,"kind":"sa","stem":"사각뿔의 꼭짓점은 모두 몇 개인가요?","answer":["5"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 사각형이에요.","밑면의 꼭짓점 4개와 각뿔의 꼭짓점 1개 — 4 + 1 = 5개예요."],"variant_rule":{"alt":[{"stem":"삼각뿔의 면은 모두 몇 개인가요?","answer":["4"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 삼각형이에요.","밑면 1개와 옆면 3개 — 3 + 1 = 4개예요."]},{"stem":"오각뿔의 모서리는 모두 몇 개인가요?","answer":["10"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 오각형이에요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#5','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":5,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 면이 원이 아니라 다각형이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X01"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X01"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 서로 평행하고 합동인 육각형인 상자」를 이 조건에 하나씩 대어 봐요.","두 면이 원이 아니라 다각형이어서 원기둥이 아니에요."]},{"stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#6','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'sa','auto','가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 3 × 2 = 6 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 7 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 세로 7 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."]},{"stem":"가로 6 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 세로 9 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 6 × 2 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#7','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'mc','auto','직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?',ARRAY['M6-2-u6-X04','M6-2-u6-X06']::text[],true,'{"seq":7,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."],"variant_rule":{"alt":[{"stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에서 뻗어 나간 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"밑면의 반지름","correct":true},{"t":"높이","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]},{"stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#8','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'ox','auto','원기둥의 두 원은 서로 평행하고 합동이에요.',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":8,"concept":"M6-2-u6-C1","difficulty":2,"kind":"ox","stem":"원기둥의 두 원은 서로 평행하고 합동이에요.","answer":"O","reason_options":[{"t":"원기둥은 서로 평행하고 합동인 두 원을 면으로 하기 때문에","correct":true},{"t":"원기둥의 두 원은 크기가 달라도 되기 때문에","mis":"M6-2-u6-X02"}],"mis":"M6-2-u6-X02","explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."],"variant_rule":{"alt":[{"stem":"두 면이 원이면 모두 원기둥이에요.","answer":"X","reason_options":[{"t":"두 원이 서로 평행하고 합동이어야 원기둥이기 때문에","correct":true},{"t":"원이 두 개 있으면 원기둥이라고 정했기 때문에","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]},{"stem":"밑면이 원인 기둥 모양도 각기둥이라고 불러요.","answer":"X","reason_options":[{"t":"각기둥의 밑면은 다각형이고 원은 다각형이 아니기 때문에","correct":true},{"t":"기둥 모양은 모두 각기둥이기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#9','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',2,'sa','auto','가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 라 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 — 이 가운데 원기둥 모양은 몇 개인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 라 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["2"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 라예요.","모두 2개예요."],"mis":"M6-2-u6-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 북 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["1"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가예요.","모두 1개예요."]},{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 다 서로 평행하고 합동인 두 원을 면으로 하는 북 · 라 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["3"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 나, 다예요.","모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_basic#10','math',6,2,'u6','L02','g6_2_math_u6_L02_basic','lesson_basic','M6-2-u6-C1',3,'mc','auto','다음 가운데 원기둥 모양은 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X01']::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 원기둥 모양은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄","correct":true},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X02"},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"두 원이 비스듬히 잘려 평행하지 않은 통","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄」이 원기둥이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥 모양은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔","correct":true},{"t":"두 원이 비스듬히 잘려 평행하지 않은 통","mis":"M6-2-u6-X02"},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔」이 원기둥이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥 모양은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 북","correct":true},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X02"},{"t":"한 원을 면으로 하고 뾰족한 점이 있는 고깔모자","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「서로 평행하고 합동인 두 원을 면으로 하는 북」이 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#1','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',2,'sa','auto','가로 4 cm, 세로 10 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 10 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["막대에 붙인 세로 10 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 4 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 3 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 높이는 몇 cm인가요?","answer":["3"],"explanation":["막대에 붙인 세로 3 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 7 cm는 밑면의 반지름이 돼요.","그래서 높이는 3 cm예요."]},{"stem":"가로 5 cm, 세로 8 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["막대에 붙인 세로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#2','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',2,'sa','auto','육각기둥의 모서리는 모두 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"육각기둥의 모서리는 모두 몇 개인가요?","answer":["18"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 육각형이에요.","한 밑면의 변 6개가 위아래로 두 번, 옆 모서리가 6개 — 6 × 3 = 18개예요."],"variant_rule":{"alt":[{"stem":"칠각기둥의 면은 모두 몇 개인가요?","answer":["9"],"explanation":["6학년 1학기에 배운 각기둥을 떠올려요.","밑면의 모양이 칠각형이에요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."]},{"stem":"팔각뿔의 모서리는 모두 몇 개인가요?","answer":["16"],"explanation":["6학년 1학기에 배운 각뿔을 떠올려요.","밑면의 모양이 팔각형이에요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#3','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'error','auto','원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C1","difficulty":3,"kind":"error","stem":"원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"순달 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"지석 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「두 면이 원이기만 하면 원기둥이야.」","correct":true,"mis_target":"M6-2-u6-X02"},{"t":"나린 — 「두 원은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「직사각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「밑면이 원이라 각기둥과는 이름이 달라.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥이 되려면 두 원이 서로 평행하고 합동이어야 해요.","위쪽 원이 더 작은 컵처럼 두 면이 원이어도 원기둥이 아닌 것이 있어요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#4','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C1","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"직사각형을 한 바퀴","r":"원기둥"},{"l":"직각삼각형을 한 바퀴","r":"원뿔"},{"l":"반원을 한 바퀴","r":"구"}],"mis":"M6-2-u6-X03","explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"막대에 붙인 변","r":"높이"},{"l":"뻗어 나간 변","r":"밑면의 반지름"},{"l":"뻗어 나간 변의 2배","r":"밑면의 지름"}],"explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"두 면이 평행하고 합동인 다각형","r":"각기둥"},{"l":"두 면이 평행하고 합동인 원","r":"원기둥"},{"l":"한 원을 면으로 하는 뿔","r":"원뿔"}],"explanation":["직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","막대에 붙인 변은 높이, 뻗은 변은 밑면의 반지름이에요.","밑면이 다각형이면 각기둥, 원이면 원기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#5','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'ox','auto','직사각형을 한 변을 기준으로 한 바퀴 돌리면 원기둥이 돼요.',ARRAY['M6-2-u6-X03']::text[],true,'{"seq":5,"concept":"M6-2-u6-C1","difficulty":3,"kind":"ox","stem":"직사각형을 한 변을 기준으로 한 바퀴 돌리면 원기둥이 돼요.","answer":"O","reason_options":[{"t":"돌린 변은 높이, 뻗은 변은 밑면의 반지름이 되기 때문에","correct":true},{"t":"직사각형의 네 변이 모두 원이 되기 때문에","mis":"M6-2-u6-X03"}],"mis":"M6-2-u6-X03","explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."],"variant_rule":{"alt":[{"stem":"직각삼각형을 한 바퀴 돌리면 원기둥이 돼요.","answer":"X","reason_options":[{"t":"직각삼각형을 돌리면 뾰족한 점이 생겨 원뿔이 되기 때문에","correct":true},{"t":"직각삼각형에도 직각이 있어 원기둥이 되기 때문에","mis":"M6-2-u6-X03"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]},{"stem":"원기둥과 각기둥은 모두 서로 평행하고 합동인 두 면이 있어요.","answer":"O","reason_options":[{"t":"두 밑면이 서로 평행하고 합동이라는 점이 같기 때문에","correct":true},{"t":"원기둥과 각기둥은 밑면의 모양까지 같기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","각기둥은 밑면이 다각형, 원기둥은 밑면이 원이에요.","직사각형을 한 바퀴 돌리면 원기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#6','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'sa','auto','가로 6 cm, 세로 4 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C1","difficulty":3,"kind":"sa","stem":"가로 6 cm, 세로 4 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 가로 6 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 9 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["막대에 붙인 가로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 9 × 2 = 18 cm예요."]},{"stem":"가로 8 cm, 세로 3 cm인 직사각형 모양의 종이를 가로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["14"],"explanation":["막대에 붙인 가로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름 6 cm와 높이 8 cm — 6 + 8 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#7','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',3,'mc','auto','「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":7,"concept":"M6-2-u6-C1","difficulty":3,"kind":"mc","stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."]},{"stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#8','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'sa','auto','가로 7 cm, 세로 12 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C1","difficulty":4,"kind":"sa","stem":"가로 7 cm, 세로 12 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["26"],"explanation":["막대에 붙인 세로 12 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 7 cm는 밑면의 반지름이 돼요.","지름 14 cm와 높이 12 cm — 14 + 12 = 26 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["23"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","지름 18 cm와 높이 5 cm — 18 + 5 = 23 cm예요."]},{"stem":"가로 4 cm, 세로 15 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["23"],"explanation":["막대에 붙인 세로 15 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름 8 cm와 높이 15 cm — 8 + 15 = 23 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#9','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'sa','auto','가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 · 마 서로 평행하고 합동인 두 원을 면으로 하는 북 — 이 가운데 원기둥 모양은 몇 개인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":4,"kind":"sa","stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 위쪽 원이 아래쪽 원보다 작은 컵 · 다 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 · 마 서로 평행하고 합동인 두 원을 면으로 하는 북 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["3"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 다, 마예요.","모두 3개예요."],"mis":"M6-2-u6-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 나 서로 평행하고 합동인 두 원을 면으로 하는 북 · 다 밑면이 오각형이고 옆면이 모두 삼각형인 탑 지붕 · 라 위쪽 원이 아래쪽 원보다 작은 컵 · 마 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["1"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 나예요.","모두 1개예요."]},{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 나 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 다 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 라 두 원이 비스듬히 잘려 평행하지 않은 통 · 마 굽은 면으로만 둘러싸인 구슬 — 이 가운데 원기둥 모양은 몇 개인가요?","answer":["2"],"explanation":["원기둥의 뜻에 하나씩 대어 봐요.","원기둥인 것은 가, 다예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L02_challenge#10','math',6,2,'u6','L02','g6_2_math_u6_L02_challenge','lesson_challenge','M6-2-u6-C1',4,'essay','teacher','간식을 담은 통 가운데 마주 보는 두 면이 모두 원인데 위쪽 원이 아래쪽 원보다 작은 통이 있어요. 이 통이 원기둥이 아닌 까닭을 원기둥의 뜻을 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":4,"kind":"essay","stem":"간식을 담은 통 가운데 마주 보는 두 면이 모두 원인데 위쪽 원이 아래쪽 원보다 작은 통이 있어요. 이 통이 원기둥이 아닌 까닭을 원기둥의 뜻을 써서 설명해 보세요.","answer_guide":{"answer":"예: 원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이다. 이 통은 두 면이 원이고 평행하지만, 위쪽 원이 더 작아 두 원이 합동이 아니므로 원기둥이 아니다.","scoring_points":["원기둥의 뜻(서로 평행하고 합동인 두 원)을 썼는가","두 원이 합동이 아님을 짚었는가","그래서 원기둥이 아니라고 결론지었는가"]},"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","위쪽 원이 더 작으면 두 원이 합동이 아니에요.","그래서 원기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#1','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'mc','auto','원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06','M6-2-u6-X15']::text[],true,'{"seq":1,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","서로 평행하고 합동인 두 원을 밑면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#2','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'sa','auto','밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]},{"stem":"밑면의 반지름이 9 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","9 × 2 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#3','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'sa','auto','원기둥의 밑면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"원기둥의 밑면은 모두 몇 개인가요?","answer":["2"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥의 밑면은 서로 평행하고 합동인 두 원 — 2개예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥의 평평한 면은 모두 몇 개인가요?","answer":["2"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥에서 평평한 면은 두 밑면뿐 — 2개예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."]},{"stem":"원기둥의 옆면은 모두 몇 개인가요?","answer":["1"],"explanation":["원기둥을 손에 들고 면을 하나씩 짚어 봐요.","원기둥의 옆면은 굽은 면 하나예요.","각기둥처럼 옆면이 여러 개로 나뉘지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#4','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',1,'mc','auto','원기둥의 높이는 무엇인가요?',ARRAY['M6-2-u6-X06']::text[],true,'{"seq":4,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥의 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X06"},{"t":"옆면의 둘레","mis":"M6-2-u6-X06"},{"t":"밑면의 반지름","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자와 삼각자를 밑면에 수직으로 대어 두 밑면 사이의 거리를 재요","correct":true},{"t":"밑면의 지름을 재요","mis":"M6-2-u6-X06"},{"t":"옆면을 따라 비스듬히 줄자를 대어 재요","mis":"M6-2-u6-X06"},{"t":"밑면의 둘레를 재요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]},{"stem":"원기둥의 높이를 비스듬히 재면 어떻게 되나요?","options":[{"t":"두 밑면 사이의 거리보다 길게 나와요","correct":true},{"t":"두 밑면 사이의 거리보다 짧게 나와요","mis":"M6-2-u6-X06"},{"t":"언제나 같은 값이 나와요","mis":"M6-2-u6-X06"},{"t":"밑면의 지름과 같아져요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#5','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'sa','auto','밑면의 지름이 6 cm이고 높이가 12 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 지름이 6 cm이고 높이가 12 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["15"],"explanation":["밑면의 반지름은 6 ÷ 2 = 3 cm예요.","높이는 12 cm예요.","3 + 12 = 15 cm예요."],"mis":"M6-2-u6-X19","variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm이고 높이가 7 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["12"],"explanation":["밑면의 반지름은 10 ÷ 2 = 5 cm예요.","높이는 7 cm예요.","5 + 7 = 12 cm예요."]},{"stem":"밑면의 지름이 8 cm이고 높이가 15 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["19"],"explanation":["밑면의 반지름은 8 ÷ 2 = 4 cm예요.","높이는 15 cm예요.","4 + 15 = 19 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#6','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'sa','auto','밑면의 반지름이 4 cm이고 높이가 8 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 4 cm이고 높이가 8 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["16"],"explanation":["밑면의 지름은 4 × 2 = 8 cm예요.","높이는 8 cm예요.","8 + 8 = 16 cm예요."],"mis":"M6-2-u6-X19","variant_rule":{"alt":[{"stem":"밑면의 반지름이 5 cm이고 높이가 9 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["19"],"explanation":["밑면의 지름은 5 × 2 = 10 cm예요.","높이는 9 cm예요.","10 + 9 = 19 cm예요."]},{"stem":"밑면의 반지름이 3 cm이고 높이가 11 cm인 원기둥이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["17"],"explanation":["밑면의 지름은 3 × 2 = 6 cm예요.","높이는 11 cm예요.","6 + 11 = 17 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#7','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'ox','auto','원기둥의 밑면은 언제나 아래쪽에 있는 면 하나예요.',ARRAY['M6-2-u6-X05']::text[],true,'{"seq":7,"concept":"M6-2-u6-C2","difficulty":2,"kind":"ox","stem":"원기둥의 밑면은 언제나 아래쪽에 있는 면 하나예요.","answer":"X","reason_options":[{"t":"밑면은 「기본이 되는 면」 — 서로 평행하고 합동인 두 원 모두 밑면이기 때문에","correct":true},{"t":"밑면이라는 이름처럼 밑에 있는 면만 밑면이기 때문에","mis":"M6-2-u6-X05"}],"mis":"M6-2-u6-X05","explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 옆면은 굽은 면이에요.","answer":"O","reason_options":[{"t":"두 밑면과 만나는 면이 둥글게 굽어 있기 때문에","correct":true},{"t":"원기둥의 옆면은 직사각형 여러 개이기 때문에","mis":"M6-2-u6-X05"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]},{"stem":"원기둥의 높이는 밑면에 수직으로 재요.","answer":"O","reason_options":[{"t":"높이는 두 밑면 사이의 거리이기 때문에","correct":true},{"t":"비스듬히 재야 정확하기 때문에","mis":"M6-2-u6-X06"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#8','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'mc','auto','원기둥과 각기둥의 같은 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X07']::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":2,"kind":"mc","stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 각기둥의 다른 점은 어느 것인가요?","options":[{"t":"밑면이 원기둥은 원, 각기둥은 다각형이에요","correct":true},{"t":"원기둥은 밑면이 1개, 각기둥은 2개예요","mis":"M6-2-u6-X05"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"},{"t":"원기둥은 두 밑면이 평행하지 않아요","mis":"M6-2-u6-X02"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]},{"stem":"원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?","options":[{"t":"모서리와 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#9','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',2,'error','auto','원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X07','M6-2-u6-X19']::text[],true,'{"seq":9,"concept":"M6-2-u6-C2","difficulty":2,"kind":"error","stem":"원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"순달 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"지석 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"나린 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_basic#10','math',6,2,'u6','L03','g6_2_math_u6_L03_basic','lesson_basic','M6-2-u6-C2',3,'match','auto','원기둥에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C2","difficulty":3,"kind":"match","stem":"원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"서로 평행하고 합동인 두 원","r":"밑면"},{"l":"두 밑면과 만나는 굽은 면","r":"옆면"},{"l":"두 밑면 사이의 거리","r":"높이"}],"mis":"M6-2-u6-X05","explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥의 밑면의 수","r":"2개"},{"l":"원기둥의 옆면의 수","r":"1개"},{"l":"원기둥의 꼭짓점의 수","r":"0개"}],"explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."]},{"stem":"이번에는 다른 보기예요. 원기둥에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"밑면","r":"원"},{"l":"옆면","r":"굽은 면"},{"l":"높이","r":"두 밑면 사이의 거리"}],"explanation":["밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 굽은 면 하나예요.","높이는 두 밑면 사이의 거리이고 꼭짓점은 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#1','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',2,'sa','auto','밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C2","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","7 × 2 = 14 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 12 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["24"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","12 × 2 = 24 cm예요."]},{"stem":"밑면의 반지름이 15 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["30"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","15 × 2 = 30 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#2','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',2,'mc','auto','원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06']::text[],true,'{"seq":2,"concept":"M6-2-u6-C2","difficulty":2,"kind":"mc","stem":"원기둥에는 없고 각기둥에는 있는 것은 어느 것인가요?","options":[{"t":"모서리와 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 각기둥의 같은 점은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면이 있어요","correct":true},{"t":"밑면의 모양이 같아요","mis":"M6-2-u6-X01"},{"t":"옆면이 모두 직사각형이에요","mis":"M6-2-u6-X01"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]},{"stem":"원기둥과 각기둥의 다른 점은 어느 것인가요?","options":[{"t":"밑면이 원기둥은 원, 각기둥은 다각형이에요","correct":true},{"t":"원기둥은 밑면이 1개, 각기둥은 2개예요","mis":"M6-2-u6-X05"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"},{"t":"원기둥은 두 밑면이 평행하지 않아요","mis":"M6-2-u6-X02"}],"explanation":["두 입체도형 모두 서로 평행하고 합동인 두 밑면과 높이가 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥의 옆면은 굽은 면이라 모서리·꼭짓점이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#3','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'ox','auto','원기둥을 눕혀 놓으면 밑면이 옆면이 돼요.',ARRAY['M6-2-u6-X05']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":3,"kind":"ox","stem":"원기둥을 눕혀 놓으면 밑면이 옆면이 돼요.","answer":"X","reason_options":[{"t":"놓는 방향과 상관없이 평행하고 합동인 두 원이 밑면이기 때문에","correct":true},{"t":"아래에 닿은 면만 밑면이기 때문에","mis":"M6-2-u6-X05"}],"mis":"M6-2-u6-X05","explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."],"variant_rule":{"alt":[{"stem":"원기둥에는 모서리가 없어요.","answer":"O","reason_options":[{"t":"평평한 면끼리 만나는 선분이 없기 때문에","correct":true},{"t":"원기둥의 모서리는 2개이기 때문에","mis":"M6-2-u6-X07"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]},{"stem":"원기둥의 높이는 밑면의 지름과 언제나 같아요.","answer":"X","reason_options":[{"t":"높이는 두 밑면 사이의 거리라 지름과 따로 정해지기 때문에","correct":true},{"t":"원기둥은 높이와 지름이 같은 도형이기 때문에","mis":"M6-2-u6-X06"}],"explanation":["원기둥의 밑면은 서로 평행하고 합동인 두 원이에요.","옆면은 두 밑면과 만나는 굽은 면이에요.","높이는 두 밑면 사이의 거리 — 밑면에 수직으로 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#4','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'error','auto','원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X07','M6-2-u6-X19']::text[],true,'{"seq":4,"concept":"M6-2-u6-C2","difficulty":3,"kind":"error","stem":"원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"하린 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"도윤 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"민준 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 수아의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"나린 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 가온의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「원기둥에는 꼭짓점이 있어.」","correct":true,"mis_target":"M6-2-u6-X07"},{"t":"지석 — 「원기둥의 밑면은 2개야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원기둥의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-2-u6-X19"}],"explanation":["원기둥의 밑면은 2개, 옆면은 굽은 면 하나예요.","굽은 면과 원은 만나도 꼭짓점이 생기지 않아요.","그래서 민지의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
