INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#6','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'sa','auto','밑면의 지름이 14 cm이고 높이가 20 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C2","difficulty":3,"kind":"sa","stem":"밑면의 지름이 14 cm이고 높이가 20 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["27"],"explanation":["밑면의 반지름은 14 ÷ 2 = 7 cm예요.","높이는 20 cm예요.","7 + 20 = 27 cm예요."],"mis":"M6-2-u6-X19","variant_rule":{"alt":[{"stem":"밑면의 지름이 18 cm이고 높이가 25 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["34"],"explanation":["밑면의 반지름은 18 ÷ 2 = 9 cm예요.","높이는 25 cm예요.","9 + 25 = 34 cm예요."]},{"stem":"밑면의 지름이 16 cm이고 높이가 30 cm인 원기둥이 있어요. 밑면의 반지름과 높이를 더하면 몇 cm인가요?","answer":["38"],"explanation":["밑면의 반지름은 16 ÷ 2 = 8 cm예요.","높이는 30 cm예요.","8 + 30 = 38 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#7','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',3,'mc','auto','원기둥의 높이를 비스듬히 재면 어떻게 되나요?',ARRAY['M6-2-u6-X06']::text[],true,'{"seq":7,"concept":"M6-2-u6-C2","difficulty":3,"kind":"mc","stem":"원기둥의 높이를 비스듬히 재면 어떻게 되나요?","options":[{"t":"두 밑면 사이의 거리보다 길게 나와요","correct":true},{"t":"두 밑면 사이의 거리보다 짧게 나와요","mis":"M6-2-u6-X06"},{"t":"언제나 같은 값이 나와요","mis":"M6-2-u6-X06"},{"t":"밑면의 지름과 같아져요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X06"},{"t":"옆면의 둘레","mis":"M6-2-u6-X06"},{"t":"밑면의 반지름","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]},{"stem":"원기둥의 높이를 재는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"자와 삼각자를 밑면에 수직으로 대어 두 밑면 사이의 거리를 재요","correct":true},{"t":"밑면의 지름을 재요","mis":"M6-2-u6-X06"},{"t":"옆면을 따라 비스듬히 줄자를 대어 재요","mis":"M6-2-u6-X06"},{"t":"밑면의 둘레를 재요","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#8','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',4,'sa','auto','가로 8 cm, 세로 13 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":4,"kind":"sa","stem":"가로 8 cm, 세로 13 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["29"],"explanation":["막대에 붙인 세로 13 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 8 cm는 밑면의 반지름이 돼요.","지름 16 cm와 높이 13 cm — 16 + 13 = 29 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 11 cm, 세로 6 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["28"],"explanation":["막대에 붙인 세로 6 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 11 cm는 밑면의 반지름이 돼요.","지름 22 cm와 높이 6 cm — 22 + 6 = 28 cm예요."]},{"stem":"가로 9 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["27"],"explanation":["막대에 붙인 세로 9 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","지름 18 cm와 높이 9 cm — 18 + 9 = 27 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#9','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',4,'sa','auto','원기둥 3개와 원뿔 2개의 밑면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C2","difficulty":4,"kind":"sa","stem":"원기둥 3개와 원뿔 2개의 밑면은 모두 몇 개인가요?","answer":["8"],"explanation":["밑면은 원기둥 하나에 2개, 원뿔 하나에 1개예요.","원기둥 3개는 3 × 2 = 6개, 원뿔 2개는 2개예요.","6 + 2 = 8개예요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥 4개와 원뿔 5개의 밑면은 모두 몇 개인가요?","answer":["13"],"explanation":["밑면은 원기둥 하나에 2개, 원뿔 하나에 1개예요.","원기둥 4개는 4 × 2 = 8개, 원뿔 5개는 5개예요.","8 + 5 = 13개예요."]},{"stem":"원기둥 6개와 원뿔 3개의 밑면은 모두 몇 개인가요?","answer":["15"],"explanation":["밑면은 원기둥 하나에 2개, 원뿔 하나에 1개예요.","원기둥 6개는 6 × 2 = 12개, 원뿔 3개는 3개예요.","12 + 3 = 15개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L03_challenge#10','math',6,2,'u6','L03','g6_2_math_u6_L03_challenge','lesson_challenge','M6-2-u6-C2',4,'essay','teacher','지호는 원기둥의 높이를 재려고 옆면을 따라 줄자를 비스듬히 대었어요. 이렇게 재면 무엇이 잘못되는지 쓰고, 높이를 바르게 재는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C2","difficulty":4,"kind":"essay","stem":"지호는 원기둥의 높이를 재려고 옆면을 따라 줄자를 비스듬히 대었어요. 이렇게 재면 무엇이 잘못되는지 쓰고, 높이를 바르게 재는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 높이는 두 밑면 사이의 거리인데, 비스듬히 재면 그 거리보다 길게 나온다. 자와 삼각자(또는 직각자)를 밑면에 수직으로 대어 두 밑면 사이의 거리를 재야 한다.","scoring_points":["높이가 두 밑면 사이의 거리임을 밝혔는가","비스듬히 재면 길게 나온다고 썼는가","밑면에 수직으로 대어 재는 방법을 썼는가"]},"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길어요.","밑면에 수직으로 자와 삼각자를 대어 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#1','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?',ARRAY['M6-2-u6-X13']::text[],true,'{"seq":1,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"원기둥의 전개도","correct":true},{"t":"원기둥의 겨냥도","mis":"M6-2-u6-X13"},{"t":"원기둥의 밑면","mis":"M6-2-u6-X13"},{"t":"원기둥의 옆면","mis":"M6-2-u6-X13"}],"explanation":["입체도형을 잘라 평면 위에 펼친 그림이 전개도예요.","겨냥도는 입체도형의 모양을 잘 알 수 있게 그린 그림이에요.","그래서 원기둥의 전개도예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 밑면과 옆면은 각각 어떤 도형인가요?","options":[{"t":"밑면은 원, 옆면은 직사각형","correct":true},{"t":"밑면은 직사각형, 옆면은 원","mis":"M6-2-u6-X09"},{"t":"밑면은 원, 옆면은 삼각형","mis":"M6-2-u6-X13"},{"t":"밑면과 옆면 모두 원","mis":"M6-2-u6-X13"}],"explanation":["밑면은 원기둥의 두 원이에요.","굽은 옆면을 잘라 펼치면 직사각형이 돼요.","그래서 밑면은 원, 옆면은 직사각형이에요."]},{"stem":"원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?","options":[{"t":"합동인 원 2개와 직사각형 1개","correct":true},{"t":"원 1개와 직사각형 1개","mis":"M6-2-u6-X13"},{"t":"합동인 원 2개와 직사각형 2개","mis":"M6-2-u6-X13"},{"t":"크기가 다른 원 2개와 직사각형 1개","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 밑면은 서로 합동인 원 2개예요.","옆면은 굽은 면 하나 — 펼치면 직사각형 1개예요.","그래서 합동인 원 2개와 직사각형 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#2','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],true,'{"seq":2,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"밑면의 둘레","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"원기둥의 높이","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X08"}],"explanation":["옆면을 다시 감아 붙이면 위쪽 테두리가 밑면의 둘레에 딱 맞아야 해요.","그래서 옆면의 가로는 밑면의 둘레와 같아요.","지름이 아니라 둘레예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 세로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"원기둥의 높이","correct":true},{"t":"밑면의 둘레","mis":"M6-2-u6-X09"},{"t":"밑면의 지름","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X09"}],"explanation":["옆면의 세로는 두 밑면 사이를 이어요.","두 밑면 사이의 거리가 원기둥의 높이예요.","그래서 옆면의 세로는 높이와 같아요."]},{"stem":"원기둥의 전개도에서 밑면의 둘레와 길이가 같은 곳은 어디인가요?","options":[{"t":"옆면의 가로","correct":true},{"t":"옆면의 세로","mis":"M6-2-u6-X09"},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"옆면의 대각선","mis":"M6-2-u6-X09"}],"explanation":["옆면을 감으면 가로가 밑면의 테두리를 한 바퀴 둘러요.","그래서 밑면의 둘레와 옆면의 가로가 같아요.","옆면의 세로는 높이와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#3','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'mc','auto','밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":3,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","8 × 3.14 = 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 5 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u6-X08"},{"t":"7.85 cm","mis":"M6-2-u6-X08"},{"t":"31.4 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","5 × 3.14 = 15.7 cm예요."]},{"stem":"밑면의 지름이 10 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X08"},{"t":"15.7 cm","mis":"M6-2-u6-X08"},{"t":"62.8 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","10 × 3.14 = 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#4','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',1,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 7 cm예요. 이 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":1,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 7 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["7"],"explanation":["옆면의 가로는 밑면의 둘레, 세로는 높이예요.","높이를 묻고 있어요.","그래서 높이는 세로와 같은 7 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 9 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["옆면의 가로는 밑면의 둘레, 세로는 높이예요.","높이를 묻고 있어요.","그래서 높이는 세로와 같은 9 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 9.42 cm, 세로가 11 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["11"],"explanation":["옆면의 가로는 밑면의 둘레, 세로는 높이예요.","높이를 묻고 있어요.","그래서 높이는 세로와 같은 11 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#5','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":5,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 3 cm에 2를 곱해 지름 6 cm를 먼저 만들어요.","6 × 3.14 = 18.84 cm예요."]},{"stem":"밑면의 반지름이 5 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"31.4 cm","correct":true},{"t":"15.7 cm","mis":"M6-2-u6-X08"},{"t":"10 cm","mis":"M6-2-u6-X08"},{"t":"62.8 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 5 cm에 2를 곱해 지름 10 cm를 먼저 만들어요.","10 × 3.14 = 31.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#6','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","25.12 ÷ 3.14 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","18.84 ÷ 3.14 = 6 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 21.98 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","21.98 ÷ 3.14 = 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#7','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":7,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?","options":[{"t":"3 × 2 × 3.14","correct":true},{"t":"3 × 3.14","mis":"M6-2-u6-X08"},{"t":"3 ÷ 3.14","mis":"M6-2-u6-X10"},{"t":"3 × 2","mis":"M6-2-u6-X08"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름에 2를 먼저 곱해 지름을 만들어요.","그래서 3 × 2 × 3.14예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 5 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?","options":[{"t":"5 × 2 × 3.14","correct":true},{"t":"5 × 3.14","mis":"M6-2-u6-X08"},{"t":"5 ÷ 3.14","mis":"M6-2-u6-X10"},{"t":"5 × 2","mis":"M6-2-u6-X08"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름에 2를 먼저 곱해 지름을 만들어요.","그래서 5 × 2 × 3.14예요."]},{"stem":"밑면의 반지름이 7 cm인 원기둥의 전개도에서 옆면의 가로를 바르게 구한 식은 어느 것인가요?","options":[{"t":"7 × 2 × 3.14","correct":true},{"t":"7 × 3.14","mis":"M6-2-u6-X08"},{"t":"7 ÷ 3.14","mis":"M6-2-u6-X10"},{"t":"7 × 2","mis":"M6-2-u6-X08"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름에 2를 먼저 곱해 지름을 만들어요.","그래서 7 × 2 × 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#8','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'ox','auto','원기둥의 전개도에서 옆면의 가로는 밑면의 지름과 같아요.',ARRAY['M6-2-u6-X08']::text[],true,'{"seq":8,"concept":"M6-2-u6-C3","difficulty":2,"kind":"ox","stem":"원기둥의 전개도에서 옆면의 가로는 밑면의 지름과 같아요.","answer":"X","reason_options":[{"t":"옆면을 감으면 가로가 밑면의 둘레를 한 바퀴 두르기 때문에","correct":true},{"t":"옆면의 가로가 밑면을 가로지르기 때문에","mis":"M6-2-u6-X08"}],"mis":"M6-2-u6-X08","explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 세로는 원기둥의 높이와 같아요.","answer":"O","reason_options":[{"t":"세로가 두 밑면 사이를 잇기 때문에","correct":true},{"t":"세로는 밑면의 둘레와 같기 때문에","mis":"M6-2-u6-X09"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]},{"stem":"원기둥의 전개도에는 원이 1개 있어요.","answer":"X","reason_options":[{"t":"원기둥의 밑면은 합동인 원 2개이기 때문에","correct":true},{"t":"원기둥의 밑면은 하나이기 때문에","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#9','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',2,'mc','auto','대나무 칫솔 상자는 밑면의 지름이 4 cm인 원기둥 모양이에요. 상자를 잘라 펼친 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"대나무 칫솔 상자는 밑면의 지름이 4 cm인 원기둥 모양이에요. 상자를 잘라 펼친 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"12.56 cm","correct":true},{"t":"4 cm","mis":"M6-2-u6-X08"},{"t":"6.28 cm","mis":"M6-2-u6-X08"},{"t":"25.12 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","4 × 3.14 = 12.56 cm예요."],"variant_rule":{"alt":[{"stem":"원기둥 모양 과자 통의 밑면의 지름은 6 cm예요. 통을 잘라 펼친 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","6 × 3.14 = 18.84 cm예요."]},{"stem":"원기둥 모양 연필꽂이의 밑면의 지름은 9 cm예요. 연필꽂이를 잘라 펼친 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"28.26 cm","correct":true},{"t":"9 cm","mis":"M6-2-u6-X08"},{"t":"14.13 cm","mis":"M6-2-u6-X08"},{"t":"56.52 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","9 × 3.14 = 28.26 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_basic#10','math',6,2,'u6','L04','g6_2_math_u6_L04_basic','lesson_basic','M6-2-u6-C3',3,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["11"],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm예요.","옆면의 세로가 높이 — 5 cm예요.","6 + 5 = 11 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 9 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["13"],"explanation":["지름은 12.56 ÷ 3.14 = 4 cm예요.","옆면의 세로가 높이 — 9 cm예요.","4 + 9 = 13 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 10 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["18"],"explanation":["지름은 25.12 ÷ 3.14 = 8 cm예요.","옆면의 세로가 높이 — 10 cm예요.","8 + 10 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#1','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["3"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 18.84 ÷ 3.14 = 6 cm예요.","반지름은 6 ÷ 2 = 3 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 25.12 ÷ 3.14 = 8 cm예요.","반지름은 8 ÷ 2 = 4 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 31.4 ÷ 3.14 = 10 cm예요.","반지름은 10 ÷ 2 = 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#2','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',2,'mc','auto','밑면의 지름이 20 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":2,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 지름이 20 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"20 cm","mis":"M6-2-u6-X08"},{"t":"31.4 cm","mis":"M6-2-u6-X08"},{"t":"125.6 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","20 × 3.14 = 62.8 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 15 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"47.1 cm","correct":true},{"t":"15 cm","mis":"M6-2-u6-X08"},{"t":"23.55 cm","mis":"M6-2-u6-X08"},{"t":"94.2 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","15 × 3.14 = 47.1 cm예요."]},{"stem":"밑면의 지름이 12 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"12 cm","mis":"M6-2-u6-X08"},{"t":"18.84 cm","mis":"M6-2-u6-X08"},{"t":"75.36 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","12 × 3.14 = 37.68 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#3','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'error','auto','밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C3","difficulty":3,"kind":"error","stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"여울 — 「가로는 밑면의 지름이니 6 cm야.」","correct":true,"mis_target":"M6-2-u6-X08"},{"t":"순달 — 「3 × 2 × 3.14 = 18.84야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「지름 6 cm에 3.14를 곱해 18.84야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「가로는 밑면의 둘레야.」","mis":"M6-2-u6-X19"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","6 × 3.14 = 18.84 cm예요.","여울는 지름을 가로로 보았어요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"민지 — 「가로는 밑면의 지름이니 8 cm야.」","correct":true,"mis_target":"M6-2-u6-X08"},{"t":"지석 — 「4 × 2 × 3.14 = 25.12야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「지름 8 cm에 3.14를 곱해 25.12야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「가로는 밑면의 둘레야.」","mis":"M6-2-u6-X19"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","8 × 3.14 = 25.12 cm예요.","민지는 지름을 가로로 보았어요."]},{"stem":"밑면의 반지름이 5 cm인 원기둥의 전개도에서 옆면의 가로를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「가로는 밑면의 지름이니 10 cm야.」","correct":true,"mis_target":"M6-2-u6-X08"},{"t":"나린 — 「5 × 2 × 3.14 = 31.4야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「지름 10 cm에 3.14를 곱해 31.4야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「가로는 밑면의 둘레야.」","mis":"M6-2-u6-X19"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","10 × 3.14 = 31.4 cm예요.","가온는 지름을 가로로 보았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#4','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'ox','auto','밑면의 지름이 같은 두 원기둥은 전개도에서 옆면의 가로가 같아요.',ARRAY['M6-2-u6-X09']::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":3,"kind":"ox","stem":"밑면의 지름이 같은 두 원기둥은 전개도에서 옆면의 가로가 같아요.","answer":"O","reason_options":[{"t":"옆면의 가로는 (지름) × 3.14이기 때문에","correct":true},{"t":"옆면의 가로는 높이로 정해지기 때문에","mis":"M6-2-u6-X09"}],"mis":"M6-2-u6-X09","explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이가 높아지면 전개도에서 옆면의 가로가 길어져요.","answer":"X","reason_options":[{"t":"높이는 옆면의 세로이고 가로는 밑면의 둘레이기 때문에","correct":true},{"t":"높이와 옆면의 가로는 같은 길이이기 때문에","mis":"M6-2-u6-X09"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]},{"stem":"밑면의 반지름이 2배가 되면 옆면의 가로도 2배가 돼요.","answer":"O","reason_options":[{"t":"옆면의 가로는 (반지름) × 2 × 3.14이기 때문에","correct":true},{"t":"옆면의 가로는 반지름과 상관없기 때문에","mis":"M6-2-u6-X10"}],"explanation":["원기둥의 전개도는 합동인 원 2개와 직사각형 1개예요.","옆면의 가로는 밑면의 둘레, 세로는 높이예요.","(밑면의 둘레) = (지름) × 3.14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#5','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'match','auto','원기둥과 전개도에서 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C3","difficulty":3,"kind":"match","stem":"원기둥과 전개도에서 알맞은 것끼리 이으세요.","pairs":[{"l":"지름 2 cm","r":"가로 6.28 cm"},{"l":"지름 5 cm","r":"가로 15.7 cm"},{"l":"지름 10 cm","r":"가로 31.4 cm"}],"mis":"M6-2-u6-X08","explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름이면 2를 먼저 곱해요.","옆면의 세로는 높이, 원은 밑면이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥과 전개도에서 알맞은 것끼리 이으세요.","pairs":[{"l":"반지름 2 cm","r":"가로 12.56 cm"},{"l":"반지름 3 cm","r":"가로 18.84 cm"},{"l":"반지름 1.5 cm","r":"가로 9.42 cm"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름이면 2를 먼저 곱해요.","옆면의 세로는 높이, 원은 밑면이에요."]},{"stem":"이번에는 다른 보기예요. 원기둥과 전개도에서 알맞은 것끼리 이으세요.","pairs":[{"l":"옆면의 가로","r":"밑면의 둘레"},{"l":"옆면의 세로","r":"원기둥의 높이"},{"l":"전개도의 원","r":"원기둥의 밑면"}],"explanation":["옆면의 가로는 밑면의 둘레 — (지름) × 3.14예요.","반지름이면 2를 먼저 곱해요.","옆면의 세로는 높이, 원은 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#6','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'mc','auto','밑면의 반지름이 6 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":6,"concept":"M6-2-u6-C3","difficulty":3,"kind":"mc","stem":"밑면의 반지름이 6 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"37.68 cm","correct":true},{"t":"18.84 cm","mis":"M6-2-u6-X08"},{"t":"12 cm","mis":"M6-2-u6-X08"},{"t":"75.36 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 6 cm에 2를 곱해 지름 12 cm를 먼저 만들어요.","12 × 3.14 = 37.68 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"50.24 cm","correct":true},{"t":"25.12 cm","mis":"M6-2-u6-X08"},{"t":"16 cm","mis":"M6-2-u6-X08"},{"t":"100.48 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 8 cm에 2를 곱해 지름 16 cm를 먼저 만들어요.","16 × 3.14 = 50.24 cm예요."]},{"stem":"밑면의 반지름이 10 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"62.8 cm","correct":true},{"t":"31.4 cm","mis":"M6-2-u6-X08"},{"t":"20 cm","mis":"M6-2-u6-X08"},{"t":"125.6 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 10 cm에 2를 곱해 지름 20 cm를 먼저 만들어요.","20 × 3.14 = 62.8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#7','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',3,'mc','auto','밑면의 지름이 10 cm, 높이가 5 cm인 원기둥의 전개도를 그렸어요. 옆면 직사각형의 둘레는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X20','M6-2-u6-X09']::text[],true,'{"seq":7,"concept":"M6-2-u6-C3","difficulty":3,"kind":"mc","stem":"밑면의 지름이 10 cm, 높이가 5 cm인 원기둥의 전개도를 그렸어요. 옆면 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"72.8 cm","correct":true},{"t":"30 cm","mis":"M6-2-u6-X08"},{"t":"36.4 cm","mis":"M6-2-u6-X20"},{"t":"82.8 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 10 × 3.14 = 31.4 cm예요.","세로는 높이 5 cm예요.","(31.4 + 5) × 2 = 72.8 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 5 cm, 높이가 10 cm인 원기둥의 전개도를 그렸어요. 옆면 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"51.4 cm","correct":true},{"t":"30 cm","mis":"M6-2-u6-X08"},{"t":"25.7 cm","mis":"M6-2-u6-X20"},{"t":"41.4 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 5 × 3.14 = 15.7 cm예요.","세로는 높이 10 cm예요.","(15.7 + 10) × 2 = 51.4 cm예요."]},{"stem":"밑면의 지름이 4 cm, 높이가 6 cm인 원기둥의 전개도를 그렸어요. 옆면 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"37.12 cm","correct":true},{"t":"20 cm","mis":"M6-2-u6-X08"},{"t":"18.56 cm","mis":"M6-2-u6-X20"},{"t":"33.12 cm","mis":"M6-2-u6-X09"}],"explanation":["옆면의 가로는 4 × 3.14 = 12.56 cm예요.","세로는 높이 6 cm예요.","(12.56 + 6) × 2 = 37.12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#8','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',4,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 62.8 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C3","difficulty":4,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 62.8 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["10"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 62.8 ÷ 3.14 = 20 cm예요.","반지름은 20 ÷ 2 = 10 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 75.36 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["12"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 75.36 ÷ 3.14 = 24 cm예요.","반지름은 24 ÷ 2 = 12 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 94.2 cm예요. 이 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["15"],"explanation":["옆면의 가로는 밑면의 둘레예요.","지름은 94.2 ÷ 3.14 = 30 cm예요.","반지름은 30 ÷ 2 = 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#9','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',4,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 37.68 cm, 세로가 20 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C3","difficulty":4,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 37.68 cm, 세로가 20 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["32"],"explanation":["지름은 37.68 ÷ 3.14 = 12 cm예요.","옆면의 세로가 높이 — 20 cm예요.","12 + 20 = 32 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 47.1 cm, 세로가 30 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["45"],"explanation":["지름은 47.1 ÷ 3.14 = 15 cm예요.","옆면의 세로가 높이 — 30 cm예요.","15 + 30 = 45 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 62.8 cm, 세로가 25 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["45"],"explanation":["지름은 62.8 ÷ 3.14 = 20 cm예요.","옆면의 세로가 높이 — 25 cm예요.","20 + 25 = 45 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L04_challenge#10','math',6,2,'u6','L04','g6_2_math_u6_L04_challenge','lesson_challenge','M6-2-u6-C3',4,'essay','teacher','밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 구하고, 가로가 밑면의 지름이 아니라 밑면의 둘레와 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로를 구하고, 가로가 밑면의 지름이 아니라 밑면의 둘레와 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 지름은 4 × 2 = 8 cm이고 옆면의 가로는 8 × 3.14 = 25.12 cm이다. 펼친 직사각형을 다시 감아 붙이면 위쪽 테두리가 밑면인 원의 둘레에 딱 맞아야 하므로, 옆면의 가로는 밑면의 둘레와 같다.","scoring_points":["25.12 cm를 구했는가","반지름에 2를 곱해 지름을 만들었는가","감아 붙이면 테두리가 밑면의 둘레에 맞는다는 까닭을 썼는가"]},"explanation":["지름 8 cm × 3.14 = 25.12 cm예요.","옆면을 감으면 가로가 밑면 둘레를 한 바퀴 둘러요.","그래서 지름이 아니라 둘레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#1','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'mc','auto','「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X11']::text[],true,'{"seq":1,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서 전개도가 될 수 없어요."]},{"stem":"「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 서로 합동이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#2','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'sa','auto','원기둥의 전개도를 그릴 때 밑면은 모두 몇 개 그려야 하나요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C4","difficulty":1,"kind":"sa","stem":"원기둥의 전개도를 그릴 때 밑면은 모두 몇 개 그려야 하나요?","answer":["2"],"explanation":["원기둥의 면을 떠올려요 — 밑면 2개와 옆면 1개예요.","밑면은 서로 합동인 원 2개를 그려요.","두 밑면은 옆면을 사이에 두고 마주 보게 그려요."],"mis":"M6-2-u6-X13","variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면은 직사각형 몇 개인가요?","answer":["1"],"explanation":["원기둥의 면을 떠올려요 — 밑면 2개와 옆면 1개예요.","옆면은 직사각형 1개를 그려요.","두 밑면은 옆면을 사이에 두고 마주 보게 그려요."]},{"stem":"원기둥의 전개도는 모두 몇 개의 평면도형으로 이루어져 있나요?","answer":["3"],"explanation":["원기둥의 면을 떠올려요 — 밑면 2개와 옆면 1개예요.","원 2개와 직사각형 1개 — 모두 3개예요.","두 밑면은 옆면을 사이에 두고 마주 보게 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#3','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'mc','auto','원기둥의 전개도를 그릴 때 두 밑면은 어떻게 그려야 하나요?',ARRAY['M6-2-u6-X02','M6-2-u6-X13']::text[],true,'{"seq":3,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"원기둥의 전개도를 그릴 때 두 밑면은 어떻게 그려야 하나요?","options":[{"t":"서로 합동인 원 2개","correct":true},{"t":"크기가 다른 원 2개","mis":"M6-2-u6-X02"},{"t":"원 1개","mis":"M6-2-u6-X13"},{"t":"직사각형 2개","mis":"M6-2-u6-X13"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?","options":[{"t":"옆면을 사이에 두고 마주 보는 위치","correct":true},{"t":"옆면의 같은 쪽에 나란히","mis":"M6-2-u6-X12"},{"t":"옆면의 한가운데에 겹쳐서","mis":"M6-2-u6-X12"},{"t":"아무 곳에나","mis":"M6-2-u6-X12"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."]},{"stem":"원기둥의 전개도가 되는 조건이 아닌 것은 어느 것인가요?","options":[{"t":"두 원이 옆면의 같은 쪽에 있어야 해요","correct":true},{"t":"옆면이 직사각형이어야 해요","mis":"M6-2-u6-X19"},{"t":"두 밑면이 합동인 원이어야 해요","mis":"M6-2-u6-X19"},{"t":"두 밑면이 마주 보는 위치에 있어야 해요","mis":"M6-2-u6-X19"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#4','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',1,'mc','auto','다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X11','M6-2-u6-X12']::text[],true,'{"seq":4,"concept":"M6-2-u6-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 옆면의 위와 아래에 하나씩 붙은 그림","correct":true},{"t":"옆면이 직사각형이고, 크기가 다른 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X02"},{"t":"옆면이 평행사변형이고, 크기가 같은 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X11"},{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 모두 위쪽에 붙은 그림","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 원이 직사각형 옆면을 사이에 두고 마주 붙은 그림","correct":true},{"t":"크기가 같은 두 원이 직사각형 옆면의 한쪽에 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"원 하나가 직사각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"},{"t":"크기가 같은 두 원이 삼각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"직사각형의 위쪽 가운데와 아래쪽 가운데에 합동인 원이 하나씩 붙은 그림","correct":true},{"t":"직사각형의 위쪽에 합동인 원 두 개가 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"직사각형의 위쪽에 큰 원, 아래쪽에 작은 원이 붙은 그림","mis":"M6-2-u6-X02"},{"t":"기울어진 사각형의 위아래에 합동인 원이 하나씩 붙은 그림","mis":"M6-2-u6-X11"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#5','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'mc','auto','「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X13']::text[],true,'{"seq":5,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"밑면이 하나뿐이어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 밑면이 하나뿐이어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서 전개도가 될 수 없어요."]},{"stem":"「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#6','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 6.28 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 6.28 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["2"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","6.28 ÷ 3.14 = 2 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 9.42 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["3"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","9.42 ÷ 3.14 = 3 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","12.56 ÷ 3.14 = 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#7','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 6.28 cm, 세로가 3 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C4","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 6.28 cm, 세로가 3 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["5"],"explanation":["지름은 6.28 ÷ 3.14 = 2 cm예요.","옆면의 세로가 높이 — 3 cm예요.","2 + 3 = 5 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 9.42 cm, 세로가 4 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["7"],"explanation":["지름은 9.42 ÷ 3.14 = 3 cm예요.","옆면의 세로가 높이 — 4 cm예요.","3 + 4 = 7 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 15.7 cm, 세로가 2 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["7"],"explanation":["지름은 15.7 ÷ 3.14 = 5 cm예요.","옆면의 세로가 높이 — 2 cm예요.","5 + 2 = 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#8','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'error','auto','원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X19']::text[],true,'{"seq":8,"concept":"M6-2-u6-C4","difficulty":2,"kind":"error","stem":"원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"순달 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"지석 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"나린 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#9','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',2,'mc','auto','「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":9,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 서로 합동이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 원이 직사각형 옆면을 사이에 두고 마주 붙은 그림","correct":true},{"t":"크기가 같은 두 원이 직사각형 옆면의 한쪽에 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"원 하나가 직사각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"},{"t":"크기가 같은 두 원이 삼각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]},{"stem":"원기둥의 전개도가 되는 조건이 아닌 것은 어느 것인가요?","options":[{"t":"두 원이 옆면의 같은 쪽에 있어야 해요","correct":true},{"t":"옆면이 직사각형이어야 해요","mis":"M6-2-u6-X19"},{"t":"두 밑면이 합동인 원이어야 해요","mis":"M6-2-u6-X19"},{"t":"두 밑면이 마주 보는 위치에 있어야 해요","mis":"M6-2-u6-X19"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_basic#10','math',6,2,'u6','L05','g6_2_math_u6_L05_basic','lesson_basic','M6-2-u6-C4',3,'mc','auto','밑면의 지름이 6 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 6 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":10,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"밑면의 지름이 6 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 6 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"18.84 cm","correct":true},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 6 × 3.14 = 18.84 cm예요.","그래서 가로를 18.84 cm로 고쳐요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 8 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 8 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 8 × 3.14 = 25.12 cm예요.","그래서 가로를 25.12 cm로 고쳐요."]},{"stem":"밑면의 지름이 5 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 5 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u6-X08"},{"t":"7.85 cm","mis":"M6-2-u6-X08"},{"t":"31.4 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 5 × 3.14 = 15.7 cm예요.","그래서 가로를 15.7 cm로 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#1','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',2,'mc','auto','다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X02','M6-2-u6-X11']::text[],true,'{"seq":1,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"직사각형의 위쪽 가운데와 아래쪽 가운데에 합동인 원이 하나씩 붙은 그림","correct":true},{"t":"직사각형의 위쪽에 합동인 원 두 개가 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"직사각형의 위쪽에 큰 원, 아래쪽에 작은 원이 붙은 그림","mis":"M6-2-u6-X02"},{"t":"기울어진 사각형의 위아래에 합동인 원이 하나씩 붙은 그림","mis":"M6-2-u6-X11"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 옆면의 위와 아래에 하나씩 붙은 그림","correct":true},{"t":"옆면이 직사각형이고, 크기가 다른 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X02"},{"t":"옆면이 평행사변형이고, 크기가 같은 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X11"},{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 모두 위쪽에 붙은 그림","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 원이 직사각형 옆면을 사이에 두고 마주 붙은 그림","correct":true},{"t":"크기가 같은 두 원이 직사각형 옆면의 한쪽에 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"원 하나가 직사각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"},{"t":"크기가 같은 두 원이 삼각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#2','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',2,'mc','auto','「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X12']::text[],true,'{"seq":2,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 서로 합동이 아니어서 전개도가 될 수 없어요."]},{"stem":"「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"밑면이 하나뿐이어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 밑면이 하나뿐이어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#3','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'ox','auto','옆면이 평행사변형인 그림도 원기둥의 전개도가 될 수 있어요.',ARRAY['M6-2-u6-X11']::text[],true,'{"seq":3,"concept":"M6-2-u6-C4","difficulty":3,"kind":"ox","stem":"옆면이 평행사변형인 그림도 원기둥의 전개도가 될 수 있어요.","answer":"X","reason_options":[{"t":"감으면 위아래 테두리가 어긋나기 때문에","correct":true},{"t":"평행사변형도 사각형이라 감을 수 있기 때문에","mis":"M6-2-u6-X11"}],"mis":"M6-2-u6-X11","explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보아야 해요."],"variant_rule":{"alt":[{"stem":"합동인 두 원이 옆면의 같은 쪽에 붙은 그림은 원기둥의 전개도가 아니에요.","answer":"O","reason_options":[{"t":"접으면 두 원이 겹치고 반대쪽이 비기 때문에","correct":true},{"t":"두 원의 크기가 다르기 때문에","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보아야 해요."]},{"stem":"두 원의 크기가 달라도 옆면이 직사각형이면 원기둥의 전개도예요.","answer":"X","reason_options":[{"t":"원기둥의 두 밑면은 서로 합동이어야 하기 때문에","correct":true},{"t":"옆면만 직사각형이면 되기 때문에","mis":"M6-2-u6-X02"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#4','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'match','auto','원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C4","difficulty":3,"kind":"match","stem":"원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.","pairs":[{"l":"옆면이 평행사변형","r":"옆면이 직사각형이 아님"},{"l":"두 원이 같은 쪽","r":"접으면 두 원이 겹침"},{"l":"위 원이 더 작음","r":"두 밑면이 합동이 아님"}],"mis":"M6-2-u6-X11","explanation":["옆면은 직사각형이어야 해요.","두 밑면은 합동인 원이어야 해요.","두 밑면은 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.","pairs":[{"l":"기울어진 옆면","r":"위아래 테두리가 어긋남"},{"l":"크기가 다른 두 원","r":"한쪽이 남거나 모자람"},{"l":"나란히 붙은 두 원","r":"한쪽이 뚫림"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 합동인 원이어야 해요.","두 밑면은 마주 보는 위치에 있어야 해요."]},{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 없는 그림과 그 까닭을 이으세요.","pairs":[{"l":"원 1개뿐","r":"밑면이 모자람"},{"l":"두 원이 같은 쪽","r":"마주 보지 않음"},{"l":"옆면이 평행사변형","r":"감으면 어긋남"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 합동인 원이어야 해요.","두 밑면은 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#5','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'error','auto','원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X19']::text[],true,'{"seq":5,"concept":"M6-2-u6-C4","difficulty":3,"kind":"error","stem":"원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"하린 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"도윤 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"민준 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 수아의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"나린 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 가온의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원기둥의 전개도가 될 수 있는지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「두 원이 옆면의 같은 쪽에 있어도 합동이면 전개도야.」","correct":true,"mis_target":"M6-2-u6-X12"},{"t":"지석 — 「옆면은 직사각형이어야 해.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「두 원은 서로 합동이어야 해.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「두 원은 옆면을 사이에 두고 마주 보아야 해.」","mis":"M6-2-u6-X19"}],"explanation":["두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐요.","그러면 반대쪽이 뚫린 채 남아요.","그래서 민지의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#6','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'mc','auto','밑면의 지름이 10 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 10 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":6,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"밑면의 지름이 10 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 10 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"31.4 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X08"},{"t":"15.7 cm","mis":"M6-2-u6-X08"},{"t":"62.8 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 10 × 3.14 = 31.4 cm예요.","그래서 가로를 31.4 cm로 고쳐요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 4 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 4 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"12.56 cm","correct":true},{"t":"4 cm","mis":"M6-2-u6-X08"},{"t":"6.28 cm","mis":"M6-2-u6-X08"},{"t":"25.12 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 4 × 3.14 = 12.56 cm예요.","그래서 가로를 12.56 cm로 고쳐요."]},{"stem":"밑면의 지름이 7 cm인 원기둥의 전개도를 그리는데 옆면의 가로를 7 cm로 그렸더니 감았을 때 밑면과 맞지 않았어요. 옆면의 가로를 몇 cm로 고쳐야 하나요?","options":[{"t":"21.98 cm","correct":true},{"t":"7 cm","mis":"M6-2-u6-X08"},{"t":"10.99 cm","mis":"M6-2-u6-X08"},{"t":"43.96 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면을 감았을 때 테두리가 밑면의 둘레에 딱 맞아야 해요.","밑면의 둘레는 7 × 3.14 = 21.98 cm예요.","그래서 가로를 21.98 cm로 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#7','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',3,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 12 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C4","difficulty":3,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 12 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["22"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","옆면의 세로가 높이 — 12 cm예요.","10 + 12 = 22 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 15 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["23"],"explanation":["지름은 25.12 ÷ 3.14 = 8 cm예요.","옆면의 세로가 높이 — 15 cm예요.","8 + 15 = 23 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 20 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["26"],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm예요.","옆면의 세로가 높이 — 20 cm예요.","6 + 20 = 26 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#8','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',4,'sa','auto','가로 18.84 cm, 세로 8 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C4","difficulty":4,"kind":"sa","stem":"가로 18.84 cm, 세로 8 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?","answer":["3"],"explanation":["두 원의 둘레가 옆면의 가로 18.84 cm와 같아야 감았을 때 딱 맞아요.","지름은 18.84 ÷ 3.14 = 6 cm예요.","반지름은 6 ÷ 2 = 3 cm — 합동인 원 두 개를 마주 보게 그려요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"가로 31.4 cm, 세로 12 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?","answer":["5"],"explanation":["두 원의 둘레가 옆면의 가로 31.4 cm와 같아야 감았을 때 딱 맞아요.","지름은 31.4 ÷ 3.14 = 10 cm예요.","반지름은 10 ÷ 2 = 5 cm — 합동인 원 두 개를 마주 보게 그려요."]},{"stem":"가로 25.12 cm, 세로 10 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?","answer":["4"],"explanation":["두 원의 둘레가 옆면의 가로 25.12 cm와 같아야 감았을 때 딱 맞아요.","지름은 25.12 ÷ 3.14 = 8 cm예요.","반지름은 8 ÷ 2 = 4 cm — 합동인 원 두 개를 마주 보게 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#9','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',4,'sa','auto','가로 62.8 cm, 세로 6 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C4","difficulty":4,"kind":"sa","stem":"가로 62.8 cm, 세로 6 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?","answer":["10"],"explanation":["두 원의 둘레가 옆면의 가로 62.8 cm와 같아야 감았을 때 딱 맞아요.","지름은 62.8 ÷ 3.14 = 20 cm예요.","반지름은 20 ÷ 2 = 10 cm — 합동인 원 두 개를 마주 보게 그려요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"가로 37.68 cm, 세로 15 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?","answer":["6"],"explanation":["두 원의 둘레가 옆면의 가로 37.68 cm와 같아야 감았을 때 딱 맞아요.","지름은 37.68 ÷ 3.14 = 12 cm예요.","반지름은 12 ÷ 2 = 6 cm — 합동인 원 두 개를 마주 보게 그려요."]},{"stem":"가로 50.24 cm, 세로 5 cm인 직사각형을 옆면으로 하여 원기둥의 전개도를 그리려고 해요. 밑면으로 붙일 두 원의 반지름은 몇 cm로 그려야 하나요?","answer":["8"],"explanation":["두 원의 둘레가 옆면의 가로 50.24 cm와 같아야 감았을 때 딱 맞아요.","지름은 50.24 ÷ 3.14 = 16 cm예요.","반지름은 16 ÷ 2 = 8 cm — 합동인 원 두 개를 마주 보게 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L05_challenge#10','math',6,2,'u6','L05','g6_2_math_u6_L05_challenge','lesson_challenge','M6-2-u6-C4',4,'essay','teacher','종이 상자를 잘라 펼친 그림에서 합동인 두 원이 직사각형 옆면의 같은 쪽에 나란히 붙어 있어요. 이 그림이 원기둥의 전개도가 될 수 없는 까닭을 쓰고, 어떻게 고치면 되는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C4","difficulty":4,"kind":"essay","stem":"종이 상자를 잘라 펼친 그림에서 합동인 두 원이 직사각형 옆면의 같은 쪽에 나란히 붙어 있어요. 이 그림이 원기둥의 전개도가 될 수 없는 까닭을 쓰고, 어떻게 고치면 되는지 설명해 보세요.","answer_guide":{"answer":"예: 옆면을 감으면 둥근 통이 되는데 두 원이 같은 쪽에 있으면 접었을 때 한자리에 겹쳐 반대쪽이 뚫린 채 남는다. 원 하나를 옆면의 반대쪽으로 옮겨 두 밑면이 옆면을 사이에 두고 마주 보게 그려야 한다.","scoring_points":["접으면 두 원이 겹친다고 썼는가","반대쪽이 막히지 않는다고 밝혔는가","두 밑면을 마주 보는 위치로 옮기는 방법을 썼는가"]},"explanation":["같은 쪽의 두 원은 접으면 겹쳐요.","반대쪽은 뚫린 채 남아요.","두 밑면을 옆면을 사이에 두고 마주 보게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#1','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','원뿔은 어떤 입체도형인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"원뿔은 어떤 입체도형인가요?","options":[{"t":"한 원을 면으로 하는 입체도형","correct":true},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X03"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X01"}],"explanation":["원뿔의 뜻을 떠올려요.","원뿔은 한 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."],"variant_rule":{"alt":[{"stem":"한 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X14"},{"t":"각기둥","mis":"M6-2-u6-X03"},{"t":"각뿔","mis":"M6-2-u6-X01"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","한 원을 면으로 하는 입체도형을 원뿔이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]},{"stem":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형을 무엇이라고 하나요?","options":[{"t":"각뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"각기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X01"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","밑면이 다각형이고 옆면이 모두 삼각형인 입체도형을 각뿔이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#2','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."],"variant_rule":{"alt":[{"stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."]},{"stem":"지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 구가 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#3','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'sa','auto','원뿔의 밑면은 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C5","difficulty":1,"kind":"sa","stem":"원뿔의 밑면은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 밑면은 원 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 꼭짓점은 뾰족한 점 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]},{"stem":"원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?","answer":["3"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개와 원기둥 2개 — 1 + 2 = 3개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#4','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',1,'mc','auto','「밑면이 사각형이고 옆면이 삼각형인 지붕」은 원뿔이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X01']::text[],true,'{"seq":4,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"「밑면이 사각형이고 옆면이 삼각형인 지붕」은 원뿔이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원을 면으로 하지 않아서","correct":true},{"t":"합동인 원이 두 개 있어서","mis":"M6-2-u6-X01"},{"t":"평평한 면도 뾰족한 점도 없어서","mis":"M6-2-u6-X01"},{"t":"뾰족한 점이 없고 원이 두 개라서","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","원뿔에는 뾰족한 점이 하나 있어요.","「밑면이 사각형이고 옆면이 삼각형인 지붕」은 원을 면으로 하지 않아서 원뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 합동인 두 원이 있는 통」은 원뿔이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"합동인 원이 두 개 있어서","correct":true},{"t":"원을 면으로 하지 않아서","mis":"M6-2-u6-X14"},{"t":"평평한 면도 뾰족한 점도 없어서","mis":"M6-2-u6-X14"},{"t":"뾰족한 점이 없고 원이 두 개라서","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","원뿔에는 뾰족한 점이 하나 있어요.","「서로 합동인 두 원이 있는 통」은 합동인 원이 두 개 있어서 원뿔이 아니에요."]},{"stem":"「굽은 면으로만 둘러싸인 공」은 원뿔이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"평평한 면도 뾰족한 점도 없어서","correct":true},{"t":"합동인 원이 두 개 있어서","mis":"M6-2-u6-X03"},{"t":"원을 면으로 하지 않아서","mis":"M6-2-u6-X03"},{"t":"뾰족한 점이 없고 원이 두 개라서","mis":"M6-2-u6-X03"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","원뿔에는 뾰족한 점이 하나 있어요.","「굽은 면으로만 둘러싸인 공」은 평평한 면도 뾰족한 점도 없어서 원뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#5','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'sa','auto','세 변이 3 cm, 4 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 4 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"세 변이 3 cm, 4 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 4 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 변 4 cm는 원뿔의 높이, 뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","가장 긴 변 5 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 3 × 2 = 6 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 6 cm, 8 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 8 cm는 원뿔의 높이, 뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","가장 긴 변 10 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 6 × 2 = 12 cm예요."]},{"stem":"세 변이 5 cm, 12 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["10"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","가장 긴 변 13 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 5 × 2 = 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#6','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'mc','auto','직각삼각형의 직각을 낀 변을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원뿔의 무엇이 되나요?',ARRAY['M6-2-u6-X04','M6-2-u6-X15']::text[],true,'{"seq":6,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"직각삼각형의 직각을 낀 변을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원뿔의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."],"variant_rule":{"alt":[{"stem":"직각삼각형의 직각을 낀 변을 막대에 붙여 한 바퀴 돌릴 때, 막대에서 뻗어 나간 변은 만들어진 원뿔의 무엇이 되나요?","options":[{"t":"밑면의 반지름","correct":true},{"t":"높이","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]},{"stem":"「위쪽이 뾰족하지 않고 잘려 작은 원이 있는 화분」은 원뿔이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"뾰족한 점이 없고 원이 두 개라서","correct":true},{"t":"합동인 원이 두 개 있어서","mis":"M6-2-u6-X14"},{"t":"원을 면으로 하지 않아서","mis":"M6-2-u6-X14"},{"t":"평평한 면도 뾰족한 점도 없어서","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","원뿔에는 뾰족한 점이 하나 있어요.","「위쪽이 뾰족하지 않고 잘려 작은 원이 있는 화분」은 뾰족한 점이 없고 원이 두 개라서 원뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#7','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'ox','auto','원뿔은 한 원을 면으로 하는 입체도형이에요.',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":7,"concept":"M6-2-u6-C5","difficulty":2,"kind":"ox","stem":"원뿔은 한 원을 면으로 하는 입체도형이에요.","answer":"O","reason_options":[{"t":"원뿔에는 면이 되는 원이 하나 있기 때문에","correct":true},{"t":"원뿔에는 서로 합동인 두 원이 있기 때문에","mis":"M6-2-u6-X14"}],"mis":"M6-2-u6-X14","explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."],"variant_rule":{"alt":[{"stem":"밑면이 원인 뿔 모양도 각뿔이라고 불러요.","answer":"X","reason_options":[{"t":"각뿔은 밑면이 다각형이고 원은 다각형이 아니기 때문에","correct":true},{"t":"뿔 모양은 모두 각뿔이기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]},{"stem":"직각삼각형을 한 바퀴 돌리면 원뿔이 돼요.","answer":"O","reason_options":[{"t":"직각을 낀 변을 기준으로 돌리면 뾰족한 점과 원이 생기기 때문에","correct":true},{"t":"삼각형을 돌리면 언제나 구가 되기 때문에","mis":"M6-2-u6-X03"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#8','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'sa','auto','가 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 나 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 다 밑면이 사각형이고 옆면이 모두 삼각형인 지붕 · 라 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원뿔 모양은 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"가 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 나 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 다 밑면이 사각형이고 옆면이 모두 삼각형인 지붕 · 라 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원뿔 모양은 몇 개인가요?","answer":["1"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 가예요.","모두 1개예요."],"mis":"M6-2-u6-X14","variant_rule":{"alt":[{"stem":"가 한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘 · 나 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 다 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 라 밑면이 오각형이고 옆면이 모두 삼각형인 탑 지붕 — 이 가운데 원뿔 모양은 몇 개인가요?","answer":["2"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 가, 나예요.","모두 2개예요."]},{"stem":"가 위쪽 원이 아래쪽 원보다 작은 컵 · 나 한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘 · 다 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 라 굽은 면으로만 둘러싸인 구슬 — 이 가운데 원뿔 모양은 몇 개인가요?","answer":["1"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 나예요.","모두 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#9','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',2,'mc','auto','원기둥과 원뿔의 다른 점은 어느 것인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X14','M6-2-u6-X06']::text[],true,'{"seq":9,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"원기둥과 원뿔의 다른 점은 어느 것인가요?","options":[{"t":"원기둥은 밑면이 2개, 원뿔은 1개예요","correct":true},{"t":"원기둥은 밑면이 원, 원뿔은 다각형이에요","mis":"M6-2-u6-X01"},{"t":"원뿔에는 옆면이 없어요","mis":"M6-2-u6-X14"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 원뿔의 같은 점은 어느 것인가요?","options":[{"t":"밑면이 원이고 옆면이 굽은 면이에요","correct":true},{"t":"밑면의 수가 같아요","mis":"M6-2-u6-X05"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"},{"t":"모선이 있어요","mis":"M6-2-u6-X15"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]},{"stem":"원뿔에는 있고 원기둥에는 없는 것은 어느 것인가요?","options":[{"t":"뾰족한 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X14"},{"t":"높이","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_basic#10','math',6,2,'u6','L06','g6_2_math_u6_L06_basic','lesson_basic','M6-2-u6-C5',3,'mc','auto','다음 가운데 원뿔 모양은 어느 것인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X01']::text[],true,'{"seq":10,"concept":"M6-2-u6-C5","difficulty":3,"kind":"mc","stem":"다음 가운데 원뿔 모양은 어느 것인가요?","options":[{"t":"한 원을 면으로 하고 뾰족한 점이 있는 고깔모자","correct":true},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄","mis":"M6-2-u6-X14"},{"t":"밑면이 사각형이고 옆면이 모두 삼각형인 지붕","mis":"M6-2-u6-X01"},{"t":"위쪽 원이 아래쪽 원보다 작은 컵","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「한 원을 면으로 하고 뾰족한 점이 있는 고깔모자」가 원뿔이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원뿔 모양은 어느 것인가요?","options":[{"t":"한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘","correct":true},{"t":"밑면이 오각형이고 옆면이 모두 삼각형인 탑 지붕","mis":"M6-2-u6-X01"},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔","mis":"M6-2-u6-X14"},{"t":"굽은 면으로만 둘러싸인 축구공","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘」이 원뿔이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원뿔 모양은 어느 것인가요?","options":[{"t":"한 원을 면으로 하고 뾰족한 점이 있는 고깔모자","correct":true},{"t":"서로 평행하고 합동인 두 육각형을 면으로 하는 연필","mis":"M6-2-u6-X01"},{"t":"굽은 면으로만 둘러싸인 구슬","mis":"M6-2-u6-X01"},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 북","mis":"M6-2-u6-X14"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","보기를 이 뜻에 하나씩 대어 봐요.","「한 원을 면으로 하고 뾰족한 점이 있는 고깔모자」가 원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#1','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',2,'sa','auto','세 변이 9 cm, 12 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"세 변이 9 cm, 12 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","가장 긴 변 15 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 높이는 12 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 8 cm, 6 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 6 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 반지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 변 6 cm는 원뿔의 높이, 뻗어 나간 변 8 cm는 밑면의 반지름이 돼요.","가장 긴 변 10 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 밑면의 반지름은 8 cm예요."]},{"stem":"세 변이 12 cm, 5 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 5 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?","answer":["5"],"explanation":["막대에 붙인 변 5 cm는 원뿔의 높이, 뻗어 나간 변 12 cm는 밑면의 반지름이 돼요.","가장 긴 변 13 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 높이는 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#2','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',2,'mc','auto','원뿔에는 있고 원기둥에는 없는 것은 어느 것인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X14','M6-2-u6-X06']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":2,"kind":"mc","stem":"원뿔에는 있고 원기둥에는 없는 것은 어느 것인가요?","options":[{"t":"뾰족한 꼭짓점","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X14"},{"t":"높이","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."],"variant_rule":{"alt":[{"stem":"원기둥과 원뿔의 다른 점은 어느 것인가요?","options":[{"t":"원기둥은 밑면이 2개, 원뿔은 1개예요","correct":true},{"t":"원기둥은 밑면이 원, 원뿔은 다각형이에요","mis":"M6-2-u6-X01"},{"t":"원뿔에는 옆면이 없어요","mis":"M6-2-u6-X14"},{"t":"원기둥은 높이가 없어요","mis":"M6-2-u6-X06"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]},{"stem":"원기둥과 원뿔의 같은 점은 어느 것인가요?","options":[{"t":"밑면이 원이고 옆면이 굽은 면이에요","correct":true},{"t":"밑면의 수가 같아요","mis":"M6-2-u6-X05"},{"t":"꼭짓점이 있어요","mis":"M6-2-u6-X07"},{"t":"모선이 있어요","mis":"M6-2-u6-X15"}],"explanation":["원기둥과 원뿔 모두 밑면이 원이고 옆면이 굽은 면이에요.","원기둥은 밑면이 2개, 원뿔은 1개예요.","원뿔에는 뾰족한 꼭짓점이 있고 원기둥에는 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#3','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'error','auto','원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C5","difficulty":3,"kind":"error","stem":"원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「원기둥도 원이 있으니 원뿔이야.」","correct":true,"mis_target":"M6-2-u6-X14"},{"t":"순달 — 「원뿔은 한 원을 면으로 해.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「직각삼각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원뿔에는 뾰족한 점이 있어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔은 한 원을 면으로 하고 뾰족한 점이 하나 있어요.","원기둥은 합동인 원이 두 개이고 뾰족한 점이 없어요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「원기둥도 원이 있으니 원뿔이야.」","correct":true,"mis_target":"M6-2-u6-X14"},{"t":"지석 — 「원뿔은 한 원을 면으로 해.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「직각삼각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「원뿔에는 뾰족한 점이 있어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔은 한 원을 면으로 하고 뾰족한 점이 하나 있어요.","원기둥은 합동인 원이 두 개이고 뾰족한 점이 없어요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「원기둥도 원이 있으니 원뿔이야.」","correct":true,"mis_target":"M6-2-u6-X14"},{"t":"나린 — 「원뿔은 한 원을 면으로 해.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「직각삼각형을 돌려서 만들 수 있어.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「원뿔에는 뾰족한 점이 있어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔은 한 원을 면으로 하고 뾰족한 점이 하나 있어요.","원기둥은 합동인 원이 두 개이고 뾰족한 점이 없어요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#4','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C5","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"밑면이 다각형인 뿔","r":"각뿔"},{"l":"밑면이 원인 뿔","r":"원뿔"},{"l":"밑면이 원인 기둥","r":"원기둥"}],"mis":"M6-2-u6-X01","explanation":["밑면이 다각형이면 각기둥·각뿔, 원이면 원기둥·원뿔이에요.","원뿔의 밑면은 1개, 원기둥은 2개, 구는 평평한 면이 없어요.","직각삼각형은 원뿔, 직사각형은 원기둥, 반원은 구가 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원뿔의 밑면의 수","r":"1개"},{"l":"원기둥의 밑면의 수","r":"2개"},{"l":"구의 평평한 면의 수","r":"0개"}],"explanation":["밑면이 다각형이면 각기둥·각뿔, 원이면 원기둥·원뿔이에요.","원뿔의 밑면은 1개, 원기둥은 2개, 구는 평평한 면이 없어요.","직각삼각형은 원뿔, 직사각형은 원기둥, 반원은 구가 돼요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"직각삼각형","r":"원뿔"},{"l":"직사각형","r":"원기둥"},{"l":"반원","r":"구"}],"explanation":["밑면이 다각형이면 각기둥·각뿔, 원이면 원기둥·원뿔이에요.","원뿔의 밑면은 1개, 원기둥은 2개, 구는 평평한 면이 없어요.","직각삼각형은 원뿔, 직사각형은 원기둥, 반원은 구가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#5','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'ox','auto','원기둥에도 원이 있으니 원뿔이라고 할 수 있어요.',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":5,"concept":"M6-2-u6-C5","difficulty":3,"kind":"ox","stem":"원기둥에도 원이 있으니 원뿔이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"원기둥은 합동인 원이 두 개이고 뾰족한 점이 없기 때문에","correct":true},{"t":"원이 있으면 모두 원뿔이기 때문에","mis":"M6-2-u6-X14"}],"mis":"M6-2-u6-X14","explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."],"variant_rule":{"alt":[{"stem":"원뿔의 옆면은 평평한 삼각형이에요.","answer":"X","reason_options":[{"t":"원뿔의 옆면은 굽은 면이기 때문에","correct":true},{"t":"원뿔은 각뿔과 옆면이 같기 때문에","mis":"M6-2-u6-X01"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]},{"stem":"직각삼각형을 돌릴 때 막대에 붙인 변은 원뿔의 높이가 돼요.","answer":"O","reason_options":[{"t":"막대에 붙은 변이 꼭짓점에서 밑면에 수직으로 서기 때문에","correct":true},{"t":"막대에 붙인 변은 모선이 되기 때문에","mis":"M6-2-u6-X04"}],"explanation":["원뿔은 한 원을 면으로 하는 입체도형이에요.","각뿔은 밑면이 다각형, 원뿔은 원이에요.","직각삼각형을 한 바퀴 돌리면 원뿔이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#6','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'sa','auto','세 변이 4 cm, 3 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 3 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름과 높이의 합은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C5","difficulty":3,"kind":"sa","stem":"세 변이 4 cm, 3 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 3 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["11"],"explanation":["막대에 붙인 변 3 cm는 원뿔의 높이, 뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","가장 긴 변 5 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름 8 cm와 높이 3 cm — 8 + 3 = 11 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 6 cm, 8 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["20"],"explanation":["막대에 붙인 변 8 cm는 원뿔의 높이, 뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","가장 긴 변 10 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름 12 cm와 높이 8 cm — 12 + 8 = 20 cm예요."]},{"stem":"세 변이 12 cm, 9 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 9 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름과 높이의 합은 몇 cm인가요?","answer":["33"],"explanation":["막대에 붙인 변 9 cm는 원뿔의 높이, 뻗어 나간 변 12 cm는 밑면의 반지름이 돼요.","가장 긴 변 15 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름 24 cm와 높이 9 cm — 24 + 9 = 33 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#7','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',3,'sa','auto','가 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 나 한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘 · 다 밑면이 사각형이고 옆면이 모두 삼각형인 지붕 · 라 밑면이 오각형이고 옆면이 모두 삼각형인 탑 지붕 · 마 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원뿔 모양은 몇 개인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C5","difficulty":3,"kind":"sa","stem":"가 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 나 한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘 · 다 밑면이 사각형이고 옆면이 모두 삼각형인 지붕 · 라 밑면이 오각형이고 옆면이 모두 삼각형인 탑 지붕 · 마 굽은 면으로만 둘러싸인 축구공 — 이 가운데 원뿔 모양은 몇 개인가요?","answer":["2"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 가, 나예요.","모두 2개예요."],"mis":"M6-2-u6-X14","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 원을 면으로 하는 김밥 한 줄 · 나 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 다 위쪽 원이 아래쪽 원보다 작은 컵 · 라 서로 평행하고 합동인 두 육각형을 면으로 하는 연필 · 마 굽은 면으로만 둘러싸인 구슬 — 이 가운데 원뿔 모양은 몇 개인가요?","answer":["1"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 나예요.","모두 1개예요."]},{"stem":"가 한 원을 면으로 하고 뾰족한 점이 있는 아이스크림 콘 · 나 서로 평행하고 합동인 두 원을 면으로 하는 음료수 캔 · 다 한 원을 면으로 하고 뾰족한 점이 있는 고깔모자 · 라 서로 평행하고 합동인 두 원을 면으로 하는 북 · 마 두 원이 비스듬히 잘려 평행하지 않은 통 — 이 가운데 원뿔 모양은 몇 개인가요?","answer":["2"],"explanation":["원뿔의 뜻에 하나씩 대어 봐요.","원뿔인 것은 가, 다예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#8','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',4,'sa','auto','직각을 낀 두 변이 3 cm, 4 cm인 직각삼각형이 있어요. 3 cm 변을 막대에 붙여 돌린 원뿔과 4 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C5","difficulty":4,"kind":"sa","stem":"직각을 낀 두 변이 3 cm, 4 cm인 직각삼각형이 있어요. 3 cm 변을 막대에 붙여 돌린 원뿔과 4 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?","answer":["2"],"explanation":["3 cm 변을 붙이면 다른 변 4 cm가 반지름 — 지름 8 cm예요.","4 cm 변을 붙이면 반지름 3 cm — 지름 6 cm예요.","8 - 6 = 2 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"직각을 낀 두 변이 5 cm, 12 cm인 직각삼각형이 있어요. 5 cm 변을 막대에 붙여 돌린 원뿔과 12 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?","answer":["14"],"explanation":["5 cm 변을 붙이면 다른 변 12 cm가 반지름 — 지름 24 cm예요.","12 cm 변을 붙이면 반지름 5 cm — 지름 10 cm예요.","24 - 10 = 14 cm예요."]},{"stem":"직각을 낀 두 변이 8 cm, 15 cm인 직각삼각형이 있어요. 8 cm 변을 막대에 붙여 돌린 원뿔과 15 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?","answer":["14"],"explanation":["8 cm 변을 붙이면 다른 변 15 cm가 반지름 — 지름 30 cm예요.","15 cm 변을 붙이면 반지름 8 cm — 지름 16 cm예요.","30 - 16 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#9','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',4,'sa','auto','직각을 낀 두 변이 6 cm, 8 cm인 직각삼각형이 있어요. 6 cm 변을 막대에 붙여 돌린 원뿔과 8 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C5","difficulty":4,"kind":"sa","stem":"직각을 낀 두 변이 6 cm, 8 cm인 직각삼각형이 있어요. 6 cm 변을 막대에 붙여 돌린 원뿔과 8 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?","answer":["4"],"explanation":["6 cm 변을 붙이면 다른 변 8 cm가 반지름 — 지름 16 cm예요.","8 cm 변을 붙이면 반지름 6 cm — 지름 12 cm예요.","16 - 12 = 4 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"직각을 낀 두 변이 9 cm, 12 cm인 직각삼각형이 있어요. 9 cm 변을 막대에 붙여 돌린 원뿔과 12 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?","answer":["6"],"explanation":["9 cm 변을 붙이면 다른 변 12 cm가 반지름 — 지름 24 cm예요.","12 cm 변을 붙이면 반지름 9 cm — 지름 18 cm예요.","24 - 18 = 6 cm예요."]},{"stem":"직각을 낀 두 변이 12 cm, 5 cm인 직각삼각형이 있어요. 5 cm 변을 막대에 붙여 돌린 원뿔과 12 cm 변을 막대에 붙여 돌린 원뿔의 밑면의 지름의 차는 몇 cm인가요?","answer":["14"],"explanation":["5 cm 변을 붙이면 다른 변 12 cm가 반지름 — 지름 24 cm예요.","12 cm 변을 붙이면 반지름 5 cm — 지름 10 cm예요.","24 - 10 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L06_challenge#10','math',6,2,'u6','L06','g6_2_math_u6_L06_challenge','lesson_challenge','M6-2-u6-C5',4,'essay','teacher','원기둥과 원뿔은 모두 밑면이 원이고 옆면이 굽은 면이에요. 두 입체도형의 다른 점을 두 가지 이상 쓰고, 각각 어떤 평면도형을 돌려 만들 수 있는지 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C5","difficulty":4,"kind":"essay","stem":"원기둥과 원뿔은 모두 밑면이 원이고 옆면이 굽은 면이에요. 두 입체도형의 다른 점을 두 가지 이상 쓰고, 각각 어떤 평면도형을 돌려 만들 수 있는지 설명해 보세요.","answer_guide":{"answer":"예: 원기둥은 서로 평행하고 합동인 원이 두 개(밑면 2개)이고 뾰족한 점이 없지만, 원뿔은 원이 하나(밑면 1개)이고 뾰족한 꼭짓점이 있다. 원기둥은 직사각형을, 원뿔은 직각삼각형을 한 변을 기준으로 한 바퀴 돌려 만든다.","scoring_points":["밑면의 수(2개·1개) 차이를 썼는가","꼭짓점(뾰족한 점)의 유무를 썼는가","직사각형·직각삼각형을 돌려 만든다고 썼는가"]},"explanation":["원기둥은 원 2개, 원뿔은 원 1개예요.","원뿔에만 뾰족한 꼭짓점이 있어요.","직사각형은 원기둥, 직각삼각형은 원뿔이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#1','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'mc','auto','원뿔에서 면이 되는 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":1,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 면이 되는 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","면이 되는 원을 밑면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#2','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'mc','auto','원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":2,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 높이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","밑면과 만나는 굽은 면을 옆면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#3','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'sa','auto','원뿔의 밑면은 몇 개인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C6","difficulty":1,"kind":"sa","stem":"원뿔의 밑면은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 밑면은 원 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원뿔의 꼭짓점은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 꼭짓점은 뾰족한 점 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]},{"stem":"원기둥·원뿔·구의 꼭짓점의 수를 모두 더하면 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개, 원기둥 0개, 구 0개 — 모두 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#4','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',1,'sa','auto','원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C6","difficulty":1,"kind":"sa","stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["8"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 10 cm는 모선이에요.","그래서 높이는 8 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 5 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 5 cm는 모선이에요.","그래서 높이는 4 cm예요."]},{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 15 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 밑면의 반지름은 9 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 15 cm는 모선이에요.","그래서 높이는 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#5','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'sa','auto','원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["10"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 8 cm는 높이예요.","그래서 모선은 10 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 13 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["13"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 12 cm는 높이예요.","그래서 모선은 13 cm예요."]},{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 17 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 15 cm는 높이예요.","그래서 모선은 17 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#6','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'mc','auto','원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?',ARRAY['M6-2-u6-X16','M6-2-u6-X15']::text[],true,'{"seq":6,"concept":"M6-2-u6-C6","difficulty":2,"kind":"mc","stem":"원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?","options":[{"t":"모선은 둘레까지 비스듬히 가고 높이는 한가운데까지 곧게 가서","correct":true},{"t":"모선이 여러 개여서","mis":"M6-2-u6-X16"},{"t":"밑면이 원이어서","mis":"M6-2-u6-X15"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"원뿔의 모선은 몇 개인가요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M6-2-u6-X16"},{"t":"2개","mis":"M6-2-u6-X16"},{"t":"4개","mis":"M6-2-u6-X16"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]},{"stem":"한 원뿔에서 모선의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"모두 달라요","mis":"M6-2-u6-X16"},{"t":"둘레 쪽으로 갈수록 길어져요","mis":"M6-2-u6-X16"},{"t":"높이와 같아요","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#7','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'ox','auto','원뿔의 모선은 하나뿐이에요.',ARRAY['M6-2-u6-X16']::text[],true,'{"seq":7,"concept":"M6-2-u6-C6","difficulty":2,"kind":"ox","stem":"원뿔의 모선은 하나뿐이에요.","answer":"X","reason_options":[{"t":"밑면 둘레의 점마다 모선을 그을 수 있어 무수히 많기 때문에","correct":true},{"t":"원뿔의 꼭짓점이 하나이기 때문에","mis":"M6-2-u6-X16"}],"mis":"M6-2-u6-X16","explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."],"variant_rule":{"alt":[{"stem":"원뿔의 높이는 모선보다 짧아요.","answer":"O","reason_options":[{"t":"높이는 곧게, 모선은 비스듬히 내려가기 때문에","correct":true},{"t":"높이는 밑면의 지름과 같기 때문에","mis":"M6-2-u6-X15"}],"explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]},{"stem":"한 원뿔에서 모선의 길이는 모두 같아요.","answer":"O","reason_options":[{"t":"꼭짓점에서 밑면 둘레의 어느 점까지나 거리가 같기 때문에","correct":true},{"t":"모선은 하나뿐이기 때문에","mis":"M6-2-u6-X16"}],"explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#8','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'error','auto','원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X05','M6-2-u6-X19']::text[],true,'{"seq":8,"concept":"M6-2-u6-C6","difficulty":2,"kind":"error","stem":"원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지석 — 「원뿔에서 밑면은 2개야.」","correct":true,"mis_target":"M6-2-u6-X05"},{"t":"민지 — 「원뿔의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「원뿔의 꼭짓점은 1개야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「원뿔에는 모서리가 없어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔에는 면이 되는 원이 하나 — 밑면은 1개예요.","옆면은 굽은 면, 꼭짓점은 1개, 모서리는 없어요.","그래서 지석의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"순달 — 「원뿔에서 밑면은 2개야.」","correct":true,"mis_target":"M6-2-u6-X05"},{"t":"여울 — 「원뿔의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「원뿔의 꼭짓점은 1개야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원뿔에는 모서리가 없어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔에는 면이 되는 원이 하나 — 밑면은 1개예요.","옆면은 굽은 면, 꼭짓점은 1개, 모서리는 없어요.","그래서 순달의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 원뿔에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나린 — 「원뿔에서 밑면은 2개야.」","correct":true,"mis_target":"M6-2-u6-X05"},{"t":"가온 — 「원뿔의 옆면은 굽은 면이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「원뿔의 꼭짓점은 1개야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「원뿔에는 모서리가 없어.」","mis":"M6-2-u6-X19"}],"explanation":["원뿔에는 면이 되는 원이 하나 — 밑면은 1개예요.","옆면은 굽은 면, 꼭짓점은 1개, 모서리는 없어요.","그래서 나린의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#9','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',2,'sa','auto','밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["20"],"explanation":["밑면의 지름은 6 × 2 = 12 cm예요.","높이는 8 cm예요 — 모선 10 cm는 쓰지 않아요.","12 + 8 = 20 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"밑면의 반지름이 3 cm, 높이가 4 cm, 모선이 5 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["10"],"explanation":["밑면의 지름은 3 × 2 = 6 cm예요.","높이는 4 cm예요 — 모선 5 cm는 쓰지 않아요.","6 + 4 = 10 cm예요."]},{"stem":"밑면의 반지름이 8 cm, 높이가 6 cm, 모선이 10 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["22"],"explanation":["밑면의 지름은 8 × 2 = 16 cm예요.","높이는 6 cm예요 — 모선 10 cm는 쓰지 않아요.","16 + 6 = 22 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_basic#10','math',6,2,'u6','L07','g6_2_math_u6_L07_basic','lesson_basic','M6-2-u6-C6',3,'mc','auto','한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X16','M6-2-u6-X19']::text[],true,'{"seq":10,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"8 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 8 cm가 높이, 긴 10 cm가 모선이에요."],"variant_rule":{"alt":[{"stem":"한 원뿔에서 두 선분의 길이가 12 cm와 13 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"12 cm","correct":true},{"t":"13 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 12 cm가 높이, 긴 13 cm가 모선이에요."]},{"stem":"한 원뿔에서 두 선분의 길이가 15 cm와 17 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"15 cm","correct":true},{"t":"17 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 15 cm가 높이, 긴 17 cm가 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#1','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',2,'mc','auto','한 원뿔에서 두 선분의 길이가 12 cm와 15 cm예요. 이 원뿔의 높이는 어느 것인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X16','M6-2-u6-X19']::text[],true,'{"seq":1,"concept":"M6-2-u6-C6","difficulty":2,"kind":"mc","stem":"한 원뿔에서 두 선분의 길이가 12 cm와 15 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"12 cm","correct":true},{"t":"15 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 12 cm가 높이, 긴 15 cm가 모선이에요."],"variant_rule":{"alt":[{"stem":"한 원뿔에서 두 선분의 길이가 4 cm와 5 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"4 cm","correct":true},{"t":"5 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 4 cm가 높이, 긴 5 cm가 모선이에요."]},{"stem":"한 원뿔에서 두 선분의 길이가 8 cm와 17 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"8 cm","correct":true},{"t":"17 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 8 cm가 높이, 긴 17 cm가 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#2','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',2,'sa','auto','원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?','{}'::text[],true,'{"seq":2,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?","answer":["3"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개와 원기둥 2개 — 1 + 2 = 3개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥·원뿔·구의 꼭짓점의 수를 모두 더하면 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개, 원기둥 0개, 구 0개 — 모두 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]},{"stem":"원뿔의 꼭짓점은 몇 개인가요?","answer":["1"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔의 꼭짓점은 뾰족한 점 하나 — 1개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#3','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'error','auto','밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C6","difficulty":3,"kind":"error","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「이 원뿔의 높이는 10 cm야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"순달 — 「모선이 높이보다 길어.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「밑면의 지름은 12 cm야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「모선은 무수히 많고 길이가 모두 10 cm야.」","mis":"M6-2-u6-X19"}],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 8 cm예요.","10 cm는 모선의 길이예요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 5 cm, 높이가 12 cm, 모선이 13 cm인 원뿔을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「이 원뿔의 높이는 13 cm야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"지석 — 「모선이 높이보다 길어.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「밑면의 지름은 10 cm야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「모선은 무수히 많고 길이가 모두 13 cm야.」","mis":"M6-2-u6-X19"}],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 12 cm예요.","13 cm는 모선의 길이예요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선이 15 cm인 원뿔을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「이 원뿔의 높이는 15 cm야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"나린 — 「모선이 높이보다 길어.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「밑면의 지름은 18 cm야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「모선은 무수히 많고 길이가 모두 15 cm야.」","mis":"M6-2-u6-X19"}],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 12 cm예요.","15 cm는 모선의 길이예요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#4','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'ox','auto','원뿔의 높이는 꼭짓점과 밑면 둘레의 한 점을 이은 선분이에요.',ARRAY['M6-2-u6-X15']::text[],true,'{"seq":4,"concept":"M6-2-u6-C6","difficulty":3,"kind":"ox","stem":"원뿔의 높이는 꼭짓점과 밑면 둘레의 한 점을 이은 선분이에요.","answer":"X","reason_options":[{"t":"그 선분은 모선이고 높이는 밑면에 수직으로 내린 선분의 길이이기 때문에","correct":true},{"t":"높이와 모선은 같은 뜻이기 때문에","mis":"M6-2-u6-X15"}],"mis":"M6-2-u6-X15","explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."],"variant_rule":{"alt":[{"stem":"원뿔의 밑면은 1개예요.","answer":"O","reason_options":[{"t":"원뿔은 한 원을 면으로 하기 때문에","correct":true},{"t":"원뿔은 원기둥처럼 원이 두 개이기 때문에","mis":"M6-2-u6-X05"}],"explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]},{"stem":"원뿔에는 꼭짓점이 2개 있어요.","answer":"X","reason_options":[{"t":"뾰족한 부분의 점 하나만 원뿔의 꼭짓점이기 때문에","correct":true},{"t":"밑면에도 꼭짓점이 하나 있기 때문에","mis":"M6-2-u6-X07"}],"explanation":["원뿔은 밑면 1개, 꼭짓점 1개예요.","모선은 무수히 많고 길이가 모두 같아요.","높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이 — 모선보다 짧아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#5','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'match','auto','원뿔에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":3,"kind":"match","stem":"원뿔에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"뾰족한 부분의 점","r":"원뿔의 꼭짓점"},{"l":"꼭짓점과 밑면 둘레의 한 점을 이은 선분","r":"모선"},{"l":"꼭짓점에서 밑면에 수직으로 내린 선분의 길이","r":"높이"}],"mis":"M6-2-u6-X15","explanation":["뾰족한 점은 원뿔의 꼭짓점이에요.","꼭짓점과 둘레의 한 점을 이은 선분은 모선 — 무수히 많아요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 원뿔에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"원뿔의 밑면","r":"원 1개"},{"l":"원뿔의 모선","r":"무수히 많음"},{"l":"원뿔의 꼭짓점","r":"1개"}],"explanation":["뾰족한 점은 원뿔의 꼭짓점이에요.","꼭짓점과 둘레의 한 점을 이은 선분은 모선 — 무수히 많아요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."]},{"stem":"이번에는 다른 보기예요. 원뿔에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"면이 되는 원","r":"밑면"},{"l":"밑면과 만나는 굽은 면","r":"옆면"},{"l":"비스듬히 둘레까지 이은 선분","r":"모선"}],"explanation":["뾰족한 점은 원뿔의 꼭짓점이에요.","꼭짓점과 둘레의 한 점을 이은 선분은 모선 — 무수히 많아요.","꼭짓점에서 밑면에 수직으로 내린 선분의 길이가 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#6','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'mc','auto','원뿔의 모선은 몇 개인가요?',ARRAY['M6-2-u6-X16']::text[],true,'{"seq":6,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"원뿔의 모선은 몇 개인가요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M6-2-u6-X16"},{"t":"2개","mis":"M6-2-u6-X16"},{"t":"4개","mis":"M6-2-u6-X16"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"한 원뿔에서 모선의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"모두 달라요","mis":"M6-2-u6-X16"},{"t":"둘레 쪽으로 갈수록 길어져요","mis":"M6-2-u6-X16"},{"t":"높이와 같아요","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]},{"stem":"원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?","options":[{"t":"모선은 둘레까지 비스듬히 가고 높이는 한가운데까지 곧게 가서","correct":true},{"t":"모선이 여러 개여서","mis":"M6-2-u6-X16"},{"t":"밑면이 원이어서","mis":"M6-2-u6-X15"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#7','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',3,'sa','auto','밑면의 반지름이 9 cm, 높이가 12 cm, 모선이 15 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C6","difficulty":3,"kind":"sa","stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선이 15 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["30"],"explanation":["밑면의 지름은 9 × 2 = 18 cm예요.","높이는 12 cm예요 — 모선 15 cm는 쓰지 않아요.","18 + 12 = 30 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"밑면의 반지름이 8 cm, 높이가 15 cm, 모선이 17 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["31"],"explanation":["밑면의 지름은 8 × 2 = 16 cm예요.","높이는 15 cm예요 — 모선 17 cm는 쓰지 않아요.","16 + 15 = 31 cm예요."]},{"stem":"밑면의 반지름이 12 cm, 높이가 5 cm, 모선이 13 cm인 원뿔이 있어요. 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["29"],"explanation":["밑면의 지름은 12 × 2 = 24 cm예요.","높이는 5 cm예요 — 모선 13 cm는 쓰지 않아요.","24 + 5 = 29 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#8','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',4,'sa','auto','밑면의 반지름이 3 cm, 높이가 4 cm, 모선이 5 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C6","difficulty":4,"kind":"sa","stem":"밑면의 반지름이 3 cm, 높이가 4 cm, 모선이 5 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["앞에서 본 삼각형의 밑변은 지름 6 cm예요.","두 옆 변은 모선 5 cm씩이에요 — 높이는 둘레에 들어가지 않아요.","6 + 5 + 5 = 16 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?","answer":["32"],"explanation":["앞에서 본 삼각형의 밑변은 지름 12 cm예요.","두 옆 변은 모선 10 cm씩이에요 — 높이는 둘레에 들어가지 않아요.","12 + 10 + 10 = 32 cm예요."]},{"stem":"밑면의 반지름이 5 cm, 높이가 12 cm, 모선이 13 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["앞에서 본 삼각형의 밑변은 지름 10 cm예요.","두 옆 변은 모선 13 cm씩이에요 — 높이는 둘레에 들어가지 않아요.","10 + 13 + 13 = 36 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#9','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',4,'sa','auto','세 변이 8 cm, 15 cm, 17 cm인 직각삼각형 모양의 종이가 있어요. 길이가 15 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C6","difficulty":4,"kind":"sa","stem":"세 변이 8 cm, 15 cm, 17 cm인 직각삼각형 모양의 종이가 있어요. 길이가 15 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["막대에 붙인 변 15 cm는 원뿔의 높이, 뻗어 나간 변 8 cm는 밑면의 반지름이 돼요.","가장 긴 변 17 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 모선의 길이는 17 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"세 변이 15 cm, 8 cm, 17 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["막대에 붙인 변 8 cm는 원뿔의 높이, 뻗어 나간 변 15 cm는 밑면의 반지름이 돼요.","가장 긴 변 17 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 모선의 길이는 17 cm예요."]},{"stem":"세 변이 5 cm, 12 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 모선의 길이는 몇 cm인가요?","answer":["13"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","가장 긴 변 13 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 모선의 길이는 13 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L07_challenge#10','math',6,2,'u6','L07','g6_2_math_u6_L07_challenge','lesson_challenge','M6-2-u6-C6',4,'essay','teacher','원뿔에서 모선은 몇 개인지, 모선의 길이는 어떤지 쓰고, 모선이 높이보다 긴 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C6","difficulty":4,"kind":"essay","stem":"원뿔에서 모선은 몇 개인지, 모선의 길이는 어떤지 쓰고, 모선이 높이보다 긴 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 모선은 원뿔의 꼭짓점과 밑면 둘레의 한 점을 이은 선분이라 둘레의 점마다 그을 수 있어 무수히 많고, 길이는 모두 같다. 높이는 꼭짓점에서 밑면의 한가운데로 곧게 내려가지만 모선은 둘레까지 비스듬히 가므로 모선이 더 길다.","scoring_points":["모선이 무수히 많다고 썼는가","모선의 길이가 모두 같다고 썼는가","비스듬히·곧게의 차이로 모선이 더 긴 까닭을 썼는가"]},"explanation":["둘레의 점마다 모선 — 무수히 많아요.","모선의 길이는 모두 같아요.","비스듬히 가는 모선이 곧게 가는 높이보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#1','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','구는 어떻게 만든 입체도형인가요?',ARRAY['M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"구는 어떻게 만든 입체도형인가요?","options":[{"t":"지름을 따라 반으로 나눈 원을 지름을 기준으로 한 바퀴 돌려서 만든 입체도형","correct":true},{"t":"직사각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"직각삼각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."],"variant_rule":{"alt":[{"stem":"돌리기 전 반원의 중심은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 중심","correct":true},{"t":"구의 반지름","mis":"M6-2-u6-X17"},{"t":"구의 밑면","mis":"M6-2-u6-X07"},{"t":"구의 꼭짓점","mis":"M6-2-u6-X07"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]},{"stem":"돌리기 전 반원의 반지름은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 반지름","correct":true},{"t":"구의 중심","mis":"M6-2-u6-X17"},{"t":"구의 지름","mis":"M6-2-u6-X04"},{"t":"구의 둘레","mis":"M6-2-u6-X17"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#2','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','구를 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":2,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"구를 앞에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 앞에서 본 모양은 원이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 위에서 본 모양은 원이에요."]},{"stem":"원뿔을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 위에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#3','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'sa','auto','반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":1,"kind":"sa","stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["8"],"explanation":["반원의 반지름은 구의 반지름이 돼요.","구의 반지름은 4 cm예요.","지름은 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 5 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["10"],"explanation":["반원의 반지름은 구의 반지름이 돼요.","구의 반지름은 5 cm예요.","지름은 5 × 2 = 10 cm예요."]},{"stem":"반지름이 7 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["14"],"explanation":["반원의 반지름은 구의 반지름이 돼요.","구의 반지름은 7 cm예요.","지름은 7 × 2 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#4','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',1,'mc','auto','원기둥을 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":4,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."],"variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 앞에서 본 모양은 삼각형이에요."]},{"stem":"구를 옆에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 옆에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#5','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'mc','auto','원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":5,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X18"},{"t":"원뿔","mis":"M6-2-u6-X18"},{"t":"세 가지 모두","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥·원뿔·구를 위에서 본 모양은 어떤가요?","options":[{"t":"모두 원이에요","correct":true},{"t":"모두 다른 모양이에요","mis":"M6-2-u6-X18"},{"t":"원기둥만 원이에요","mis":"M6-2-u6-X18"},{"t":"구만 원이에요","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."]},{"stem":"앞에서 본 모양이 삼각형인 입체도형은 무엇인가요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X18"},{"t":"구","mis":"M6-2-u6-X18"},{"t":"삼각기둥","mis":"M6-2-u6-X01"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#6','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'mc','auto','구에 대해 바르게 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X17','M6-2-u6-X05','M6-2-u6-X07']::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"구에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구의 반지름은 무수히 많고 그 길이가 모두 같아요","correct":true},{"t":"구의 반지름은 무수히 많고 그 길이가 모두 달라요","mis":"M6-2-u6-X17"},{"t":"구는 밑면이 2개 있어요","mis":"M6-2-u6-X05"},{"t":"구에는 꼭짓점이 1개 있어요","mis":"M6-2-u6-X07"}],"explanation":["구의 반지름은 구의 중심에서 겉면의 한 점까지예요.","겉면의 점마다 그을 수 있어 무수히 많아요.","중심에서 겉면까지의 거리는 어디나 같아 길이도 모두 같아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 구에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구의 중심은 1개예요","correct":true},{"t":"구의 중심은 무수히 많아요","mis":"M6-2-u6-X17"},{"t":"구에는 평평한 면이 1개 있어요","mis":"M6-2-u6-X07"},{"t":"구를 앞에서 보면 반원이에요","mis":"M6-2-u6-X18"}],"explanation":["반원의 중심이 구의 중심이 되니 구의 중심은 1개예요.","구는 굽은 면으로만 이루어져 평평한 면이 없어요.","구는 어느 방향에서 보아도 원이에요."]},{"stem":"구에 대해 잘못 설명한 것은 어느 것인가요?","options":[{"t":"구의 반지름은 방향에 따라 길이가 달라요","correct":true},{"t":"구의 중심은 1개예요","mis":"M6-2-u6-X19"},{"t":"구에는 평평한 면이 없어요","mis":"M6-2-u6-X19"},{"t":"구는 어느 방향에서 보아도 원이에요","mis":"M6-2-u6-X19"}],"explanation":["구의 중심은 1개, 평평한 면은 없어요.","구는 어느 방향에서 보아도 원이에요.","구의 반지름은 무수히 많고 길이가 모두 같아요 — 방향마다 다르지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#7','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'sa','auto','원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 2개, 원뿔 1개, 구 0개 — 2 + 1 + 0 = 3개예요."],"mis":"M6-2-u6-X07","variant_rule":{"alt":[{"stem":"원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?","answer":["5"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 하나에 2개씩 4개, 원뿔 1개 — 4 + 1 = 5개예요."]},{"stem":"원뿔 3개와 구 2개의 평평한 면은 모두 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원뿔 하나에 1개씩 3개, 구는 0개 — 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#8','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'ox','auto','구의 중심은 1개예요.',ARRAY['M6-2-u6-X17']::text[],true,'{"seq":8,"concept":"M6-2-u6-C7","difficulty":2,"kind":"ox","stem":"구의 중심은 1개예요.","answer":"O","reason_options":[{"t":"돌리기 전 반원의 중심 하나가 구의 중심이 되기 때문에","correct":true},{"t":"구의 중심은 무수히 많기 때문에","mis":"M6-2-u6-X17"}],"mis":"M6-2-u6-X17","explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."],"variant_rule":{"alt":[{"stem":"구를 앞에서 본 모양은 반원이에요.","answer":"X","reason_options":[{"t":"구는 어느 방향에서 보아도 원이기 때문에","correct":true},{"t":"반원을 돌려 만들었기 때문에","mis":"M6-2-u6-X18"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]},{"stem":"구에는 평평한 면이 없어요.","answer":"O","reason_options":[{"t":"구는 굽은 면으로만 이루어져 있기 때문에","correct":true},{"t":"구의 밑면은 원 하나이기 때문에","mis":"M6-2-u6-X07"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#9','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',2,'sa','auto','지름이 12 cm인 공 모양 구슬이 있어요. 이 구의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"지름이 12 cm인 공 모양 구슬이 있어요. 이 구의 반지름은 몇 cm인가요?","answer":["6"],"explanation":["구의 반지름은 구의 중심에서 구의 겉면의 한 점까지예요.","반지름은 지름의 반이에요.","12 ÷ 2 = 6 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"지름이 18 cm인 공 모양 구슬이 있어요. 이 구의 반지름은 몇 cm인가요?","answer":["9"],"explanation":["구의 반지름은 구의 중심에서 구의 겉면의 한 점까지예요.","반지름은 지름의 반이에요.","18 ÷ 2 = 9 cm예요."]},{"stem":"지름이 30 cm인 공 모양 구슬이 있어요. 이 구의 반지름은 몇 cm인가요?","answer":["15"],"explanation":["구의 반지름은 구의 중심에서 구의 겉면의 한 점까지예요.","반지름은 지름의 반이에요.","30 ÷ 2 = 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_basic#10','math',6,2,'u6','L08','g6_2_math_u6_L08_basic','lesson_basic','M6-2-u6-C7',3,'sa','auto','반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 4 cm예요.","지름은 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 6 cm예요.","지름은 6 × 2 = 12 cm예요."]},{"stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["16"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 8 cm예요.","지름은 8 × 2 = 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#1','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',2,'sa','auto','반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"반지름이 8 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["16"],"explanation":["반원의 반지름은 구의 반지름이 돼요.","구의 반지름은 8 cm예요.","지름은 8 × 2 = 16 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 11 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["22"],"explanation":["반원의 반지름은 구의 반지름이 돼요.","구의 반지름은 11 cm예요.","지름은 11 × 2 = 22 cm예요."]},{"stem":"반지름이 12 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구의 지름은 몇 cm인가요?","answer":["24"],"explanation":["반원의 반지름은 구의 반지름이 돼요.","구의 반지름은 12 cm예요.","지름은 12 × 2 = 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#2','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',2,'mc','auto','원뿔을 옆에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":2,"concept":"M6-2-u6-C7","difficulty":2,"kind":"mc","stem":"원뿔을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 옆에서 본 모양은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 옆에서 본 모양은 직사각형이에요."]},{"stem":"구를 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 위에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#3','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'error','auto','구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u6-X18','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C7","difficulty":3,"kind":"error","stem":"구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「구를 옆에서 보면 반원이야.」","correct":true,"mis_target":"M6-2-u6-X18"},{"t":"순달 — 「구의 중심은 1개야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「구의 반지름은 모두 길이가 같아.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「구에는 평평한 면이 없어.」","mis":"M6-2-u6-X19"}],"explanation":["구는 어느 방향에서 보아도 원이에요.","반원은 구를 만들 때 돌린 모양일 뿐이에요.","그래서 여울의 말이 잘못되었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민지 — 「구를 옆에서 보면 반원이야.」","correct":true,"mis_target":"M6-2-u6-X18"},{"t":"지석 — 「구의 중심은 1개야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「구의 반지름은 모두 길이가 같아.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「구에는 평평한 면이 없어.」","mis":"M6-2-u6-X19"}],"explanation":["구는 어느 방향에서 보아도 원이에요.","반원은 구를 만들 때 돌린 모양일 뿐이에요.","그래서 민지의 말이 잘못되었어요."]},{"stem":"이번에는 다른 보기예요. 구에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「구를 옆에서 보면 반원이야.」","correct":true,"mis_target":"M6-2-u6-X18"},{"t":"나린 — 「구의 중심은 1개야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「구의 반지름은 모두 길이가 같아.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「구에는 평평한 면이 없어.」","mis":"M6-2-u6-X19"}],"explanation":["구는 어느 방향에서 보아도 원이에요.","반원은 구를 만들 때 돌린 모양일 뿐이에요.","그래서 가온의 말이 잘못되었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#4','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'ox','auto','구의 반지름은 방향에 따라 길이가 달라요.',ARRAY['M6-2-u6-X17']::text[],true,'{"seq":4,"concept":"M6-2-u6-C7","difficulty":3,"kind":"ox","stem":"구의 반지름은 방향에 따라 길이가 달라요.","answer":"X","reason_options":[{"t":"구의 중심에서 겉면의 어느 점까지나 거리가 같기 때문에","correct":true},{"t":"구는 공처럼 찌그러질 수 있기 때문에","mis":"M6-2-u6-X17"}],"mis":"M6-2-u6-X17","explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."],"variant_rule":{"alt":[{"stem":"원기둥·원뿔·구를 위에서 본 모양은 모두 원이에요.","answer":"O","reason_options":[{"t":"세 입체도형 모두 위에서 보면 둥근 테두리만 보이기 때문에","correct":true},{"t":"셋 다 앞에서 본 모양과 위에서 본 모양이 같기 때문에","mis":"M6-2-u6-X18"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]},{"stem":"직사각형을 한 바퀴 돌리면 구가 돼요.","answer":"X","reason_options":[{"t":"직사각형을 돌리면 원기둥, 반원을 돌려야 구가 되기 때문에","correct":true},{"t":"네 변이 모두 돌면 공 모양이 되기 때문에","mis":"M6-2-u6-X03"}],"explanation":["구는 반원을 지름을 기준으로 한 바퀴 돌려 만들어요.","구의 중심은 1개, 반지름은 무수히 많고 길이가 같아요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#5','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C7","difficulty":3,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥을 앞에서","r":"직사각형"},{"l":"원뿔을 앞에서","r":"삼각형"},{"l":"구를 앞에서","r":"원"}],"mis":"M6-2-u6-X18","explanation":["원기둥은 앞에서 직사각형, 원뿔은 삼각형, 구는 원이에요.","반원의 중심은 구의 중심, 반지름은 구의 반지름이 돼요.","평평한 면은 원기둥 2개, 원뿔 1개, 구 0개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"반원의 중심","r":"구의 중심"},{"l":"반원의 반지름","r":"구의 반지름"},{"l":"반원을 돌린 입체도형","r":"구"}],"explanation":["원기둥은 앞에서 직사각형, 원뿔은 삼각형, 구는 원이에요.","반원의 중심은 구의 중심, 반지름은 구의 반지름이 돼요.","평평한 면은 원기둥 2개, 원뿔 1개, 구 0개예요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"원기둥의 평평한 면","r":"2개"},{"l":"원뿔의 평평한 면","r":"1개"},{"l":"구의 평평한 면","r":"0개"}],"explanation":["원기둥은 앞에서 직사각형, 원뿔은 삼각형, 구는 원이에요.","반원의 중심은 구의 중심, 반지름은 구의 반지름이 돼요.","평평한 면은 원기둥 2개, 원뿔 1개, 구 0개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#6','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'sa','auto','반지름이 5 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"반지름이 5 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["10"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 5 × 2 = 10 cm예요.","그래서 한 모서리는 10 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 7 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["14"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 7 × 2 = 14 cm예요.","그래서 한 모서리는 14 cm예요."]},{"stem":"반지름이 9 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["18"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 9 × 2 = 18 cm예요.","그래서 한 모서리는 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#7','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',3,'mc','auto','구에 대해 잘못 설명한 것은 어느 것인가요?',ARRAY['M6-2-u6-X19']::text[],true,'{"seq":7,"concept":"M6-2-u6-C7","difficulty":3,"kind":"mc","stem":"구에 대해 잘못 설명한 것은 어느 것인가요?","options":[{"t":"구의 반지름은 방향에 따라 길이가 달라요","correct":true},{"t":"구의 중심은 1개예요","mis":"M6-2-u6-X19"},{"t":"구에는 평평한 면이 없어요","mis":"M6-2-u6-X19"},{"t":"구는 어느 방향에서 보아도 원이에요","mis":"M6-2-u6-X19"}],"explanation":["구의 중심은 1개, 평평한 면은 없어요.","구는 어느 방향에서 보아도 원이에요.","구의 반지름은 무수히 많고 길이가 모두 같아요 — 방향마다 다르지 않아요."],"variant_rule":{"alt":[{"stem":"구에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구의 반지름은 무수히 많고 그 길이가 모두 같아요","correct":true},{"t":"구의 반지름은 무수히 많고 그 길이가 모두 달라요","mis":"M6-2-u6-X17"},{"t":"구는 밑면이 2개 있어요","mis":"M6-2-u6-X05"},{"t":"구에는 꼭짓점이 1개 있어요","mis":"M6-2-u6-X07"}],"explanation":["구의 반지름은 구의 중심에서 겉면의 한 점까지예요.","겉면의 점마다 그을 수 있어 무수히 많아요.","중심에서 겉면까지의 거리는 어디나 같아 길이도 모두 같아요."]},{"stem":"구에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구의 중심은 1개예요","correct":true},{"t":"구의 중심은 무수히 많아요","mis":"M6-2-u6-X17"},{"t":"구에는 평평한 면이 1개 있어요","mis":"M6-2-u6-X07"},{"t":"구를 앞에서 보면 반원이에요","mis":"M6-2-u6-X18"}],"explanation":["반원의 중심이 구의 중심이 되니 구의 중심은 1개예요.","구는 굽은 면으로만 이루어져 평평한 면이 없어요.","구는 어느 방향에서 보아도 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#8','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',4,'sa','auto','원기둥 3개, 원뿔 4개, 구 2개의 평평한 면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C7","difficulty":4,"kind":"sa","stem":"원기둥 3개, 원뿔 4개, 구 2개의 평평한 면은 모두 몇 개인가요?","answer":["10"],"explanation":["평평한 면은 원기둥 하나에 2개, 원뿔 하나에 1개, 구는 0개예요.","원기둥 3개는 3 × 2 = 6개, 원뿔 4개는 4개예요.","6 + 4 = 10개예요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥 2개, 원뿔 5개, 구 3개의 평평한 면은 모두 몇 개인가요?","answer":["9"],"explanation":["평평한 면은 원기둥 하나에 2개, 원뿔 하나에 1개, 구는 0개예요.","원기둥 2개는 2 × 2 = 4개, 원뿔 5개는 5개예요.","4 + 5 = 9개예요."]},{"stem":"원기둥 5개, 원뿔 2개, 구 4개의 평평한 면은 모두 몇 개인가요?","answer":["12"],"explanation":["평평한 면은 원기둥 하나에 2개, 원뿔 하나에 1개, 구는 0개예요.","원기둥 5개는 5 × 2 = 10개, 원뿔 2개는 2개예요.","10 + 2 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#9','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',4,'sa','auto','반지름이 10 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C7","difficulty":4,"kind":"sa","stem":"반지름이 10 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["20"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 10 × 2 = 20 cm예요.","그래서 한 모서리는 20 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 12 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["24"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 12 cm예요.","지름은 12 × 2 = 24 cm예요."]},{"stem":"반지름이 15 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["30"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 15 × 2 = 30 cm예요.","그래서 한 모서리는 30 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L08_challenge#10','math',6,2,'u6','L08','g6_2_math_u6_L08_challenge','lesson_challenge','M6-2-u6-C7',4,'essay','teacher','원기둥·원뿔·구를 위·앞·옆에서 본 모양을 견주어 보고, 구만 어느 방향에서 보아도 원인 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C7","difficulty":4,"kind":"essay","stem":"원기둥·원뿔·구를 위·앞·옆에서 본 모양을 견주어 보고, 구만 어느 방향에서 보아도 원인 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 위에서 보면 셋 다 원이지만, 앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이다. 구는 한 점(구의 중심)에서 같은 거리에 있는 점들로 이루어져 어느 쪽으로 돌려 보아도 생김새가 그대로이기 때문에 늘 원으로 보인다.","scoring_points":["위에서는 셋 다 원이라고 썼는가","앞·옆 모양(직사각형·삼각형·원)을 썼는가","중심에서 같은 거리라는 까닭을 썼는가"]},"explanation":["위에서는 모두 원이에요.","앞·옆에서 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","구는 중심에서 같은 거리의 점들이라 어디서 보아도 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#1','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','원뿔을 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":1,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원뿔을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 앞에서 본 모양은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."]},{"stem":"구를 앞에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 앞에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#2','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','원뿔을 앞에서 본 삼각형의 밑변은 원뿔의 무엇과 길이가 같나요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":2,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원뿔을 앞에서 본 삼각형의 밑변은 원뿔의 무엇과 길이가 같나요?","options":[{"t":"밑면의 지름","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X20"},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"}],"explanation":["원뿔을 앞에서 보면 밑면인 원이 납작하게 보여요.","원이 지름만큼의 선분으로 보여요.","그래서 삼각형의 밑변은 밑면의 지름과 같아요."],"variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 삼각형의 높이는 원뿔의 무엇과 길이가 같나요?","options":[{"t":"원뿔의 높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면의 지름","mis":"M6-2-u6-X18"},{"t":"밑면의 반지름","mis":"M6-2-u6-X18"}],"explanation":["삼각형의 꼭짓점이 원뿔의 꼭짓점이에요.","꼭짓점에서 밑변에 수직으로 내린 길이가 삼각형의 높이예요.","그래서 원뿔의 높이와 같아요 — 모선은 삼각형의 옆 변이에요."]},{"stem":"원기둥을 앞에서 본 직사각형의 가로와 세로는 원기둥의 무엇과 같나요?","options":[{"t":"가로는 밑면의 지름, 세로는 높이","correct":true},{"t":"가로는 밑면의 둘레, 세로는 높이","mis":"M6-2-u6-X08"},{"t":"가로는 밑면의 반지름, 세로는 높이","mis":"M6-2-u6-X20"},{"t":"가로는 높이, 세로는 밑면의 둘레","mis":"M6-2-u6-X09"}],"explanation":["원기둥을 앞에서 보면 밑면인 원이 지름만큼의 선분으로 보여요.","그래서 가로는 밑면의 지름이에요.","세로는 두 밑면 사이 — 원기둥의 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#3','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','밑면의 지름이 6 cm, 높이가 5 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X08']::text[],true,'{"seq":3,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"밑면의 지름이 6 cm, 높이가 5 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"30 cm²","correct":true},{"t":"15 cm²","mis":"M6-2-u6-X20"},{"t":"94.2 cm²","mis":"M6-2-u6-X08"},{"t":"22 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 6 cm, 세로는 높이 5 cm예요.","6 × 5 = 30 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 8 cm, 높이가 4 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"32 cm²","correct":true},{"t":"16 cm²","mis":"M6-2-u6-X20"},{"t":"100.48 cm²","mis":"M6-2-u6-X08"},{"t":"24 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 8 cm, 세로는 높이 4 cm예요.","8 × 4 = 32 cm²예요."]},{"stem":"밑면의 지름이 7 cm, 높이가 3 cm인 원기둥을 앞에서 보았어요. 앞에서 본 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"21 cm²","correct":true},{"t":"10.5 cm²","mis":"M6-2-u6-X20"},{"t":"65.94 cm²","mis":"M6-2-u6-X08"},{"t":"20 cm²","mis":"M6-2-u6-X20"}],"explanation":["원기둥을 앞에서 보면 직사각형이에요.","가로는 밑면의 지름 7 cm, 세로는 높이 3 cm예요.","7 × 3 = 21 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#4','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',1,'mc','auto','밑면의 지름이 12 cm, 높이가 8 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":4,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","12 × 8 ÷ 2 = 48 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm, 높이가 6 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"30 cm²","correct":true},{"t":"60 cm²","mis":"M6-2-u6-X20"},{"t":"15 cm²","mis":"M6-2-u6-X20"},{"t":"40 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 10 cm, 높이는 원뿔의 높이 6 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","10 × 6 ÷ 2 = 30 cm²예요."]},{"stem":"밑면의 지름이 8 cm, 높이가 5 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"20 cm²","correct":true},{"t":"40 cm²","mis":"M6-2-u6-X20"},{"t":"10 cm²","mis":"M6-2-u6-X20"},{"t":"28 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 8 cm, 높이는 원뿔의 높이 5 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","8 × 5 ÷ 2 = 20 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#5','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','밑면의 지름이 18 cm, 높이가 12 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":5,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"126 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","18 × 12 ÷ 2 = 108 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 14 cm, 높이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"70 cm²","correct":true},{"t":"140 cm²","mis":"M6-2-u6-X20"},{"t":"35 cm²","mis":"M6-2-u6-X20"},{"t":"84 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 14 cm, 높이는 원뿔의 높이 10 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","14 × 10 ÷ 2 = 70 cm²예요."]},{"stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"72 cm²","correct":true},{"t":"144 cm²","mis":"M6-2-u6-X20"},{"t":"36 cm²","mis":"M6-2-u6-X20"},{"t":"88 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 16 cm, 높이는 원뿔의 높이 9 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","16 × 9 ÷ 2 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#6','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'sa','auto','원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C8","difficulty":2,"kind":"sa","stem":"원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","108 ÷ 9 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 세로가 6 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","48 ÷ 6 = 8 cm예요."]},{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 35 cm², 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","35 ÷ 5 = 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#7','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'sa','auto','원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":2,"kind":"sa","stem":"원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["6"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","48 ÷ 8 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 36 cm², 가로가 9 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["4"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","36 ÷ 9 = 4 cm예요."]},{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 42 cm², 가로가 6 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["7"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","42 ÷ 6 = 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#8','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구하려고 해요. 쓰지 않는 길이는 어느 것인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X20']::text[],true,'{"seq":8,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구하려고 해요. 쓰지 않는 길이는 어느 것인가요?","options":[{"t":"모선 10 cm","correct":true},{"t":"높이 8 cm","mis":"M6-2-u6-X15"},{"t":"밑면의 반지름 6 cm","mis":"M6-2-u6-X20"},{"t":"세 길이 모두 써요","mis":"M6-2-u6-X15"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","밑변은 밑면의 지름(반지름의 2배), 높이는 원뿔의 높이예요.","모선은 넓이를 구할 때 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 5 cm, 높이가 12 cm, 모선이 13 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구하려고 해요. 쓰지 않는 길이는 어느 것인가요?","options":[{"t":"모선 13 cm","correct":true},{"t":"높이 12 cm","mis":"M6-2-u6-X15"},{"t":"밑면의 반지름 5 cm","mis":"M6-2-u6-X20"},{"t":"세 길이 모두 써요","mis":"M6-2-u6-X15"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","밑변은 밑면의 지름(반지름의 2배), 높이는 원뿔의 높이예요.","모선은 넓이를 구할 때 쓰지 않아요."]},{"stem":"밑면의 반지름이 9 cm, 높이가 12 cm, 모선이 15 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구하려고 해요. 쓰지 않는 길이는 어느 것인가요?","options":[{"t":"모선 15 cm","correct":true},{"t":"높이 12 cm","mis":"M6-2-u6-X15"},{"t":"밑면의 반지름 9 cm","mis":"M6-2-u6-X20"},{"t":"세 길이 모두 써요","mis":"M6-2-u6-X15"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","밑변은 밑면의 지름(반지름의 2배), 높이는 원뿔의 높이예요.","모선은 넓이를 구할 때 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#9','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',2,'mc','auto','원뿔을 앞에서 본 삼각형의 두 옆 변은 원뿔의 무엇과 길이가 같나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X18']::text[],true,'{"seq":9,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"원뿔을 앞에서 본 삼각형의 두 옆 변은 원뿔의 무엇과 길이가 같나요?","options":[{"t":"모선","correct":true},{"t":"원뿔의 높이","mis":"M6-2-u6-X15"},{"t":"밑면의 지름","mis":"M6-2-u6-X18"},{"t":"밑면의 반지름","mis":"M6-2-u6-X18"}],"explanation":["앞에서 보면 꼭짓점에서 밑면의 양 끝까지 비스듬한 선이 보여요.","꼭짓점과 밑면 둘레의 한 점을 이은 선분이 모선이에요.","그래서 두 옆 변은 모선과 같아요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 가로와 세로는 원기둥의 무엇과 같나요?","options":[{"t":"가로는 밑면의 지름, 세로는 높이","correct":true},{"t":"가로는 밑면의 둘레, 세로는 높이","mis":"M6-2-u6-X08"},{"t":"가로는 밑면의 반지름, 세로는 높이","mis":"M6-2-u6-X20"},{"t":"가로는 높이, 세로는 밑면의 둘레","mis":"M6-2-u6-X09"}],"explanation":["원기둥을 앞에서 보면 밑면인 원이 지름만큼의 선분으로 보여요.","그래서 가로는 밑면의 지름이에요.","세로는 두 밑면 사이 — 원기둥의 높이예요."]},{"stem":"원뿔을 앞에서 본 삼각형의 밑변은 원뿔의 무엇과 길이가 같나요?","options":[{"t":"밑면의 지름","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X20"},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"}],"explanation":["원뿔을 앞에서 보면 밑면인 원이 납작하게 보여요.","원이 지름만큼의 선분으로 보여요.","그래서 삼각형의 밑변은 밑면의 지름과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_basic#10','math',6,2,'u6','L09','g6_2_math_u6_L09_basic','lesson_basic','M6-2-u6-C8',3,'ox','auto','원뿔을 앞에서 본 삼각형의 높이는 모선과 같아요.',ARRAY['M6-2-u6-X15']::text[],true,'{"seq":10,"concept":"M6-2-u6-C8","difficulty":3,"kind":"ox","stem":"원뿔을 앞에서 본 삼각형의 높이는 모선과 같아요.","answer":"X","reason_options":[{"t":"삼각형의 높이는 원뿔의 높이이고 모선은 옆 변이기 때문에","correct":true},{"t":"모선이 꼭짓점에서 내려오기 때문에","mis":"M6-2-u6-X15"}],"mis":"M6-2-u6-X15","explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 가로는 밑면의 지름이에요.","answer":"O","reason_options":[{"t":"밑면인 원이 지름만큼의 선분으로 보이기 때문에","correct":true},{"t":"가로는 밑면의 둘레이기 때문에","mis":"M6-2-u6-X08"}],"explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."]},{"stem":"원뿔을 앞에서 본 삼각형의 밑변은 밑면의 반지름이에요.","answer":"X","reason_options":[{"t":"밑면인 원이 지름만큼 보이기 때문에","correct":true},{"t":"원뿔의 밑면은 반지름으로만 나타내기 때문에","mis":"M6-2-u6-X20"}],"explanation":["원뿔을 앞에서 보면 삼각형 — 밑변은 밑면의 지름, 높이는 원뿔의 높이예요.","원기둥을 앞에서 보면 직사각형 — 가로는 지름, 세로는 높이예요.","모선은 삼각형의 옆 변이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#1','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',2,'sa','auto','밑면의 지름이 6 cm, 높이가 8 cm인 원기둥을 앞에서 본 직사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":1,"concept":"M6-2-u6-C8","difficulty":2,"kind":"sa","stem":"밑면의 지름이 6 cm, 높이가 8 cm인 원기둥을 앞에서 본 직사각형의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["가로는 밑면의 지름 6 cm, 세로는 높이 8 cm예요.","직사각형의 둘레는 ((가로) + (세로)) × 2예요.","(6 + 8) × 2 = 28 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm, 높이가 5 cm인 원기둥을 앞에서 본 직사각형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["가로는 밑면의 지름 10 cm, 세로는 높이 5 cm예요.","직사각형의 둘레는 ((가로) + (세로)) × 2예요.","(10 + 5) × 2 = 30 cm예요."]},{"stem":"밑면의 지름이 4 cm, 높이가 12 cm인 원기둥을 앞에서 본 직사각형의 둘레는 몇 cm인가요?","answer":["32"],"explanation":["가로는 밑면의 지름 4 cm, 세로는 높이 12 cm예요.","직사각형의 둘레는 ((가로) + (세로)) × 2예요.","(4 + 12) × 2 = 32 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#2','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',2,'mc','auto','밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":2,"concept":"M6-2-u6-C8","difficulty":2,"kind":"mc","stem":"밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선은 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 6 cm, 높이가 4 cm, 모선이 5 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"12 cm²","correct":true},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"6 cm²","mis":"M6-2-u6-X20"},{"t":"15 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 6 cm, 높이는 원뿔의 높이 4 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선은 쓰지 않아요.","6 × 4 ÷ 2 = 12 cm²예요."]},{"stem":"밑면의 지름이 10 cm, 높이가 12 cm, 모선이 13 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M6-2-u6-X20"},{"t":"30 cm²","mis":"M6-2-u6-X20"},{"t":"65 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 10 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선은 쓰지 않아요.","10 × 12 ÷ 2 = 60 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#3','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'error','auto','밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X19']::text[],true,'{"seq":3,"concept":"M6-2-u6-C8","difficulty":3,"kind":"error","stem":"밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"여울 — 「12 × 10 ÷ 2 = 60이야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"순달 — 「12 × 8 ÷ 2 = 48이야.」","mis":"M6-2-u6-X19"},{"t":"달곰 — 「밑변은 지름, 높이는 원뿔의 높이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「넓이는 48 cm²야.」","mis":"M6-2-u6-X19"}],"explanation":["삼각형의 높이는 원뿔의 높이 8 cm예요.","모선 10 cm는 삼각형의 옆 변이라 높이가 아니에요.","바른 넓이는 48 cm² — 여울는 모선을 높이로 썼어요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 6 cm, 높이가 4 cm, 모선이 5 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"민지 — 「6 × 5 ÷ 2 = 15야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"지석 — 「6 × 4 ÷ 2 = 12야.」","mis":"M6-2-u6-X19"},{"t":"서우 — 「밑변은 지름, 높이는 원뿔의 높이야.」","mis":"M6-2-u6-X19"},{"t":"여울 — 「넓이는 12 cm²야.」","mis":"M6-2-u6-X19"}],"explanation":["삼각형의 높이는 원뿔의 높이 4 cm예요.","모선 5 cm는 삼각형의 옆 변이라 높이가 아니에요.","바른 넓이는 12 cm² — 민지는 모선을 높이로 썼어요."]},{"stem":"밑면의 지름이 18 cm, 높이가 12 cm, 모선이 15 cm인 원뿔을 앞에서 본 삼각형의 넓이를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"가온 — 「18 × 15 ÷ 2 = 135야.」","correct":true,"mis_target":"M6-2-u6-X15"},{"t":"나린 — 「18 × 12 ÷ 2 = 108이야.」","mis":"M6-2-u6-X19"},{"t":"지호 — 「밑변은 지름, 높이는 원뿔의 높이야.」","mis":"M6-2-u6-X19"},{"t":"유진 — 「넓이는 108 cm²야.」","mis":"M6-2-u6-X19"}],"explanation":["삼각형의 높이는 원뿔의 높이 12 cm예요.","모선 15 cm는 삼각형의 옆 변이라 높이가 아니에요.","바른 넓이는 108 cm² — 가온는 모선을 높이로 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#4','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'match','auto','앞에서 본 모양에 대해 알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u6-C8","difficulty":3,"kind":"match","stem":"앞에서 본 모양에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"원뿔의 앞모양","r":"삼각형"},{"l":"원기둥의 앞모양","r":"직사각형"},{"l":"구의 앞모양","r":"원"}],"mis":"M6-2-u6-X18","explanation":["원뿔은 삼각형, 원기둥은 직사각형, 구는 원으로 보여요.","삼각형의 밑변은 지름, 높이는 원뿔의 높이, 옆 변은 모선이에요.","직사각형의 가로는 지름, 세로는 높이예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 앞에서 본 모양에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"삼각형의 밑변","r":"밑면의 지름"},{"l":"삼각형의 높이","r":"원뿔의 높이"},{"l":"삼각형의 옆 변","r":"모선"}],"explanation":["원뿔은 삼각형, 원기둥은 직사각형, 구는 원으로 보여요.","삼각형의 밑변은 지름, 높이는 원뿔의 높이, 옆 변은 모선이에요.","직사각형의 가로는 지름, 세로는 높이예요."]},{"stem":"이번에는 다른 보기예요. 앞에서 본 모양에 대해 알맞은 것끼리 이으세요.","pairs":[{"l":"직사각형의 가로","r":"밑면의 지름"},{"l":"직사각형의 세로","r":"원기둥의 높이"},{"l":"위에서 본 모양","r":"원"}],"explanation":["원뿔은 삼각형, 원기둥은 직사각형, 구는 원으로 보여요.","삼각형의 밑변은 지름, 높이는 원뿔의 높이, 옆 변은 모선이에요.","직사각형의 가로는 지름, 세로는 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#5','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'sa','auto','원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 밑면의 지름이 10 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 밑면의 지름이 10 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","10 × (높이) ÷ 2 = 30 — (높이) = 30 × 2 ÷ 10이에요.","30 × 2 ÷ 10 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 42 cm²이고, 원뿔의 밑면의 지름이 12 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["7"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","12 × (높이) ÷ 2 = 42 — (높이) = 42 × 2 ÷ 12예요.","42 × 2 ÷ 12 = 7 cm예요."]},{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 36 cm²이고, 원뿔의 밑면의 지름이 8 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["9"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","8 × (높이) ÷ 2 = 36 — (높이) = 36 × 2 ÷ 8이에요.","36 × 2 ÷ 8 = 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#6','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'sa','auto','원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 높이가 6 cm예요. 이 원뿔의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 높이가 6 cm예요. 이 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["10"],"explanation":["삼각형의 밑변이 밑면의 지름이에요.","(밑변) = (넓이) × 2 ÷ (높이)예요.","30 × 2 ÷ 6 = 10 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 28 cm²이고, 원뿔의 높이가 4 cm예요. 이 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["삼각형의 밑변이 밑면의 지름이에요.","(밑변) = (넓이) × 2 ÷ (높이)예요.","28 × 2 ÷ 4 = 14 cm예요."]},{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 33 cm²이고, 원뿔의 높이가 11 cm예요. 이 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 밑변이 밑면의 지름이에요.","(밑변) = (넓이) × 2 ÷ (높이)예요.","33 × 2 ÷ 11 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#7','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',3,'sa','auto','밑면의 반지름이 3 cm, 높이가 4 cm, 모선이 5 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"밑면의 반지름이 3 cm, 높이가 4 cm, 모선이 5 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?","answer":["16"],"explanation":["앞에서 본 삼각형의 밑변은 지름 6 cm예요.","두 옆 변은 모선 5 cm씩이에요 — 높이는 둘레에 들어가지 않아요.","6 + 5 + 5 = 16 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?","answer":["32"],"explanation":["앞에서 본 삼각형의 밑변은 지름 12 cm예요.","두 옆 변은 모선 10 cm씩이에요 — 높이는 둘레에 들어가지 않아요.","12 + 10 + 10 = 32 cm예요."]},{"stem":"밑면의 반지름이 8 cm, 높이가 6 cm, 모선이 10 cm인 원뿔을 앞에서 본 삼각형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["앞에서 본 삼각형의 밑변은 지름 16 cm예요.","두 옆 변은 모선 10 cm씩이에요 — 높이는 둘레에 들어가지 않아요.","16 + 10 + 10 = 36 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#8','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',4,'sa','auto','밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 5 cm일 때 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 5 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 10 × 6 ÷ 2 = 30 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 30 cm² — 세로는 높이 5 cm예요.","가로(지름) = 30 ÷ 5 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 6 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름) = 48 ÷ 6 = 8 cm예요."]},{"stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 9 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름) = 108 ÷ 9 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#9','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',4,'sa','auto','밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 6 cm일 때 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 6 cm일 때 높이는 몇 cm인가요?","answer":["5"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 10 × 6 ÷ 2 = 30 cm²예요.","원기둥 모자의 앞모양도 30 cm² — 가로는 지름 6 cm예요.","세로(높이) = 30 ÷ 6 = 5 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 8 cm일 때 높이는 몇 cm인가요?","answer":["6"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥 모자의 앞모양도 48 cm² — 가로는 지름 8 cm예요.","세로(높이) = 48 ÷ 8 = 6 cm예요."]},{"stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 8 cm일 때 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 16 × 9 ÷ 2 = 72 cm²예요.","원기둥 모자의 앞모양도 72 cm² — 가로는 지름 8 cm예요.","세로(높이) = 72 ÷ 8 = 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_L09_challenge#10','math',6,2,'u6','L09','g6_2_math_u6_L09_challenge','lesson_challenge','M6-2-u6-C8',4,'essay','teacher','세계 전통 의상 체험관에서 밑면의 지름이 18 cm, 높이가 12 cm, 모선이 15 cm인 원뿔 모자와 높이가 9 cm인 원기둥 모자를 앞에서 본 모양의 넓이가 같았어요. 원기둥 모자의 밑면의 지름을 구하는 과정을 쓰고, 모선을 쓰지 않는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"세계 전통 의상 체험관에서 밑면의 지름이 18 cm, 높이가 12 cm, 모선이 15 cm인 원뿔 모자와 높이가 9 cm인 원기둥 모자를 앞에서 본 모양의 넓이가 같았어요. 원기둥 모자의 밑면의 지름을 구하는 과정을 쓰고, 모선을 쓰지 않는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 원뿔 모자를 앞에서 보면 밑변 18 cm, 높이 12 cm인 삼각형이라 넓이는 18 × 12 ÷ 2 = 108 cm²이다. 원기둥 모자의 앞모양은 세로가 9 cm인 직사각형이고 넓이가 108 cm²이므로 가로(지름)는 108 ÷ 9 = 12 cm이다. 모선은 삼각형의 옆 변이라 넓이를 구하는 데 필요한 높이가 아니다.","scoring_points":["삼각형의 넓이 108 cm²를 구했는가","108 ÷ 9 = 12 cm를 구했는가","모선은 옆 변이라 높이가 아니라고 설명했는가"]},"explanation":["18 × 12 ÷ 2 = 108 cm²예요.","108 ÷ 9 = 12 cm예요.","모선은 옆 변 — 넓이에는 원뿔의 높이를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#1','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',1,'mc','auto','원기둥은 어떤 입체도형인가요?',ARRAY['M6-2-u6-X01','M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"원기둥은 어떤 입체도형인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","correct":true},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X01"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X03"},{"t":"한 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["원기둥의 뜻을 떠올려요.","원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."],"variant_rule":{"alt":[{"stem":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원기둥","correct":true},{"t":"각기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X14"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]},{"stem":"원뿔은 어떤 입체도형인가요?","options":[{"t":"한 원을 면으로 하는 입체도형","correct":true},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X03"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X01"}],"explanation":["원뿔의 뜻을 떠올려요.","원뿔은 한 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#2','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',1,'mc','auto','직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."],"variant_rule":{"alt":[{"stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."]},{"stem":"지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 구가 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#3','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C2',1,'mc','auto','원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06','M6-2-u6-X15']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","서로 평행하고 합동인 두 원을 밑면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#4','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',1,'mc','auto','원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?',ARRAY['M6-2-u6-X13']::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"원기둥의 전개도","correct":true},{"t":"원기둥의 겨냥도","mis":"M6-2-u6-X13"},{"t":"원기둥의 밑면","mis":"M6-2-u6-X13"},{"t":"원기둥의 옆면","mis":"M6-2-u6-X13"}],"explanation":["입체도형을 잘라 평면 위에 펼친 그림이 전개도예요.","겨냥도는 입체도형의 모양을 잘 알 수 있게 그린 그림이에요.","그래서 원기둥의 전개도예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 밑면과 옆면은 각각 어떤 도형인가요?","options":[{"t":"밑면은 원, 옆면은 직사각형","correct":true},{"t":"밑면은 직사각형, 옆면은 원","mis":"M6-2-u6-X09"},{"t":"밑면은 원, 옆면은 삼각형","mis":"M6-2-u6-X13"},{"t":"밑면과 옆면 모두 원","mis":"M6-2-u6-X13"}],"explanation":["밑면은 원기둥의 두 원이에요.","굽은 옆면을 잘라 펼치면 직사각형이 돼요.","그래서 밑면은 원, 옆면은 직사각형이에요."]},{"stem":"원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?","options":[{"t":"합동인 원 2개와 직사각형 1개","correct":true},{"t":"원 1개와 직사각형 1개","mis":"M6-2-u6-X13"},{"t":"합동인 원 2개와 직사각형 2개","mis":"M6-2-u6-X13"},{"t":"크기가 다른 원 2개와 직사각형 1개","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 밑면은 서로 합동인 원 2개예요.","옆면은 굽은 면 하나 — 펼치면 직사각형 1개예요.","그래서 합동인 원 2개와 직사각형 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#5','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C6',1,'mc','auto','원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 높이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#6','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C7',1,'mc','auto','구는 어떻게 만든 입체도형인가요?',ARRAY['M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"구는 어떻게 만든 입체도형인가요?","options":[{"t":"지름을 따라 반으로 나눈 원을 지름을 기준으로 한 바퀴 돌려서 만든 입체도형","correct":true},{"t":"직사각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"직각삼각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."],"variant_rule":{"alt":[{"stem":"돌리기 전 반원의 중심은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 중심","correct":true},{"t":"구의 반지름","mis":"M6-2-u6-X17"},{"t":"구의 밑면","mis":"M6-2-u6-X07"},{"t":"구의 꼭짓점","mis":"M6-2-u6-X07"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]},{"stem":"돌리기 전 반원의 반지름은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 반지름","correct":true},{"t":"구의 중심","mis":"M6-2-u6-X17"},{"t":"구의 지름","mis":"M6-2-u6-X04"},{"t":"구의 둘레","mis":"M6-2-u6-X17"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#7','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',1,'mc','auto','원뿔을 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원뿔을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 앞에서 본 모양은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."]},{"stem":"구를 앞에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 앞에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#8','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C2',1,'sa','auto','밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 6 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]},{"stem":"밑면의 반지름이 9 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","9 × 2 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#9','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',2,'sa','auto','가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 3 × 2 = 6 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 7 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 세로 7 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."]},{"stem":"가로 6 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["막대에 붙인 세로 9 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#10','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',2,'mc','auto','「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 면이 원이 아니라 다각형이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X01"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X01"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 서로 평행하고 합동인 육각형인 상자」를 이 조건에 하나씩 대어 봐요.","두 면이 원이 아니라 다각형이어서 원기둥이 아니에요."]},{"stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#11','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',2,'mc','auto','밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":11,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","8 × 3.14 = 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 5 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u6-X08"},{"t":"7.85 cm","mis":"M6-2-u6-X08"},{"t":"31.4 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","5 × 3.14 = 15.7 cm예요."]},{"stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#12','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","25.12 ÷ 3.14 = 8 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","18.84 ÷ 3.14 = 6 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 21.98 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","21.98 ÷ 3.14 = 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#13','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C4',2,'mc','auto','「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X11']::text[],true,'{"seq":13,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서 전개도가 될 수 없어요."]},{"stem":"「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 서로 합동이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#14','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C5',2,'sa','auto','세 변이 3 cm, 4 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 4 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"세 변이 3 cm, 4 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 4 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 변 4 cm는 원뿔의 높이, 뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","가장 긴 변 5 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 3 × 2 = 6 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 6 cm, 8 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 8 cm는 원뿔의 높이, 뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","가장 긴 변 10 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 6 × 2 = 12 cm예요."]},{"stem":"세 변이 5 cm, 12 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","가장 긴 변 13 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 높이는 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#15','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["8"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 10 cm는 모선이에요.","그래서 높이는 8 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 13 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["13"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 12 cm는 높이예요.","그래서 모선은 13 cm예요."]},{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 5 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 5 cm는 모선이에요.","그래서 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#16','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C7',2,'sa','auto','원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 2개, 원뿔 1개, 구 0개 — 2 + 1 + 0 = 3개예요."],"mis":"M6-2-u6-X07","variant_rule":{"alt":[{"stem":"원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?","answer":["5"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 하나에 2개씩 4개, 원뿔 1개 — 4 + 1 = 5개예요."]},{"stem":"원뿔 3개와 구 2개의 평평한 면은 모두 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원뿔 하나에 1개씩 3개, 구는 0개 — 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#17','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',3,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["11"],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm예요.","옆면의 세로가 높이 — 5 cm예요.","6 + 5 = 11 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 9 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["13"],"explanation":["지름은 12.56 ÷ 3.14 = 4 cm예요.","옆면의 세로가 높이 — 9 cm예요.","4 + 9 = 13 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 10 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["18"],"explanation":["지름은 25.12 ÷ 3.14 = 8 cm예요.","옆면의 세로가 높이 — 10 cm예요.","8 + 10 = 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#18','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C6',3,'mc','auto','원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?',ARRAY['M6-2-u6-X16','M6-2-u6-X15']::text[],true,'{"seq":18,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?","options":[{"t":"모선은 둘레까지 비스듬히 가고 높이는 한가운데까지 곧게 가서","correct":true},{"t":"모선이 여러 개여서","mis":"M6-2-u6-X16"},{"t":"밑면이 원이어서","mis":"M6-2-u6-X15"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"원뿔의 모선은 몇 개인가요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M6-2-u6-X16"},{"t":"2개","mis":"M6-2-u6-X16"},{"t":"4개","mis":"M6-2-u6-X16"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]},{"stem":"한 원뿔에서 모선의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"모두 달라요","mis":"M6-2-u6-X16"},{"t":"둘레 쪽으로 갈수록 길어져요","mis":"M6-2-u6-X16"},{"t":"높이와 같아요","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#19','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C7',3,'sa','auto','반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 4 cm예요.","지름은 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 5 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["10"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 5 × 2 = 10 cm예요.","그래서 한 모서리는 10 cm예요."]},{"stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 6 cm예요.","지름은 6 × 2 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#20','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 지름이 18 cm, 높이가 12 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":20,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"126 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","18 × 12 ÷ 2 = 108 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 14 cm, 높이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"70 cm²","correct":true},{"t":"140 cm²","mis":"M6-2-u6-X20"},{"t":"35 cm²","mis":"M6-2-u6-X20"},{"t":"84 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 14 cm, 높이는 원뿔의 높이 10 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","14 × 10 ÷ 2 = 70 cm²예요."]},{"stem":"밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선은 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#21','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',3,'sa','auto','원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","108 ÷ 9 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["6"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","48 ÷ 8 = 6 cm예요."]},{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 35 cm², 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","35 ÷ 5 = 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#22','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C4',3,'mc','auto','다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X02','M6-2-u6-X11','M6-2-u6-X12']::text[],true,'{"seq":22,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 옆면의 위와 아래에 하나씩 붙은 그림","correct":true},{"t":"옆면이 직사각형이고, 크기가 다른 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X02"},{"t":"옆면이 평행사변형이고, 크기가 같은 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X11"},{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 모두 위쪽에 붙은 그림","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 원이 직사각형 옆면을 사이에 두고 마주 붙은 그림","correct":true},{"t":"크기가 같은 두 원이 직사각형 옆면의 한쪽에 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"원 하나가 직사각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"},{"t":"크기가 같은 두 원이 삼각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"직사각형의 위쪽 가운데와 아래쪽 가운데에 합동인 원이 하나씩 붙은 그림","correct":true},{"t":"직사각형의 위쪽에 합동인 원 두 개가 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"직사각형의 위쪽에 큰 원, 아래쪽에 작은 원이 붙은 그림","mis":"M6-2-u6-X02"},{"t":"기울어진 사각형의 위아래에 합동인 원이 하나씩 붙은 그림","mis":"M6-2-u6-X11"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#23','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C8',4,'sa','auto','밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 5 cm일 때 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 5 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 10 × 6 ÷ 2 = 30 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 30 cm² — 세로는 높이 5 cm예요.","가로(지름) = 30 ÷ 5 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 6 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름) = 48 ÷ 6 = 8 cm예요."]},{"stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 9 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름) = 108 ÷ 9 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#24','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C1',4,'essay','teacher','직사각형, 직각삼각형, 반원을 각각 한 바퀴 돌리면 어떤 입체도형이 되는지 쓰고, 직사각형을 돌릴 때 막대에 붙인 변과 뻗어 나간 변이 원기둥의 무엇이 되는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C1","difficulty":4,"kind":"essay","stem":"직사각형, 직각삼각형, 반원을 각각 한 바퀴 돌리면 어떤 입체도형이 되는지 쓰고, 직사각형을 돌릴 때 막대에 붙인 변과 뻗어 나간 변이 원기둥의 무엇이 되는지 설명해 보세요.","answer_guide":{"answer":"예: 직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 된다. 직사각형을 돌릴 때 막대에 붙인 변은 원기둥의 높이가 되고, 뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 된다.","scoring_points":["세 도형이 각각 원기둥·원뿔·구가 됨을 썼는가","막대에 붙인 변이 높이가 됨을 썼는가","뻗어 나간 변이 밑면의 반지름이 됨을 썼는가"]},"explanation":["직사각형→원기둥, 직각삼각형→원뿔, 반원→구예요.","막대에 붙인 변은 높이예요.","뻗어 나간 변은 밑면의 반지름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_a#25','math',6,2,'u6','','g6_2_math_u6_review_a','unit_review','M6-2-u6-C3',4,'essay','teacher','어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 반지름과 높이를 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C3","difficulty":4,"kind":"essay","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 반지름과 높이를 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 옆면의 가로는 밑면의 둘레이므로 지름은 18.84 ÷ 3.14 = 6 cm이고 반지름은 6 ÷ 2 = 3 cm이다. 옆면의 세로는 원기둥의 높이이므로 높이는 5 cm이다.","scoring_points":["가로가 밑면의 둘레임을 밝혔는가","지름 6 cm, 반지름 3 cm를 구했는가","세로가 높이 5 cm임을 썼는가"]},"explanation":["가로 = 밑면의 둘레예요.","18.84 ÷ 3.14 = 6 → 반지름 3 cm예요.","세로 = 높이 5 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#1','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C1',1,'mc','auto','서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?',ARRAY['M6-2-u6-X01','M6-2-u6-X03','M6-2-u6-X14']::text[],true,'{"seq":1,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원기둥","correct":true},{"t":"각기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X14"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."],"variant_rule":{"alt":[{"stem":"원뿔은 어떤 입체도형인가요?","options":[{"t":"한 원을 면으로 하는 입체도형","correct":true},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X03"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X01"}],"explanation":["원뿔의 뜻을 떠올려요.","원뿔은 한 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."]},{"stem":"한 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X14"},{"t":"각기둥","mis":"M6-2-u6-X03"},{"t":"각뿔","mis":"M6-2-u6-X01"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","한 원을 면으로 하는 입체도형을 원뿔이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#2','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C5',1,'mc','auto','직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."],"variant_rule":{"alt":[{"stem":"지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 구가 만들어져요."]},{"stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#3','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C2',1,'mc','auto','원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X06','M6-2-u6-X15']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥의 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X06"},{"t":"옆면의 둘레","mis":"M6-2-u6-X06"},{"t":"밑면의 반지름","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#4','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',1,'mc','auto','원기둥의 전개도에서 밑면과 옆면은 각각 어떤 도형인가요?',ARRAY['M6-2-u6-X09','M6-2-u6-X13']::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 전개도에서 밑면과 옆면은 각각 어떤 도형인가요?","options":[{"t":"밑면은 원, 옆면은 직사각형","correct":true},{"t":"밑면은 직사각형, 옆면은 원","mis":"M6-2-u6-X09"},{"t":"밑면은 원, 옆면은 삼각형","mis":"M6-2-u6-X13"},{"t":"밑면과 옆면 모두 원","mis":"M6-2-u6-X13"}],"explanation":["밑면은 원기둥의 두 원이에요.","굽은 옆면을 잘라 펼치면 직사각형이 돼요.","그래서 밑면은 원, 옆면은 직사각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?","options":[{"t":"합동인 원 2개와 직사각형 1개","correct":true},{"t":"원 1개와 직사각형 1개","mis":"M6-2-u6-X13"},{"t":"합동인 원 2개와 직사각형 2개","mis":"M6-2-u6-X13"},{"t":"크기가 다른 원 2개와 직사각형 1개","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 밑면은 서로 합동인 원 2개예요.","옆면은 굽은 면 하나 — 펼치면 직사각형 1개예요.","그래서 합동인 원 2개와 직사각형 1개예요."]},{"stem":"원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"밑면의 둘레","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"원기둥의 높이","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X08"}],"explanation":["옆면을 다시 감아 붙이면 위쪽 테두리가 밑면의 둘레에 딱 맞아야 해요.","그래서 옆면의 가로는 밑면의 둘레와 같아요.","지름이 아니라 둘레예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#5','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C6',1,'mc','auto','원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 높이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 면이 되는 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","면이 되는 원을 밑면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#6','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',1,'mc','auto','돌리기 전 반원의 중심은 만들어진 구의 무엇이 되나요?',ARRAY['M6-2-u6-X17','M6-2-u6-X07']::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"돌리기 전 반원의 중심은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 중심","correct":true},{"t":"구의 반지름","mis":"M6-2-u6-X17"},{"t":"구의 밑면","mis":"M6-2-u6-X07"},{"t":"구의 꼭짓점","mis":"M6-2-u6-X07"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."],"variant_rule":{"alt":[{"stem":"돌리기 전 반원의 반지름은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 반지름","correct":true},{"t":"구의 중심","mis":"M6-2-u6-X17"},{"t":"구의 지름","mis":"M6-2-u6-X04"},{"t":"구의 둘레","mis":"M6-2-u6-X17"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]},{"stem":"원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X18"},{"t":"원뿔","mis":"M6-2-u6-X18"},{"t":"세 가지 모두","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#7','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',1,'mc','auto','원기둥을 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."],"variant_rule":{"alt":[{"stem":"구를 앞에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 앞에서 본 모양은 원이에요."]},{"stem":"원기둥을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 위에서 본 모양은 원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#8','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C2',1,'sa','auto','밑면의 반지름이 6 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"밑면의 반지름이 6 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 9 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","9 × 2 = 18 cm예요."]},{"stem":"밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","7 × 2 = 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#9','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C1',2,'sa','auto','가로 4 cm, 세로 7 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 7 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 세로 7 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["막대에 붙인 세로 9 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."]},{"stem":"가로 5 cm, 세로 8 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["막대에 붙인 세로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#10','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C1',2,'mc','auto','「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X01']::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 면이 원이 아니라 다각형이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X01"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X01"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 서로 평행하고 합동인 육각형인 상자」를 이 조건에 하나씩 대어 봐요.","두 면이 원이 아니라 다각형이어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."]},{"stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#11','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',2,'mc','auto','밑면의 지름이 5 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":11,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 지름이 5 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u6-X08"},{"t":"7.85 cm","mis":"M6-2-u6-X08"},{"t":"31.4 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","5 × 3.14 = 15.7 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 cm예요."]},{"stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 3 cm에 2를 곱해 지름 6 cm를 먼저 만들어요.","6 × 3.14 = 18.84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#12','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","18.84 ÷ 3.14 = 6 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 21.98 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","21.98 ÷ 3.14 = 7 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","12.56 ÷ 3.14 = 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#13','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C4',2,'mc','auto','「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X12']::text[],true,'{"seq":13,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 서로 합동이 아니어서 전개도가 될 수 없어요."]},{"stem":"「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"밑면이 하나뿐이어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 밑면이 하나뿐이어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#14','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C5',2,'sa','auto','세 변이 6 cm, 8 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"세 변이 6 cm, 8 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 8 cm는 원뿔의 높이, 뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","가장 긴 변 10 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 6 × 2 = 12 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 5 cm, 12 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","가장 긴 변 13 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 높이는 12 cm예요."]},{"stem":"세 변이 9 cm, 12 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 반지름은 몇 cm인가요?","answer":["9"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","가장 긴 변 15 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 밑면의 반지름은 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#15','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 13 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 13 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["13"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 12 cm는 높이예요.","그래서 모선은 13 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 5 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 5 cm는 모선이에요.","그래서 높이는 4 cm예요."]},{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 17 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 15 cm는 높이예요.","그래서 모선은 17 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#16','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',2,'sa','auto','원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?","answer":["5"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 하나에 2개씩 4개, 원뿔 1개 — 4 + 1 = 5개예요."],"mis":"M6-2-u6-X07","variant_rule":{"alt":[{"stem":"원뿔 3개와 구 2개의 평평한 면은 모두 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원뿔 하나에 1개씩 3개, 구는 0개 — 3개예요."]},{"stem":"원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?","answer":["3"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개와 원기둥 2개 — 1 + 2 = 3개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#17','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C3',3,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 9 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 9 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["13"],"explanation":["지름은 12.56 ÷ 3.14 = 4 cm예요.","옆면의 세로가 높이 — 9 cm예요.","4 + 9 = 13 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 10 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["18"],"explanation":["지름은 25.12 ÷ 3.14 = 8 cm예요.","옆면의 세로가 높이 — 10 cm예요.","8 + 10 = 18 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 12 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["22"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","옆면의 세로가 높이 — 12 cm예요.","10 + 12 = 22 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#18','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C6',3,'mc','auto','원뿔의 모선은 몇 개인가요?',ARRAY['M6-2-u6-X16']::text[],true,'{"seq":18,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"원뿔의 모선은 몇 개인가요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M6-2-u6-X16"},{"t":"2개","mis":"M6-2-u6-X16"},{"t":"4개","mis":"M6-2-u6-X16"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"한 원뿔에서 모선의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"모두 달라요","mis":"M6-2-u6-X16"},{"t":"둘레 쪽으로 갈수록 길어져요","mis":"M6-2-u6-X16"},{"t":"높이와 같아요","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]},{"stem":"한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"8 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 8 cm가 높이, 긴 10 cm가 모선이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#19','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C7',3,'sa','auto','반지름이 5 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"반지름이 5 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["10"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 5 × 2 = 10 cm예요.","그래서 한 모서리는 10 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 6 cm예요.","지름은 6 × 2 = 12 cm예요."]},{"stem":"반지름이 7 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["14"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 7 × 2 = 14 cm예요.","그래서 한 모서리는 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#20','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 지름이 14 cm, 높이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":20,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 지름이 14 cm, 높이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"70 cm²","correct":true},{"t":"140 cm²","mis":"M6-2-u6-X20"},{"t":"35 cm²","mis":"M6-2-u6-X20"},{"t":"84 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 14 cm, 높이는 원뿔의 높이 10 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","14 × 10 ÷ 2 = 70 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선은 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."]},{"stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"72 cm²","correct":true},{"t":"144 cm²","mis":"M6-2-u6-X20"},{"t":"36 cm²","mis":"M6-2-u6-X20"},{"t":"88 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 16 cm, 높이는 원뿔의 높이 9 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","16 × 9 ÷ 2 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#21','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',3,'sa','auto','원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["6"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","48 ÷ 8 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 35 cm², 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","35 ÷ 5 = 7 cm예요."]},{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 밑면의 지름이 10 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","10 × (높이) ÷ 2 = 30 — (높이) = 30 × 2 ÷ 10이에요.","30 × 2 ÷ 10 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#22','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C4',3,'mc','auto','다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X13']::text[],true,'{"seq":22,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 원이 직사각형 옆면을 사이에 두고 마주 붙은 그림","correct":true},{"t":"크기가 같은 두 원이 직사각형 옆면의 한쪽에 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"원 하나가 직사각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"},{"t":"크기가 같은 두 원이 삼각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"직사각형의 위쪽 가운데와 아래쪽 가운데에 합동인 원이 하나씩 붙은 그림","correct":true},{"t":"직사각형의 위쪽에 합동인 원 두 개가 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"직사각형의 위쪽에 큰 원, 아래쪽에 작은 원이 붙은 그림","mis":"M6-2-u6-X02"},{"t":"기울어진 사각형의 위아래에 합동인 원이 하나씩 붙은 그림","mis":"M6-2-u6-X11"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]},{"stem":"원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?","options":[{"t":"옆면을 사이에 두고 마주 보는 위치","correct":true},{"t":"옆면의 같은 쪽에 나란히","mis":"M6-2-u6-X12"},{"t":"옆면의 한가운데에 겹쳐서","mis":"M6-2-u6-X12"},{"t":"아무 곳에나","mis":"M6-2-u6-X12"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#23','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C8',4,'sa','auto','밑면의 지름이 12 cm, 높이가 8 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 6 cm일 때 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 6 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름) = 48 ÷ 6 = 8 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 9 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름) = 108 ÷ 9 = 12 cm예요."]},{"stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 8 cm일 때 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 16 × 9 ÷ 2 = 72 cm²예요.","원기둥 모자의 앞모양도 72 cm² — 가로는 지름 8 cm예요.","세로(높이) = 72 ÷ 8 = 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#24','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C2',4,'essay','teacher','원기둥과 각기둥의 같은 점과 다른 점을 각각 하나 이상 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C2","difficulty":4,"kind":"essay","stem":"원기둥과 각기둥의 같은 점과 다른 점을 각각 하나 이상 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 서로 평행하고 합동인 두 밑면이 있고 높이가 있다. 다른 점 — 원기둥의 밑면은 원이고 각기둥은 다각형이다. 원기둥의 옆면은 굽은 면 하나이고 모서리·꼭짓점이 없지만, 각기둥의 옆면은 직사각형이고 모서리·꼭짓점이 있다.","scoring_points":["같은 점(평행하고 합동인 두 밑면)을 썼는가","밑면 모양(원·다각형)의 차이를 썼는가","옆면이나 모서리·꼭짓점의 차이를 썼는가"]},"explanation":["둘 다 평행하고 합동인 두 밑면이 있어요.","밑면이 원기둥은 원, 각기둥은 다각형이에요.","원기둥에는 모서리·꼭짓점이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_b#25','math',6,2,'u6','','g6_2_math_u6_review_b','unit_review','M6-2-u6-C4',4,'essay','teacher','원기둥의 전개도가 되기 위한 조건 세 가지를 쓰고, 그중 하나라도 어긋나면 어떻게 되는지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C4","difficulty":4,"kind":"essay","stem":"원기둥의 전개도가 되기 위한 조건 세 가지를 쓰고, 그중 하나라도 어긋나면 어떻게 되는지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: ① 옆면이 직사각형이어야 한다. ② 두 밑면이 서로 합동인 원이어야 한다. ③ 두 밑면이 옆면을 사이에 두고 마주 보는 위치에 있어야 한다. 예를 들어 두 원의 크기가 다르면 접었을 때 한쪽이 남거나 모자라 원기둥이 되지 않는다.","scoring_points":["옆면이 직사각형이라는 조건을 썼는가","합동인 두 원·마주 보는 위치 조건을 썼는가","어긋날 때의 예를 들었는가"]},"explanation":["옆면은 직사각형이에요.","두 밑면은 합동인 원이고 마주 보아야 해요.","하나라도 어긋나면 접었을 때 원기둥이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#1','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C5',1,'mc','auto','원뿔은 어떤 입체도형인가요?',ARRAY['M6-2-u6-X14','M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"원뿔은 어떤 입체도형인가요?","options":[{"t":"한 원을 면으로 하는 입체도형","correct":true},{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X03"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X01"}],"explanation":["원뿔의 뜻을 떠올려요.","원뿔은 한 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."],"variant_rule":{"alt":[{"stem":"한 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X14"},{"t":"각기둥","mis":"M6-2-u6-X03"},{"t":"각뿔","mis":"M6-2-u6-X01"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","한 원을 면으로 하는 입체도형을 원뿔이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]},{"stem":"원기둥은 어떤 입체도형인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","correct":true},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X01"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X03"},{"t":"한 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["원기둥의 뜻을 떠올려요.","원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#2','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',1,'mc','auto','지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?',ARRAY['M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":2,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"지름을 따라 반으로 나눈 원 모양의 종이를 지름을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 구가 만들어져요."],"variant_rule":{"alt":[{"stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."]},{"stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#3','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C2',1,'mc','auto','원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?',ARRAY['M6-2-u6-X05','M6-2-u6-X15']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥에서 두 밑면 사이의 거리를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면 사이의 거리를 높이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."],"variant_rule":{"alt":[{"stem":"원기둥의 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X06"},{"t":"옆면의 둘레","mis":"M6-2-u6-X06"},{"t":"밑면의 반지름","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."]},{"stem":"원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","서로 평행하고 합동인 두 원을 밑면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#4','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',1,'mc','auto','원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?',ARRAY['M6-2-u6-X13','M6-2-u6-X02']::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 전개도는 어떤 도형 몇 개로 이루어져 있나요?","options":[{"t":"합동인 원 2개와 직사각형 1개","correct":true},{"t":"원 1개와 직사각형 1개","mis":"M6-2-u6-X13"},{"t":"합동인 원 2개와 직사각형 2개","mis":"M6-2-u6-X13"},{"t":"크기가 다른 원 2개와 직사각형 1개","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 밑면은 서로 합동인 원 2개예요.","옆면은 굽은 면 하나 — 펼치면 직사각형 1개예요.","그래서 합동인 원 2개와 직사각형 1개예요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"밑면의 둘레","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"원기둥의 높이","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X08"}],"explanation":["옆면을 다시 감아 붙이면 위쪽 테두리가 밑면의 둘레에 딱 맞아야 해요.","그래서 옆면의 가로는 밑면의 둘레와 같아요.","지름이 아니라 둘레예요."]},{"stem":"원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"원기둥의 전개도","correct":true},{"t":"원기둥의 겨냥도","mis":"M6-2-u6-X13"},{"t":"원기둥의 밑면","mis":"M6-2-u6-X13"},{"t":"원기둥의 옆면","mis":"M6-2-u6-X13"}],"explanation":["입체도형을 잘라 평면 위에 펼친 그림이 전개도예요.","겨냥도는 입체도형의 모양을 잘 알 수 있게 그린 그림이에요.","그래서 원기둥의 전개도예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#5','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',1,'mc','auto','원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 뾰족한 부분의 점을 무엇이라고 하나요?","options":[{"t":"원뿔의 꼭짓점","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","뾰족한 부분의 점을 원뿔의 꼭짓점이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 면이 되는 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","면이 되는 원을 밑면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#6','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',1,'mc','auto','돌리기 전 반원의 반지름은 만들어진 구의 무엇이 되나요?',ARRAY['M6-2-u6-X17','M6-2-u6-X04']::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"돌리기 전 반원의 반지름은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 반지름","correct":true},{"t":"구의 중심","mis":"M6-2-u6-X17"},{"t":"구의 지름","mis":"M6-2-u6-X04"},{"t":"구의 둘레","mis":"M6-2-u6-X17"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."],"variant_rule":{"alt":[{"stem":"원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X18"},{"t":"원뿔","mis":"M6-2-u6-X18"},{"t":"세 가지 모두","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."]},{"stem":"구는 어떻게 만든 입체도형인가요?","options":[{"t":"지름을 따라 반으로 나눈 원을 지름을 기준으로 한 바퀴 돌려서 만든 입체도형","correct":true},{"t":"직사각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"직각삼각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#7','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',1,'mc','auto','구를 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"구를 앞에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 구를 앞에서 본 모양은 원이에요."],"variant_rule":{"alt":[{"stem":"원기둥을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 위에서 본 모양은 원이에요."]},{"stem":"원뿔을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 앞에서 본 모양은 삼각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#8','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C2',1,'sa','auto','밑면의 반지름이 9 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"밑면의 반지름이 9 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["18"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","9 × 2 = 18 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","7 × 2 = 14 cm예요."]},{"stem":"밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#9','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C1',2,'sa','auto','가로 6 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 6 cm, 세로 9 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 높이는 몇 cm인가요?","answer":["9"],"explanation":["막대에 붙인 세로 9 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","그래서 높이는 9 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 8 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["막대에 붙인 세로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 5 cm예요."]},{"stem":"가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 3 × 2 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#10','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C1',2,'mc','auto','「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「두 원이 비스듬히 잘려 서로 평행하지 않은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 평행하지 않아서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 원이 비스듬히 잘려 서로 평행하지 않은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 평행하지 않아서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."]},{"stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#11','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":11,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 4 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 4 cm에 2를 곱해 지름 8 cm를 먼저 만들어요.","8 × 3.14 = 25.12 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 3 cm에 2를 곱해 지름 6 cm를 먼저 만들어요.","6 × 3.14 = 18.84 cm예요."]},{"stem":"밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","8 × 3.14 = 25.12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#12','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 21.98 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 21.98 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","21.98 ÷ 3.14 = 7 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","12.56 ÷ 3.14 = 4 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","25.12 ÷ 3.14 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#13','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C4',2,'mc','auto','「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X02']::text[],true,'{"seq":13,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「위쪽 원이 아래쪽 원보다 작은 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X02"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X02"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 서로 합동이 아니어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"밑면이 하나뿐이어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 밑면이 하나뿐이어서 전개도가 될 수 없어요."]},{"stem":"「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#14','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C5',2,'sa','auto','세 변이 5 cm, 12 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"세 변이 5 cm, 12 cm, 13 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 높이는 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","가장 긴 변 13 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 높이는 12 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 9 cm, 12 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 반지름은 몇 cm인가요?","answer":["9"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","가장 긴 변 15 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 밑면의 반지름은 9 cm예요."]},{"stem":"세 변이 3 cm, 4 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 4 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 변 4 cm는 원뿔의 높이, 뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","가장 긴 변 5 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 3 × 2 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#15','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 5 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 5 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 4 cm, 밑면의 반지름은 3 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["4"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 5 cm는 모선이에요.","그래서 높이는 4 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 17 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 15 cm는 높이예요.","그래서 모선은 17 cm예요."]},{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["8"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 10 cm는 모선이에요.","그래서 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#16','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',2,'sa','auto','원뿔 3개와 구 2개의 평평한 면은 모두 몇 개인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u6-C7","difficulty":2,"kind":"sa","stem":"원뿔 3개와 구 2개의 평평한 면은 모두 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원뿔 하나에 1개씩 3개, 구는 0개 — 3개예요."],"mis":"M6-2-u6-X07","variant_rule":{"alt":[{"stem":"원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?","answer":["3"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개와 원기둥 2개 — 1 + 2 = 3개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."]},{"stem":"원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 2개, 원뿔 1개, 구 0개 — 2 + 1 + 0 = 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#17','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C3',3,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 10 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm, 세로가 10 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["18"],"explanation":["지름은 25.12 ÷ 3.14 = 8 cm예요.","옆면의 세로가 높이 — 10 cm예요.","8 + 10 = 18 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 12 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["22"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","옆면의 세로가 높이 — 12 cm예요.","10 + 12 = 22 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["11"],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm예요.","옆면의 세로가 높이 — 5 cm예요.","6 + 5 = 11 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#18','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',3,'mc','auto','한 원뿔에서 모선의 길이는 어떤가요?',ARRAY['M6-2-u6-X16','M6-2-u6-X15']::text[],true,'{"seq":18,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"한 원뿔에서 모선의 길이는 어떤가요?","options":[{"t":"모두 같아요","correct":true},{"t":"모두 달라요","mis":"M6-2-u6-X16"},{"t":"둘레 쪽으로 갈수록 길어져요","mis":"M6-2-u6-X16"},{"t":"높이와 같아요","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"8 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 8 cm가 높이, 긴 10 cm가 모선이에요."]},{"stem":"원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?","options":[{"t":"모선은 둘레까지 비스듬히 가고 높이는 한가운데까지 곧게 가서","correct":true},{"t":"모선이 여러 개여서","mis":"M6-2-u6-X16"},{"t":"밑면이 원이어서","mis":"M6-2-u6-X15"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#19','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C7',3,'sa','auto','반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"반지름이 6 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 6 cm예요.","지름은 6 × 2 = 12 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 7 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["14"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 7 × 2 = 14 cm예요.","그래서 한 모서리는 14 cm예요."]},{"stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 4 cm예요.","지름은 4 × 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#20','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":20,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 지름이 12 cm, 높이가 8 cm, 모선이 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"96 cm²","mis":"M6-2-u6-X20"},{"t":"24 cm²","mis":"M6-2-u6-X20"},{"t":"60 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 12 cm, 높이는 원뿔의 높이 8 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 모선은 쓰지 않아요.","12 × 8 ÷ 2 = 48 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"72 cm²","correct":true},{"t":"144 cm²","mis":"M6-2-u6-X20"},{"t":"36 cm²","mis":"M6-2-u6-X20"},{"t":"88 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 16 cm, 높이는 원뿔의 높이 9 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","16 × 9 ÷ 2 = 72 cm²예요."]},{"stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"126 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","18 × 12 ÷ 2 = 108 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#21','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',3,'sa','auto','원기둥을 앞에서 본 직사각형의 넓이가 35 cm², 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원기둥을 앞에서 본 직사각형의 넓이가 35 cm², 세로가 5 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["7"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","35 ÷ 5 = 7 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 밑면의 지름이 10 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","10 × (높이) ÷ 2 = 30 — (높이) = 30 × 2 ÷ 10이에요.","30 × 2 ÷ 10 = 6 cm예요."]},{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","108 ÷ 9 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#22','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C4',3,'mc','auto','다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?',ARRAY['M6-2-u6-X12','M6-2-u6-X02','M6-2-u6-X11']::text[],true,'{"seq":22,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"직사각형의 위쪽 가운데와 아래쪽 가운데에 합동인 원이 하나씩 붙은 그림","correct":true},{"t":"직사각형의 위쪽에 합동인 원 두 개가 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"직사각형의 위쪽에 큰 원, 아래쪽에 작은 원이 붙은 그림","mis":"M6-2-u6-X02"},{"t":"기울어진 사각형의 위아래에 합동인 원이 하나씩 붙은 그림","mis":"M6-2-u6-X11"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."],"variant_rule":{"alt":[{"stem":"원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?","options":[{"t":"옆면을 사이에 두고 마주 보는 위치","correct":true},{"t":"옆면의 같은 쪽에 나란히","mis":"M6-2-u6-X12"},{"t":"옆면의 한가운데에 겹쳐서","mis":"M6-2-u6-X12"},{"t":"아무 곳에나","mis":"M6-2-u6-X12"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 옆면의 위와 아래에 하나씩 붙은 그림","correct":true},{"t":"옆면이 직사각형이고, 크기가 다른 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X02"},{"t":"옆면이 평행사변형이고, 크기가 같은 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X11"},{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 모두 위쪽에 붙은 그림","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#23','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',4,'sa','auto','밑면의 지름이 18 cm, 높이가 12 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 9 cm일 때 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 9 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 18 × 12 ÷ 2 = 108 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 108 cm² — 세로는 높이 9 cm예요.","가로(지름) = 108 ÷ 9 = 12 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 8 cm일 때 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 16 × 9 ÷ 2 = 72 cm²예요.","원기둥 모자의 앞모양도 72 cm² — 가로는 지름 8 cm예요.","세로(높이) = 72 ÷ 8 = 9 cm예요."]},{"stem":"밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 5 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 10 × 6 ÷ 2 = 30 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 30 cm² — 세로는 높이 5 cm예요.","가로(지름) = 30 ÷ 5 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#24','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C6',4,'essay','teacher','밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔이 있어요. 친구가 「이 원뿔의 높이는 10 cm야.」라고 말했어요. 친구의 말이 맞는지 판단하고, 모선과 높이의 차이를 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C6","difficulty":4,"kind":"essay","stem":"밑면의 반지름이 6 cm, 높이가 8 cm, 모선이 10 cm인 원뿔이 있어요. 친구가 「이 원뿔의 높이는 10 cm야.」라고 말했어요. 친구의 말이 맞는지 판단하고, 모선과 높이의 차이를 설명해 보세요.","answer_guide":{"answer":"예: 틀렸다. 10 cm는 원뿔의 꼭짓점과 밑면 둘레의 한 점을 이은 모선의 길이이다. 높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이로 8 cm이며, 모선은 비스듬히 가므로 높이보다 길다.","scoring_points":["친구의 말이 틀렸다고 판단했는가","10 cm는 모선, 8 cm가 높이임을 밝혔는가","모선과 높이의 뜻 차이를 썼는가"]},"explanation":["10 cm는 모선이에요.","높이는 수직으로 내린 8 cm예요.","모선은 비스듬히, 높이는 곧게 내려가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_c#25','math',6,2,'u6','','g6_2_math_u6_review_c','unit_review','M6-2-u6-C8',4,'essay','teacher','밑면의 지름이 12 cm, 높이가 8 cm인 원뿔과, 밑면의 지름이 12 cm, 높이가 8 cm인 원기둥을 앞에서 보았어요. 두 앞모양의 넓이를 각각 구하고 어떤 관계인지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C8","difficulty":4,"kind":"essay","stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔과, 밑면의 지름이 12 cm, 높이가 8 cm인 원기둥을 앞에서 보았어요. 두 앞모양의 넓이를 각각 구하고 어떤 관계인지 설명해 보세요.","answer_guide":{"answer":"예: 원뿔의 앞모양은 밑변 12 cm, 높이 8 cm인 삼각형이라 12 × 8 ÷ 2 = 48 cm², 원기둥의 앞모양은 가로 12 cm, 세로 8 cm인 직사각형이라 12 × 8 = 96 cm²이다. 밑변과 높이가 같으니 삼각형의 넓이는 직사각형 넓이의 반이다.","scoring_points":["삼각형 넓이 48 cm²를 구했는가","직사각형 넓이 96 cm²를 구했는가","삼각형이 직사각형의 반이라고 설명했는가"]},"explanation":["삼각형은 48 cm²예요.","직사각형은 96 cm²예요.","삼각형은 직사각형의 반이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#1','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C5',1,'mc','auto','한 원을 면으로 하는 입체도형을 무엇이라고 하나요?',ARRAY['M6-2-u6-X14','M6-2-u6-X03','M6-2-u6-X01']::text[],true,'{"seq":1,"concept":"M6-2-u6-C5","difficulty":1,"kind":"mc","stem":"한 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X14"},{"t":"각기둥","mis":"M6-2-u6-X03"},{"t":"각뿔","mis":"M6-2-u6-X01"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","한 원을 면으로 하는 입체도형을 원뿔이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."],"variant_rule":{"alt":[{"stem":"원기둥은 어떤 입체도형인가요?","options":[{"t":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형","correct":true},{"t":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형","mis":"M6-2-u6-X01"},{"t":"밑면이 다각형이고 옆면이 모두 삼각형인 입체도형","mis":"M6-2-u6-X03"},{"t":"한 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["원기둥의 뜻을 떠올려요.","원기둥은 서로 평행하고 합동인 두 원을 면으로 하는 입체도형이에요.","나머지는 다른 입체도형의 뜻이에요."]},{"stem":"서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 무엇이라고 하나요?","options":[{"t":"원기둥","correct":true},{"t":"각기둥","mis":"M6-2-u6-X01"},{"t":"각뿔","mis":"M6-2-u6-X03"},{"t":"원뿔","mis":"M6-2-u6-X14"}],"explanation":["밑면의 모양(원인지 다각형인지)과 원의 수를 봐요.","서로 평행하고 합동인 두 원을 면으로 하는 입체도형을 원기둥이라고 해요.","원기둥은 원 2개, 원뿔은 원 1개, 각기둥·각뿔은 밑면이 다각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#2','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',1,'mc','auto','직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?',ARRAY['M6-2-u6-X04','M6-2-u6-X06']::text[],true,'{"seq":2,"concept":"M6-2-u6-C1","difficulty":1,"kind":"mc","stem":"직사각형을 막대에 붙여 한 바퀴 돌릴 때, 막대에 붙인 변은 만들어진 원기둥의 무엇이 되나요?","options":[{"t":"높이","correct":true},{"t":"밑면의 반지름","mis":"M6-2-u6-X04"},{"t":"밑면의 지름","mis":"M6-2-u6-X04"},{"t":"밑면의 둘레","mis":"M6-2-u6-X06"}],"explanation":["막대가 돌리는 축이에요 — 축에 붙은 변은 위아래로 곧게 서 있어요.","그래서 막대에 붙인 변은 높이가 돼요.","뻗어 나간 변은 돌면서 원을 그려 밑면의 반지름이 돼요."],"variant_rule":{"alt":[{"stem":"직사각형 모양의 종이를 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원기둥","correct":true},{"t":"원뿔","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원기둥이 만들어져요."]},{"stem":"직각삼각형 모양의 종이를 직각을 낀 한 변을 기준으로 한 바퀴 돌렸어요. 어떤 입체도형이 만들어지나요?","options":[{"t":"원뿔","correct":true},{"t":"원기둥","mis":"M6-2-u6-X03"},{"t":"구","mis":"M6-2-u6-X03"},{"t":"사각기둥","mis":"M6-2-u6-X01"}],"explanation":["돌리는 평면도형에 따라 만들어지는 입체도형이 달라요.","직사각형은 원기둥, 직각삼각형은 원뿔, 반원은 구가 돼요.","그래서 원뿔이 만들어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#3','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C2',1,'mc','auto','원기둥의 높이는 무엇인가요?',ARRAY['M6-2-u6-X06']::text[],true,'{"seq":3,"concept":"M6-2-u6-C2","difficulty":1,"kind":"mc","stem":"원기둥의 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X06"},{"t":"옆면의 둘레","mis":"M6-2-u6-X06"},{"t":"밑면의 반지름","mis":"M6-2-u6-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","비스듬히 재면 거리보다 길게 나와요.","그래서 밑면에 수직으로 자와 삼각자를 대어 재요."],"variant_rule":{"alt":[{"stem":"원기둥에서 서로 평행하고 합동인 두 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","서로 평행하고 합동인 두 원을 밑면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]},{"stem":"원기둥에서 두 밑면과 만나는 굽은 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"높이","mis":"M6-2-u6-X06"},{"t":"모선","mis":"M6-2-u6-X15"}],"explanation":["원기둥에는 밑면·옆면·높이가 있어요.","두 밑면과 만나는 굽은 면을 옆면이라고 해요.","원기둥에는 꼭짓점과 모선이 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#4','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',1,'mc','auto','원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?',ARRAY['M6-2-u6-X08','M6-2-u6-X09']::text[],true,'{"seq":4,"concept":"M6-2-u6-C3","difficulty":1,"kind":"mc","stem":"원기둥의 전개도에서 옆면의 가로는 원기둥의 무엇과 길이가 같나요?","options":[{"t":"밑면의 둘레","correct":true},{"t":"밑면의 지름","mis":"M6-2-u6-X08"},{"t":"원기둥의 높이","mis":"M6-2-u6-X09"},{"t":"밑면의 반지름","mis":"M6-2-u6-X08"}],"explanation":["옆면을 다시 감아 붙이면 위쪽 테두리가 밑면의 둘레에 딱 맞아야 해요.","그래서 옆면의 가로는 밑면의 둘레와 같아요.","지름이 아니라 둘레예요."],"variant_rule":{"alt":[{"stem":"원기둥의 모든 면이 이어지도록 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"원기둥의 전개도","correct":true},{"t":"원기둥의 겨냥도","mis":"M6-2-u6-X13"},{"t":"원기둥의 밑면","mis":"M6-2-u6-X13"},{"t":"원기둥의 옆면","mis":"M6-2-u6-X13"}],"explanation":["입체도형을 잘라 평면 위에 펼친 그림이 전개도예요.","겨냥도는 입체도형의 모양을 잘 알 수 있게 그린 그림이에요.","그래서 원기둥의 전개도예요."]},{"stem":"원기둥의 전개도에서 밑면과 옆면은 각각 어떤 도형인가요?","options":[{"t":"밑면은 원, 옆면은 직사각형","correct":true},{"t":"밑면은 직사각형, 옆면은 원","mis":"M6-2-u6-X09"},{"t":"밑면은 원, 옆면은 삼각형","mis":"M6-2-u6-X13"},{"t":"밑면과 옆면 모두 원","mis":"M6-2-u6-X13"}],"explanation":["밑면은 원기둥의 두 원이에요.","굽은 옆면을 잘라 펼치면 직사각형이 돼요.","그래서 밑면은 원, 옆면은 직사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#5','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C6',1,'mc','auto','원뿔에서 면이 되는 원을 무엇이라고 하나요?',ARRAY['M6-2-u6-X15','M6-2-u6-X05']::text[],true,'{"seq":5,"concept":"M6-2-u6-C6","difficulty":1,"kind":"mc","stem":"원뿔에서 면이 되는 원을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","면이 되는 원을 밑면이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."],"variant_rule":{"alt":[{"stem":"원뿔에서 원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"모선","correct":true},{"t":"높이","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분을 모선이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]},{"stem":"원뿔에서 원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 무엇이라고 하나요?","options":[{"t":"높이","correct":true},{"t":"모선","mis":"M6-2-u6-X15"},{"t":"밑면","mis":"M6-2-u6-X05"},{"t":"옆면","mis":"M6-2-u6-X05"}],"explanation":["원뿔에는 밑면·옆면·원뿔의 꼭짓점·모선·높이가 있어요.","원뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이를 높이라고 해요.","모선은 둘레까지 비스듬히, 높이는 밑면에 수직으로 내려가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#6','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C7',1,'mc','auto','원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":6,"concept":"M6-2-u6-C7","difficulty":1,"kind":"mc","stem":"원기둥·원뿔·구 가운데 어느 방향에서 보아도 모양이 같은 입체도형은 무엇인가요?","options":[{"t":"구","correct":true},{"t":"원기둥","mis":"M6-2-u6-X18"},{"t":"원뿔","mis":"M6-2-u6-X18"},{"t":"세 가지 모두","mis":"M6-2-u6-X18"}],"explanation":["구는 한 점에서 같은 거리에 있는 점들로 이루어져 어느 쪽에서 보아도 원이에요.","원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞에서 보면 원기둥은 직사각형, 원뿔은 삼각형이에요."],"variant_rule":{"alt":[{"stem":"구는 어떻게 만든 입체도형인가요?","options":[{"t":"지름을 따라 반으로 나눈 원을 지름을 기준으로 한 바퀴 돌려서 만든 입체도형","correct":true},{"t":"직사각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"직각삼각형을 한 바퀴 돌려서 만든 입체도형","mis":"M6-2-u6-X03"},{"t":"합동인 두 원을 면으로 하는 입체도형","mis":"M6-2-u6-X14"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]},{"stem":"돌리기 전 반원의 중심은 만들어진 구의 무엇이 되나요?","options":[{"t":"구의 중심","correct":true},{"t":"구의 반지름","mis":"M6-2-u6-X17"},{"t":"구의 밑면","mis":"M6-2-u6-X07"},{"t":"구의 꼭짓점","mis":"M6-2-u6-X07"}],"explanation":["반원을 지름을 기준으로 한 바퀴 돌리면 구가 돼요.","원의 중심은 구의 중심, 원의 반지름은 구의 반지름이 돼요.","구의 중심은 1개, 구의 반지름은 무수히 많고 길이가 모두 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#7','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',1,'mc','auto','원기둥을 위에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u6-X18']::text[],true,'{"seq":7,"concept":"M6-2-u6-C8","difficulty":1,"kind":"mc","stem":"원기둥을 위에서 본 모양은 어느 것인가요?","options":[{"t":"원","correct":true},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 위에서 본 모양은 원이에요."],"variant_rule":{"alt":[{"stem":"원뿔을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"직사각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원뿔을 앞에서 본 모양은 삼각형이에요."]},{"stem":"원기둥을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"원","mis":"M6-2-u6-X18"},{"t":"삼각형","mis":"M6-2-u6-X18"},{"t":"반원","mis":"M6-2-u6-X18"}],"explanation":["원기둥·원뿔·구를 위에서 보면 모두 원이에요.","앞과 옆에서 보면 원기둥은 직사각형, 원뿔은 삼각형, 구는 원이에요.","그래서 원기둥을 앞에서 본 모양은 직사각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#8','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C2',1,'sa','auto','밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M6-2-u6-C2","difficulty":1,"kind":"sa","stem":"밑면의 반지름이 7 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["14"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","7 × 2 = 14 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"밑면의 반지름이 4 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","4 × 2 = 8 cm예요."]},{"stem":"밑면의 반지름이 6 cm인 원기둥이 있어요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["밑면은 원이에요.","지름은 반지름의 2배예요.","6 × 2 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#9','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',2,'sa','auto','가로 5 cm, 세로 8 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M6-2-u6-C1","difficulty":2,"kind":"sa","stem":"가로 5 cm, 세로 8 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 반지름은 몇 cm인가요?","answer":["5"],"explanation":["막대에 붙인 세로 8 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 5 cm는 밑면의 반지름이 돼요.","그래서 밑면의 반지름은 5 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"가로 3 cm, 세로 5 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 세로 5 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 3 × 2 = 6 cm예요."]},{"stem":"가로 4 cm, 세로 7 cm인 직사각형 모양의 종이를 세로를 막대에 붙이고 한 바퀴 돌려 원기둥을 만들었어요. 만들어진 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["막대에 붙인 세로 7 cm는 원기둥의 높이가 돼요.","뻗어 나간 변 4 cm는 밑면의 반지름이 돼요.","지름은 반지름의 2배 — 4 × 2 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#10','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C1',2,'mc','auto','「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u6-X14']::text[],true,'{"seq":10,"concept":"M6-2-u6-C1","difficulty":2,"kind":"mc","stem":"「한 원과 뾰족한 점이 있는 고깔」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"원이 하나뿐이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X14"},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X14"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X14"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「한 원과 뾰족한 점이 있는 고깔」을 이 조건에 하나씩 대어 봐요.","원이 하나뿐이어서 원기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」은 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 원이 서로 합동이 아니어서","correct":true},{"t":"두 면이 원이 아니라 다각형이어서","mis":"M6-2-u6-X02"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X02"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X02"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 원인데 위쪽 원이 아래쪽 원보다 작은 통」을 이 조건에 하나씩 대어 봐요.","두 원이 서로 합동이 아니어서 원기둥이 아니에요."]},{"stem":"「두 면이 서로 평행하고 합동인 육각형인 상자」는 원기둥이 아니에요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 면이 원이 아니라 다각형이어서","correct":true},{"t":"두 원이 서로 합동이 아니어서","mis":"M6-2-u6-X01"},{"t":"두 원이 서로 평행하지 않아서","mis":"M6-2-u6-X01"},{"t":"원이 하나뿐이어서","mis":"M6-2-u6-X01"}],"explanation":["원기둥은 서로 평행하고 합동인 두 원을 면으로 해요.","「두 면이 서로 평행하고 합동인 육각형인 상자」를 이 조건에 하나씩 대어 봐요.","두 면이 원이 아니라 다각형이어서 원기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#11','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',2,'mc','auto','밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?',ARRAY['M6-2-u6-X08','M6-2-u6-X10']::text[],true,'{"seq":11,"concept":"M6-2-u6-C3","difficulty":2,"kind":"mc","stem":"밑면의 반지름이 3 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"18.84 cm","correct":true},{"t":"9.42 cm","mis":"M6-2-u6-X08"},{"t":"6 cm","mis":"M6-2-u6-X08"},{"t":"37.68 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","반지름 3 cm에 2를 곱해 지름 6 cm를 먼저 만들어요.","6 × 3.14 = 18.84 cm예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 8 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"25.12 cm","correct":true},{"t":"8 cm","mis":"M6-2-u6-X08"},{"t":"12.56 cm","mis":"M6-2-u6-X08"},{"t":"50.24 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","8 × 3.14 = 25.12 cm예요."]},{"stem":"밑면의 지름이 5 cm인 원기둥의 전개도에서 옆면의 가로는 몇 cm인가요?","options":[{"t":"15.7 cm","correct":true},{"t":"5 cm","mis":"M6-2-u6-X08"},{"t":"7.85 cm","mis":"M6-2-u6-X08"},{"t":"31.4 cm","mis":"M6-2-u6-X10"}],"explanation":["옆면의 가로는 밑면의 둘레예요.","(밑면의 둘레) = (지름) × 3.14예요.","5 × 3.14 = 15.7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#12','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',2,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?','{}'::text[],true,'{"seq":12,"concept":"M6-2-u6-C3","difficulty":2,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["4"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","12.56 ÷ 3.14 = 4 cm예요."],"mis":"M6-2-u6-X10","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 25.12 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","25.12 ÷ 3.14 = 8 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["옆면의 가로는 밑면의 둘레예요.","(지름) = (둘레) ÷ 3.14예요.","18.84 ÷ 3.14 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#13','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C4',2,'mc','auto','「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M6-2-u6-X13']::text[],true,'{"seq":13,"concept":"M6-2-u6-C4","difficulty":2,"kind":"mc","stem":"「원 1개와 직사각형 1개로 된 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"밑면이 하나뿐이어서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X13"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X13"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 밑면이 하나뿐이어서 전개도가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"「옆면이 비스듬히 기울어진 평행사변형인 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니어서","correct":true},{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","mis":"M6-2-u6-X11"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X11"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X11"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 옆면이 직사각형이 아니어서 전개도가 될 수 없어요."]},{"stem":"「두 원이 옆면의 같은 쪽에 나란히 붙어 있는 그림」은 원기둥의 전개도가 될 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서","correct":true},{"t":"옆면이 직사각형이 아니어서","mis":"M6-2-u6-X12"},{"t":"두 밑면이 서로 합동이 아니어서","mis":"M6-2-u6-X12"},{"t":"밑면이 하나뿐이어서","mis":"M6-2-u6-X12"}],"explanation":["원기둥의 전개도가 되려면 세 가지가 필요해요.","옆면이 직사각형, 두 밑면이 합동인 원, 두 밑면이 마주 보는 위치예요.","이 그림은 두 밑면이 마주 보는 위치에 있지 않아 접으면 겹쳐서 전개도가 될 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#14','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C5',2,'sa','auto','세 변이 9 cm, 12 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 반지름은 몇 cm인가요?','{}'::text[],true,'{"seq":14,"concept":"M6-2-u6-C5","difficulty":2,"kind":"sa","stem":"세 변이 9 cm, 12 cm, 15 cm인 직각삼각형 모양의 종이가 있어요. 길이가 12 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 반지름은 몇 cm인가요?","answer":["9"],"explanation":["막대에 붙인 변 12 cm는 원뿔의 높이, 뻗어 나간 변 9 cm는 밑면의 반지름이 돼요.","가장 긴 변 15 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","그래서 밑면의 반지름은 9 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"세 변이 3 cm, 4 cm, 5 cm인 직각삼각형 모양의 종이가 있어요. 길이가 4 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["막대에 붙인 변 4 cm는 원뿔의 높이, 뻗어 나간 변 3 cm는 밑면의 반지름이 돼요.","가장 긴 변 5 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 3 × 2 = 6 cm예요."]},{"stem":"세 변이 6 cm, 8 cm, 10 cm인 직각삼각형 모양의 종이가 있어요. 길이가 8 cm인 변을 막대에 붙이고 한 바퀴 돌려 원뿔을 만들었어요. 만들어진 원뿔의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["막대에 붙인 변 8 cm는 원뿔의 높이, 뻗어 나간 변 6 cm는 밑면의 반지름이 돼요.","가장 긴 변 10 cm는 꼭짓점과 밑면의 둘레를 이어 모선이 돼요.","지름은 6 × 2 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#15','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 17 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":15,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 17 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 15 cm, 밑면의 반지름은 8 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["17"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 15 cm는 높이예요.","그래서 모선은 17 cm예요."],"mis":"M6-2-u6-X15","variant_rule":{"alt":[{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 10 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 8 cm, 밑면의 반지름은 6 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["8"],"explanation":["높이는 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","꼭짓점과 둘레의 한 점을 이은 10 cm는 모선이에요.","그래서 높이는 8 cm예요."]},{"stem":"원뿔에서 꼭짓점과 밑면의 둘레의 한 점을 이은 선분은 13 cm, 꼭짓점에서 밑면에 수직으로 내린 선분은 12 cm, 밑면의 반지름은 5 cm예요. 이 원뿔의 모선의 길이는 몇 cm인가요?","answer":["13"],"explanation":["모선은 꼭짓점과 밑면인 원의 둘레의 한 점을 이은 선분이에요.","수직으로 내린 12 cm는 높이예요.","그래서 모선은 13 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#16','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C6',2,'sa','auto','원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?','{}'::text[],true,'{"seq":16,"concept":"M6-2-u6-C6","difficulty":2,"kind":"sa","stem":"원뿔의 밑면의 수와 원기둥의 밑면의 수를 더하면 모두 몇 개인가요?","answer":["3"],"explanation":["원뿔은 밑면이 1개, 뾰족한 꼭짓점이 1개예요.","원뿔 1개와 원기둥 2개 — 1 + 2 = 3개예요.","원기둥은 밑면 2개에 꼭짓점이 없고, 구는 평평한 면도 꼭짓점도 없어요."],"mis":"M6-2-u6-X05","variant_rule":{"alt":[{"stem":"원기둥·원뿔·구의 평평한 면의 수를 모두 더하면 몇 개인가요?","answer":["3"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 2개, 원뿔 1개, 구 0개 — 2 + 1 + 0 = 3개예요."]},{"stem":"원기둥 2개와 원뿔 1개의 평평한 면은 모두 몇 개인가요?","answer":["5"],"explanation":["평평한 면은 원기둥 2개(두 밑면), 원뿔 1개(밑면), 구 0개예요.","구는 굽은 면으로만 이루어져 있어요.","원기둥 하나에 2개씩 4개, 원뿔 1개 — 4 + 1 = 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#17','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C3',3,'sa','auto','어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 12 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?','{}'::text[],true,'{"seq":17,"concept":"M6-2-u6-C3","difficulty":3,"kind":"sa","stem":"어떤 원기둥의 전개도에서 옆면의 가로가 31.4 cm, 세로가 12 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["22"],"explanation":["지름은 31.4 ÷ 3.14 = 10 cm예요.","옆면의 세로가 높이 — 12 cm예요.","10 + 12 = 22 cm예요."],"mis":"M6-2-u6-X09","variant_rule":{"alt":[{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 18.84 cm, 세로가 5 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["11"],"explanation":["지름은 18.84 ÷ 3.14 = 6 cm예요.","옆면의 세로가 높이 — 5 cm예요.","6 + 5 = 11 cm예요."]},{"stem":"어떤 원기둥의 전개도에서 옆면의 가로가 12.56 cm, 세로가 9 cm예요. 이 원기둥의 밑면의 지름과 높이를 더하면 몇 cm인가요?","answer":["13"],"explanation":["지름은 12.56 ÷ 3.14 = 4 cm예요.","옆면의 세로가 높이 — 9 cm예요.","4 + 9 = 13 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#18','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C6',3,'mc','auto','한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?',ARRAY['M6-2-u6-X15','M6-2-u6-X16','M6-2-u6-X19']::text[],true,'{"seq":18,"concept":"M6-2-u6-C6","difficulty":3,"kind":"mc","stem":"한 원뿔에서 두 선분의 길이가 8 cm와 10 cm예요. 이 원뿔의 높이는 어느 것인가요?","options":[{"t":"8 cm","correct":true},{"t":"10 cm","mis":"M6-2-u6-X15"},{"t":"두 선분 모두 높이예요","mis":"M6-2-u6-X16"},{"t":"알 수 없어요","mis":"M6-2-u6-X19"}],"explanation":["원뿔에서 모선은 높이보다 길어요.","모선은 둘레까지 비스듬히, 높이는 한가운데까지 곧게 가요.","그래서 짧은 8 cm가 높이, 긴 10 cm가 모선이에요."],"variant_rule":{"alt":[{"stem":"원뿔의 모선이 높이보다 긴 까닭은 무엇인가요?","options":[{"t":"모선은 둘레까지 비스듬히 가고 높이는 한가운데까지 곧게 가서","correct":true},{"t":"모선이 여러 개여서","mis":"M6-2-u6-X16"},{"t":"밑면이 원이어서","mis":"M6-2-u6-X15"},{"t":"높이를 잴 수 없어서","mis":"M6-2-u6-X15"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]},{"stem":"원뿔의 모선은 몇 개인가요?","options":[{"t":"무수히 많아요","correct":true},{"t":"1개","mis":"M6-2-u6-X16"},{"t":"2개","mis":"M6-2-u6-X16"},{"t":"4개","mis":"M6-2-u6-X16"}],"explanation":["모선은 꼭짓점과 밑면 둘레의 한 점을 이어요 — 둘레의 점마다 하나씩, 무수히 많아요.","꼭짓점에서 둘레까지의 거리는 어디나 같아 모선의 길이도 모두 같아요.","모선은 비스듬히 둘레까지 가니 곧게 내린 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#19','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C7',3,'sa','auto','반지름이 7 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?','{}'::text[],true,'{"seq":19,"concept":"M6-2-u6-C7","difficulty":3,"kind":"sa","stem":"반지름이 7 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["14"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 7 × 2 = 14 cm예요.","그래서 한 모서리는 14 cm예요."],"mis":"M6-2-u6-X04","variant_rule":{"alt":[{"stem":"반지름이 4 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 이 구를 중심을 지나게 반으로 자른 면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["구의 중심을 지나게 자른 면은 반지름이 구의 반지름과 같은 원이에요.","그 원의 반지름은 4 cm예요.","지름은 4 × 2 = 8 cm예요."]},{"stem":"반지름이 5 cm인 구가 정육면체 상자에 꼭 맞게 들어가요. 정육면체의 한 모서리는 몇 cm인가요?","answer":["10"],"explanation":["구가 상자에 꼭 맞으면 마주 보는 두 면 사이가 구의 지름이에요.","구의 지름은 5 × 2 = 10 cm예요.","그래서 한 모서리는 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#20','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',3,'mc','auto','밑면의 지름이 16 cm, 높이가 9 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?',ARRAY['M6-2-u6-X20','M6-2-u6-X15']::text[],true,'{"seq":20,"concept":"M6-2-u6-C8","difficulty":3,"kind":"mc","stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"72 cm²","correct":true},{"t":"144 cm²","mis":"M6-2-u6-X20"},{"t":"36 cm²","mis":"M6-2-u6-X20"},{"t":"88 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 16 cm, 높이는 원뿔의 높이 9 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","16 × 9 ÷ 2 = 72 cm²예요."],"variant_rule":{"alt":[{"stem":"밑면의 지름이 18 cm, 높이가 12 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"108 cm²","correct":true},{"t":"216 cm²","mis":"M6-2-u6-X20"},{"t":"54 cm²","mis":"M6-2-u6-X20"},{"t":"126 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 18 cm, 높이는 원뿔의 높이 12 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","18 × 12 ÷ 2 = 108 cm²예요."]},{"stem":"밑면의 지름이 14 cm, 높이가 10 cm인 원뿔을 앞에서 보았어요. 앞에서 본 삼각형의 넓이는 몇 cm²인가요?","options":[{"t":"70 cm²","correct":true},{"t":"140 cm²","mis":"M6-2-u6-X20"},{"t":"35 cm²","mis":"M6-2-u6-X20"},{"t":"84 cm²","mis":"M6-2-u6-X15"}],"explanation":["밑변은 밑면의 지름 14 cm, 높이는 원뿔의 높이 10 cm예요.","삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","14 × 10 ÷ 2 = 70 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#21','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',3,'sa','auto','원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 밑면의 지름이 10 cm예요. 이 원뿔의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":21,"concept":"M6-2-u6-C8","difficulty":3,"kind":"sa","stem":"원뿔을 앞에서 본 삼각형의 넓이가 30 cm²이고, 원뿔의 밑면의 지름이 10 cm예요. 이 원뿔의 높이는 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","10 × (높이) ÷ 2 = 30 — (높이) = 30 × 2 ÷ 10이에요.","30 × 2 ÷ 10 = 6 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 108 cm², 세로가 9 cm예요. 이 원기둥의 밑면의 지름은 몇 cm인가요?","answer":["12"],"explanation":["앞에서 본 직사각형의 세로는 높이, 가로는 밑면의 지름이에요.","(가로) = (넓이) ÷ (세로)예요.","108 ÷ 9 = 12 cm예요."]},{"stem":"원기둥을 앞에서 본 직사각형의 넓이가 48 cm², 가로가 8 cm예요. 이 원기둥의 높이는 몇 cm인가요?","answer":["6"],"explanation":["앞에서 본 직사각형의 가로는 밑면의 지름, 세로는 높이예요.","(세로) = (넓이) ÷ (가로)예요.","48 ÷ 8 = 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#22','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C4',3,'mc','auto','원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?',ARRAY['M6-2-u6-X12']::text[],true,'{"seq":22,"concept":"M6-2-u6-C4","difficulty":3,"kind":"mc","stem":"원기둥의 전개도에서 두 밑면은 어디에 있어야 하나요?","options":[{"t":"옆면을 사이에 두고 마주 보는 위치","correct":true},{"t":"옆면의 같은 쪽에 나란히","mis":"M6-2-u6-X12"},{"t":"옆면의 한가운데에 겹쳐서","mis":"M6-2-u6-X12"},{"t":"아무 곳에나","mis":"M6-2-u6-X12"}],"explanation":["옆면을 감으면 둥근 통이 돼요.","그 통의 위쪽과 아래쪽을 각각 막아야 해요.","그래서 두 밑면은 서로 합동인 원이고 옆면을 사이에 두고 마주 보아야 해요."],"variant_rule":{"alt":[{"stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 옆면의 위와 아래에 하나씩 붙은 그림","correct":true},{"t":"옆면이 직사각형이고, 크기가 다른 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X02"},{"t":"옆면이 평행사변형이고, 크기가 같은 두 원이 위와 아래에 하나씩 붙은 그림","mis":"M6-2-u6-X11"},{"t":"옆면이 직사각형이고, 크기가 같은 두 원이 모두 위쪽에 붙은 그림","mis":"M6-2-u6-X12"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]},{"stem":"다음 가운데 원기둥의 전개도가 될 수 있는 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 원이 직사각형 옆면을 사이에 두고 마주 붙은 그림","correct":true},{"t":"크기가 같은 두 원이 직사각형 옆면의 한쪽에 나란히 붙은 그림","mis":"M6-2-u6-X12"},{"t":"원 하나가 직사각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"},{"t":"크기가 같은 두 원이 삼각형 옆면에 붙은 그림","mis":"M6-2-u6-X13"}],"explanation":["옆면은 직사각형이어야 해요.","두 밑면은 서로 합동인 원이어야 해요.","두 밑면은 옆면을 사이에 두고 마주 보는 위치에 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#23','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C8',4,'sa','auto','밑면의 지름이 16 cm, 높이가 9 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 8 cm일 때 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":23,"concept":"M6-2-u6-C8","difficulty":4,"kind":"sa","stem":"밑면의 지름이 16 cm, 높이가 9 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 밑면의 지름이 8 cm일 때 높이는 몇 cm인가요?","answer":["9"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 16 × 9 ÷ 2 = 72 cm²예요.","원기둥 모자의 앞모양도 72 cm² — 가로는 지름 8 cm예요.","세로(높이) = 72 ÷ 8 = 9 cm예요."],"mis":"M6-2-u6-X20","variant_rule":{"alt":[{"stem":"밑면의 지름이 10 cm, 높이가 6 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 5 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["6"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 10 × 6 ÷ 2 = 30 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 30 cm² — 세로는 높이 5 cm예요.","가로(지름) = 30 ÷ 5 = 6 cm예요."]},{"stem":"밑면의 지름이 12 cm, 높이가 8 cm인 원뿔 모자와 원기둥 모자를 앞에서 본 모양의 넓이가 같아요. 원기둥 모자의 높이가 6 cm일 때 밑면의 지름은 몇 cm인가요?","answer":["8"],"explanation":["원뿔 모자를 앞에서 본 삼각형의 넓이는 12 × 8 ÷ 2 = 48 cm²예요.","원기둥 모자를 앞에서 본 직사각형도 48 cm² — 세로는 높이 6 cm예요.","가로(지름) = 48 ÷ 6 = 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#24','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C7',4,'essay','teacher','반지름이 5 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 구의 중심·구의 반지름이 무엇에서 생겼는지 쓰고, 이 구가 꼭 맞게 들어가는 정육면체 상자의 한 모서리를 구해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-2-u6-C7","difficulty":4,"kind":"essay","stem":"반지름이 5 cm인 반원을 지름을 기준으로 한 바퀴 돌려 구를 만들었어요. 구의 중심·구의 반지름이 무엇에서 생겼는지 쓰고, 이 구가 꼭 맞게 들어가는 정육면체 상자의 한 모서리를 구해 보세요.","answer_guide":{"answer":"예: 돌리기 전 반원의 중심이 구의 중심(1개)이 되고, 반원의 반지름이 구의 반지름(무수히 많고 길이 5 cm로 모두 같음)이 된다. 상자에 꼭 맞으면 한 모서리는 구의 지름과 같으므로 5 × 2 = 10 cm이다.","scoring_points":["반원의 중심 → 구의 중심을 썼는가","반원의 반지름 → 구의 반지름(모두 같음)을 썼는가","한 모서리 10 cm를 구했는가"]},"explanation":["반원의 중심이 구의 중심이에요.","반원의 반지름이 구의 반지름 — 모두 5 cm예요.","한 모서리는 지름 10 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u6_review_d#25','math',6,2,'u6','','g6_2_math_u6_review_d','unit_review','M6-2-u6-C5',4,'essay','teacher','세 변이 6 cm, 8 cm, 10 cm인 직각삼각형을 8 cm인 변을 막대에 붙여 한 바퀴 돌렸어요. 만들어진 원뿔의 높이·밑면의 지름·모선의 길이를 각각 쓰고 그렇게 되는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-2-u6-C5","difficulty":4,"kind":"essay","stem":"세 변이 6 cm, 8 cm, 10 cm인 직각삼각형을 8 cm인 변을 막대에 붙여 한 바퀴 돌렸어요. 만들어진 원뿔의 높이·밑면의 지름·모선의 길이를 각각 쓰고 그렇게 되는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 막대에 붙인 8 cm 변은 원뿔의 높이가 된다. 뻗어 나간 6 cm 변은 돌면서 원을 그려 밑면의 반지름이 되므로 지름은 12 cm이다. 가장 긴 10 cm 변은 꼭짓점과 밑면 둘레를 이어 모선이 된다.","scoring_points":["높이 8 cm를 썼는가","반지름 6 cm → 지름 12 cm를 썼는가","모선 10 cm와 그 까닭을 썼는가"]},"explanation":["붙인 변 8 cm = 높이예요.","뻗은 변 6 cm = 반지름 → 지름 12 cm예요.","빗변 10 cm = 모선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
